window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0022", [{"word":"maximize","ipa_uk":"/ˈmæksɪmaɪz/","ipa_us":"/ˈmæksəmaɪz/","definition_zh":"使最大化；使增至最大；充分利用；把……发挥到极致","definition_en":"to make something as great, large, or effective as it can possibly be","core_image":"把一只旋钮拧到刻度盘最右端、直到再也拧不动的顶点","scene":"The plant manager turned every dial to its limit to maximize output before the export deadline.","sceneCN":"这里 maximize 是「把产量推到最高」（第 3 个义项：把产出、效率推到最高）；句意：出口截止日前，厂长把每一个旋钮都拧到极限，以把产量推到最高。场景要点：车间里的控制台、一排拧到头的旋钮、堆到天花板的成品箱。","pos":[{"tag":"vt.","zh":"使最大化；使增至最大"},{"tag":"vt.","zh":"充分利用；把……发挥到极致"}],"collocations":[{"phrase":"maximize profit","zh":"使利润最大化"},{"phrase":"maximize efficiency","zh":"使效率最大化"},{"phrase":"maximize output","zh":"使产量最大化"},{"phrase":"maximize the impact of","zh":"使……的影响最大化"},{"phrase":"maximize returns","zh":"使收益最大化"},{"phrase":"maximize the chance of success","zh":"把成功的机会做到最大"},{"phrase":"maximize the use of resources","zh":"充分利用资源"}],"forms":[{"label":"三单（he/she/it）","form":"maximizes"},{"label":"过去式（已经发生）","form":"maximized"},{"label":"过去分词（完成／被动）","form":"maximized"},{"label":"现在分词（进行体）","form":"maximizing"}],"derivatives":[{"word":"maximum","pos":"n./adj.","zh":"最大值；最大限度；最大的"},{"word":"maximal","pos":"adj.","zh":"最大的；达到最大限度的"},{"word":"maximization","pos":"n.","zh":"最大化；最大化过程"},{"word":"maximizer","pos":"n.","zh":"追求最大化的人；最大化者"},{"word":"max","pos":"v./n./adj.","zh":"达到最高水平；最大值；最大的（口语缩略）"}],"senses":[{"no":"01","title":"Reach the mathematical maximum","titleCN":"数学上取最大值","definition":"to find or reach the highest value of a function, quantity, or variable","definitionCN":"求取或达到函数、数量、变量的最高值","example":"To maximize the function, set its derivative to zero.","exampleCN":"要使这个函数取最大值，把它的导数设为零。","why":"Latin maximus names the top point of a scale. The verb makes an object arrive at that point, so the mathematical sense is the image in its plainest form.","whyCN":"拉丁语 maximus 指刻度上的顶点。这个动词让对象抵达那个点，因此数学义是这幅意象最朴素的形态。"},{"no":"02","title":"Profit: make the return as large as possible","titleCN":"利润：把回报做到最大","definition":"to make profit, revenue, or financial return as large as the situation allows","definitionCN":"在条件允许的范围内把利润、收入或财务回报做到最大","example":"The firm cut staff and raised prices to maximize profit.","exampleCN":"公司裁减员工并提高价格，以使利润最大化。","why":"Profit is a quantity on a dial. Turning that dial to the right end is the business version of the same gesture, and it is the sense that dominates business writing.","whyCN":"利润是刻度盘上的一个量。把这只旋钮拧到最右端，就是同一个动作在商业里的版本，也是商业写作中最常见的义项。"},{"no":"03","title":"Output and efficiency: run everything at full capacity","titleCN":"产出与效率：全力运转","definition":"to make production or efficiency as high as the equipment and time allow","definitionCN":"在设备与时间允许的范围内把产量或效率做到最高","example":"The mill maximized output by running three shifts.","exampleCN":"这家工厂实行三班倒，把产量推到最高。","why":"Output is what a machine yields. Maximizing it means no capacity is left unused, so the top of the scale is also the point of full employment.","whyCN":"产量是机器产出的东西。把它最大化，意味着没有一寸产能被闲置，因此刻度的顶点也是“全部投入使用”的那一点。"},{"no":"04","title":"Impact and effect: make it land as hard as possible","titleCN":"影响与效果：让冲击达到最远","definition":"to make the effect or influence of something as strong and wide as possible","definitionCN":"把某事物的效果或影响力做到最强、最广","example":"The campaign was designed to maximize its impact on young voters.","exampleCN":"这场宣传活动旨在把对年轻选民的影响做到最大。","why":"Effect is a force that travels. Pushing it to its greatest reach applies the same top-of-scale image to influence rather than to a number.","whyCN":"效果是一种会传播的力量。把它推到最远的射程，就是把同一个“刻度到顶”的意象用在影响力上，而不是用在数字上。"},{"no":"05","title":"Chance and probability: make the odds as good as possible","titleCN":"机会与概率：把胜算做到最大","definition":"to make the likelihood of a desired result as high as possible","definitionCN":"把期望结果出现的可能性做到最高","example":"Apply early to maximize your chance of getting a place.","exampleCN":"尽早申请，以把获得名额的机会做到最大。","why":"Probability is a number between zero and one. Maximizing it moves that number toward one, the upper end of its own small scale.","whyCN":"概率是零到一之间的数。最大化就是把这个数推向一，也就是它自己那一小段刻度的上端。"},{"no":"06","title":"Use resources fully: leave nothing idle","titleCN":"利用资源：不让任何一份闲置","definition":"to use a resource, space, or opportunity as fully as possible","definitionCN":"把资源、空间或机会尽可能充分地用尽","example":"The new timetable maximizes the use of the existing trains.","exampleCN":"新的时刻表把现有列车的利用率做到最高。","why":"A resource has a capacity. Maximizing means every unit of it is put to work, so the scale is measured in unused capacity rather than in output.","whyCN":"资源有容量。最大化意味着它的每一个单位都被投入使用，因此这把尺子量的是“还剩多少没用”，而不是产量。"},{"no":"07","title":"Computing: enlarge a window to fill the screen","titleCN":"计算机：把窗口放到满屏","definition":"to enlarge a window on a screen until it fills the available display area","definitionCN":"把屏幕上的窗口放大到占满可用的显示区域","example":"Double-click the title bar to maximize the window.","exampleCN":"双击标题栏即可把窗口最大化。","why":"A window has a size scale whose ceiling is the screen. The command drives the window to that ceiling, making the metaphor visible as a button.","whyCN":"窗口有一个尺寸刻度，它的天花板就是屏幕。这个命令把窗口推到那层天花板，让比喻变成了一个可见的按钮。"},{"no":"08","title":"Biology: make fitness as high as possible","titleCN":"生物学：把适应度推到最高","definition":"in evolutionary biology, to increase reproductive fitness to the highest level available in an environment","definitionCN":"在演化生物学中，把繁殖适应度提高到环境所允许的最高水平","example":"Natural selection maximizes fitness in a given environment.","exampleCN":"自然选择会把适应度在特定环境中推到最高。","why":"Evolutionary fitness is a score attached to a trait. Selection pushes that score toward its highest attainable value, exactly as a dial is turned to its stop.","whyCN":"演化适应度是附在某个性状上的分数。选择把这个分数推向可达到的最高值，正像把旋钮拧到它的止点。"},{"no":"09","title":"Push a feature to an extreme, often at a cost","titleCN":"把某一特征推到极端，往往付出代价","definition":"to make one feature or quantity as extreme as possible, usually by sacrificing something else","definitionCN":"把某一特征或数量做到尽可能极端，通常以牺牲其他方面为代价","example":"The design maximizes contrast and ignores comfort.","exampleCN":"这个设计把对比度做到最大，却不顾舒适度。","why":"When one quantity is driven to its top, everything else is subordinated to it. The word then carries a warning about single-minded extremes.","whyCN":"当一个量被推到顶端，其他一切都得服从它。于是这个词带上了一层警告：只顾一头的极端做法。"}],"etymology":{"intro":{"en":"Maximize is a transparent English coinage of 1802, built on maximum plus -ize; the Latin pieces behind maximum are well documented. Dates are those given by standard etymological references.","cn":"maximize 是 1802 年由英语自造的词，构词清楚：maximum 加 -ize；maximum 背后的拉丁语成分有明确记载。年代采用通行词源资料给出的说法。"},"items":[{"era":"1802","en":"First recorded in English meaning 'to make as great as possible, raise to the highest degree'. It is an English formation from maximum + -ize, and Bentham is the first attested user.","cn":"英语中最早记录于 1802 年，意为“使尽可能大、提高到最高程度”。它是由 maximum 加 -ize 构成的英语自造词，边沁是最早可考的使用者。"},{"era":"1740","en":"Maximum entered English from French maximum and directly from Latin maximum, the neuter form of maximus 'greatest'. The noun supplied the base for the later verb.","cn":"maximum 于 1740 年经法语 maximum 并直接由拉丁语 maximum 进入英语，后者是 maximus“最大的”的中性形式。这个名词为后来的动词提供了词基。"},{"era":"LATIN","en":"Latin maximus is the superlative of magnus 'great, large, big', and it belongs to the same scale as minor and minimus at the other end.","cn":"拉丁语 maximus 是 magnus“大的、巨大的”的最高级，它与另一端的 minor、minimus 同属一把尺子。"},{"era":"PIE","en":"Maximus goes back to PIE *mag-samo-, the superlative form of *meg- 'great', the root also behind magnify, magnitude and magnate.","cn":"maximus 可追溯到原始印欧语 *mag-samo-，即 *meg-“大”的最高级形式；该词根也是 magnify、magnitude、magnate 的来源。"},{"era":"BENTHAM","en":"Jeremy Bentham used maximize repeatedly in his utilitarian writing. The twin minimize is recorded in the same year and with the same author, so the two verbs were coined as a matching pair.","cn":"杰里米·边沁在功利主义写作中反复使用 maximize。与之配对的 minimize 记录于同一年、同样出自他手，因此这两个动词是一套成对造出来的。"},{"era":"MODERN ENGLISH","en":"British spelling is maximise. Maximization, maximizer and the clipped max (as a verb by 1986) complete the family. Maximize is an English verb, not a Latin one, even though every part of it looks Latin.","cn":"英式拼写为 maximise。maximization、maximizer 以及缩略的 max（1986 年起作动词）补足了词族。maximize 是英语动词而非拉丁语动词，尽管它的每个部件看起来都像拉丁语。"}]},"similar":{"note":{"en":"The first group separates the noun, the derived noun, the clipping and a look-alike with a different origin. The second group compares maximize with optimize, with plain increase, and with its two opposite poles, minimize and minimum.","cn":"第一组区分名词、派生名词、缩略词以及一个来源不同的形近词；第二组把 maximize 与 optimize、普通的 increase，以及它的两个对立端点 minimize、minimum 作比较。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"maximum","ipa":"/ˈmæksɪməm/","tag":"base noun","definition":"the greatest amount or degree possible. It is the noun that maximize was built from, not a synonym of the verb.","definitionCN":"可能的最大数量或程度。它是构成 maximize 的名词词基，而不是这个动词的同义词。"},{"word":"maxim","ipa":"/ˈmæksɪm/","tag":"different origin","definition":"a short statement of a general truth or rule of conduct, from Latin maxima propositio. It looks like maximum but belongs to a different noun.","definitionCN":"关于普遍真理或行为准则的简短格言，来自拉丁语 maxima propositio。它形似 maximum，却是另一个名词。"},{"word":"maximization","ipa":"/ˌmæksɪmaɪˈzeɪʃn/","tag":"derived noun","definition":"the act or process of maximizing. It names the process, while maximum names the end point.","definitionCN":"最大化的行为或过程。它命名过程，而 maximum 命名终点。"},{"word":"max","ipa":"/mæks/","tag":"clipping","definition":"informal short form of maximum, and by 1986 a verb meaning 'to reach the maximum level'. It is a clipping, not a separate root.","definitionCN":"maximum 的口语缩略形式，1986 年起也作动词，意为“达到最高水平”。它是缩略形式，不是另一条词根。"}]},{"heading":"NEAR MEANING","entries":[{"word":"optimize","ipa":"/ˈɒptɪmaɪz/","tag":"best arrangement","definition":"to make the best possible arrangement within given limits. It looks for the best compromise among competing factors, while maximize pushes one quantity to its ceiling.","definitionCN":"在既定限制内做出尽可能好的安排。它在多个相互竞争的因素之间寻找最佳折中，而 maximize 把一个量推到它的天花板。"},{"word":"increase","ipa":"/ɪnˈkriːs/","tag":"plain growth","definition":"to make larger in amount. It says nothing about a ceiling: you can increase a number without ever reaching its maximum.","definitionCN":"使数量变大。它不涉及天花板：你可以让一个数变大，却始终没到它的最大值。"},{"word":"minimize","ipa":"/ˈmɪnɪmaɪz/","tag":"direct antonym","definition":"to reduce to the smallest possible amount. It is the exact opposite pole: one verb turns the dial to the right, the other to the left.","definitionCN":"使降到尽可能小的量。它正是对立的那一端：一个动词把旋钮向右拧，另一个向左拧。"},{"word":"minimum","ipa":"/ˈmɪnɪməm/","tag":"opposite noun","definition":"the smallest amount or degree possible. It is the floor of the same scale whose ceiling is maximum.","definitionCN":"可能的最小数量或程度。它是同一把尺子的底端，而 maximum 是顶端。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: maximum + -ize, the Latin superlative maximus, the magnus family, and the matched pair maximize / minimize.","cn":"只用真实成分与真实同族词：maximum 加 -ize、拉丁最高级 maximus、magnus 词族，以及成对的 maximize／minimize。"},"normal":[{"en":"Maximum is the top of a scale and -ize means 'to make'. Maximize is simply 'to make maximum'.","cn":"maximum 是刻度的顶端，-ize 意为“使……”。maximize 就是“使达到最大”。"},{"en":"Maximus is the Latin superlative of magnus 'great'; the same root gives magnify, magnitude and magnate.","cn":"maximus 是拉丁语 magnus“大”的最高级；同一词根还给出 magnify、magnitude、magnate。"},{"en":"Maximize and minimize were both recorded in 1802, both in Bentham: one drives to the top of the scale, the other to the bottom.","cn":"maximize 与 minimize 都记录于 1802 年，都出自边沁：一个把刻度推到顶，一个推到低。"},{"en":"In business writing maximize collocates with profit, efficiency, output and returns — quantities that can be read off a dial.","cn":"在商业写作里，maximize 常与 profit、efficiency、output、returns 搭配——都是能从刻度盘上读出来的量。"},{"en":"In computing, maximize is the button that makes a window fill the screen; the screen is the ceiling of that scale.","cn":"在计算机里，maximize 是让窗口占满屏幕的那个按钮；屏幕就是那把尺子的天花板。"}],"abstract":[{"en":"Picture a dial with a hard stop at the right end. You can turn it as far as the stop and no further; that stop is what maximum means.","cn":"想象一只右端有硬止点的旋钮。你能拧到止点，再也不能多拧一格；那个止点就是 maximum 的含义。"},{"en":"A maximum is a ceiling, not a direction: maximizing tells you where to stop, not how to get there.","cn":"最大值是天花板，不是方向：maximize 告诉你该停在哪里，却没告诉你该怎么走到那里。"},{"en":"When one quantity is maximized, others are usually spent: maximum contrast costs comfort, maximum output costs rest.","cn":"当一个量被最大化，其他量通常被花掉：最大的对比度要付出舒适，最大的产量要付出休息。"}]},"examples":[{"en":"Farmers use every hectare to maximize the harvest.","cn":"农民用尽每一公顷土地，把收成做到最大。"},{"en":"The software maximizes screen space by hiding the toolbar.","cn":"这款软件通过隐藏工具栏把屏幕空间用到最大。"},{"en":"Negotiators tried to maximize the settlement without losing the deal.","cn":"谈判者试图在不丢单的情况下把和解条件做到最好。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“麦克西麦子”——麦克把麦子一层层堆到仓顶，堆到再也放不下一粒 → maximize 最大化、推到顶","word":"maximize"},"root":"由 maximum“最大限度”加 -ize“使……”构成，maximum 又来自拉丁语 maximus“最大的”，核心是“把某物推到刻度的最右端”。","sensesIntro":{"en":"Nine senses of maximize, all from one gesture: a dial is turned to the far right until it will go no further, whether the scale measures a function, a profit, an output, a chance, or a window.","cn":"maximize 的九个义项都来自同一个动作：把旋钮一路拧到最右端，直到再也拧不动——无论这把尺子量的是函数、利润、产量、机会还是一扇窗口。"},"semanticMap":{"core":{"en":"CORE IMAGE: a dial turned to the far right until it stops at the top of its scale.","cn":"核心意象：一只旋钮被拧到最右端，停在刻度的顶点。"},"chain":["A SCALE WITH A TOP","TURN TO THE RIGHT","ALL CAPACITY USED","OUTPUT AT ITS PEAK","EFFECT AT FULL REACH","NOTHING LEFT IDLE"],"branches":[{"senses":"S1 · S5","en":"MEASURED QUANTITIES: functions and probabilities sit on numeric scales, and maximizing moves the value to the top of that scale.","cn":"可测的量：函数与概率都落在数值刻度上，最大化就是把取值推到这段刻度的顶端。"},{"senses":"S2 · S3","en":"PRODUCTION: profit and output are the business dials, and maximizing runs them at full capacity.","cn":"生产：利润与产量是商业里的旋钮，最大化就是让它们满负荷运转。"},{"senses":"S4 · S9","en":"FORCE AND EXTREME: impact is a force pushed to full reach; driving one feature alone turns the word critical.","cn":"力量与极端：影响是一种被推到最远的力量；只把某一特征推到顶，就让这个词带上了批评意味。"},{"senses":"S6","en":"RESOURCES: every unit is put to work, so the measure becomes the absence of idle capacity.","cn":"资源：每个单位都被投入使用，于是衡量的对象变成了“没有闲置产能”。"},{"senses":"S7 · S8","en":"DEVICES AND FITNESS: a window grows to the screen's ceiling, and fitness rises to the highest value selection can reach.","cn":"设备与适应度：窗口长到屏幕这层天花板，适应度升到选择所能达到的最高值。"}]},"affixes":{"intro":{"en":"Maximize is built from a complete noun plus a living suffix, so its parts are easy to see: maximum + -ize. The same Latin superlative also supplies a large family of size words.","cn":"maximize 由一个完整名词加一个活后缀构成，部件一眼可见：maximum 加 -ize。同一个拉丁最高级还供应了一大群表示“大小”的词。"},"latinIntro":{"en":"Latin maximus 'greatest' is the superlative of magnus 'great'. Both are ordinary Latin adjectives, and maximum is the neuter form used as a noun; the PIE superlative suffix *-samo- is preserved in maximus.","cn":"拉丁语 maximus“最大的”是 magnus“大的”的最高级。两者都是普通拉丁形容词，maximum 是作名词用的中性形式；原始印欧语最高级后缀 *-samo- 保留在 maximus 里。"},"items":[{"word":"maximize","structure":"maximum + -ize (verb)","meaning":"to make as great as possible","meaningCN":"使尽可能大；最大化（-ize 构成动词）","example":"They maximized the grant by matching it with local funds.","exampleCN":"他们用地方资金配套，把拨款的作用做到最大。"},{"word":"maximum","structure":"maxim- + -um (neuter superlative ending)","meaning":"the greatest amount or degree","meaningCN":"最大量；最大限度（-um 为中性最高级词尾）","example":"The tank holds a maximum of forty litres.","exampleCN":"这个罐子最多装四十升。"},{"word":"maximal","structure":"maximum + -al (adjective)","meaning":"greatest possible; at the maximum","meaningCN":"最大的；达到最大限度的（-al 构成形容词）","example":"The drug was given at its maximal safe dose.","exampleCN":"这种药按最大安全剂量给予。"},{"word":"maximization","structure":"maximize + -ation (noun of process)","meaning":"the process of making something as great as possible","meaningCN":"最大化；最大化过程（-ation 构成过程名词）","example":"Profit maximization was not the only goal of the reform.","exampleCN":"利润最大化并不是这场改革的唯一目标。"},{"word":"maximizer","structure":"maximize + -er (person or thing that does)","meaning":"one who seeks the maximum","meaningCN":"追求最大化的人或物（-er 表示行为者）","example":"As a maximizer, she never settles for the second-best option.","exampleCN":"作为一个凡事求最大的人，她从不接受次优选项。"},{"word":"max","structure":"clipping of maximum","meaning":"the maximum; to reach the maximum level","meaningCN":"最大值；达到最高水平（maximum 的缩略）","example":"He maxed out his credit card before the trip.","exampleCN":"出发前他把信用卡刷到了额度上限。"},{"word":"maximise","structure":"maximize + British -ise spelling","meaning":"British spelling of maximize","meaningCN":"maximize 的英式拼写（-ise）","example":"The report advises firms to maximise energy efficiency.","exampleCN":"报告建议企业把能效做到最大。"},{"word":"maxim","structure":"Latin maxima (propositio), a different noun","meaning":"a short rule of conduct or general truth","meaningCN":"格言；行为准则（来自拉丁语 maxima propositio，与 maximum 同形不同源）","example":"The maxim 'less is more' guided the whole design.","exampleCN":"“少即是多”这句格言指导了整个设计。"},{"word":"magnify","structure":"magni- (magnus, great) + -fy (make)","meaning":"to make something appear larger","meaningCN":"放大；使显得更大（magni- 大 + -fy 使）","example":"The lens magnifies the print for easy reading.","exampleCN":"这片透镜把字放大，便于阅读。"},{"word":"magnitude","structure":"magni- (magnus) + -tude (state, quality)","meaning":"greatness of size or importance","meaningCN":"巨大；重要性；量级（magni- 大 + -tude 状态）","example":"Few understood the magnitude of the loss.","exampleCN":"很少有人明白这次损失有多大。"},{"word":"magnate","structure":"magn- (Latin magnates, great men) + -ate","meaning":"a powerful person in business or industry","meaningCN":"巨头；大亨（拉丁语 magnates“大人物”）","example":"A shipping magnate funded the new museum.","exampleCN":"一位航运巨头出资建了这座新博物馆。"}],"latinEntries":[{"word":"maximus","structure":"superlative of magnus 'great'","meaning":"greatest, largest","meaningCN":"最大的；最伟大的"},{"word":"magnus","structure":"Latin adjective, from PIE *meg- 'great'","meaning":"great, large, big","meaningCN":"大的；巨大的"},{"word":"maximum","structure":"neuter of maximus, used as a noun","meaning":"the greatest thing or amount","meaningCN":"最大者；最大量（maximus 的中性形式作名词）"}]}},{"word":"mechanism","ipa_uk":"/ˈmekənɪzəm/","ipa_us":"/ˈmekənɪzəm/","definition_zh":"机械装置；机械结构；机制；机理；途径","definition_en":"a set of connected moving parts, or an abstract arrangement of parts and processes that produces a particular result","core_image":"一排咬合的齿轮：每一枚只做一件事，连起来却推动整台机器","scene":"The clockmaker lifted the back plate to show the mechanism of the old tower clock.","sceneCN":"这里 mechanism 是「机械结构、传动装置」（第 2 个义项：机器内部一起工作的部件与结构）；句意：钟表匠揭开后板，展示这座老塔钟的机械结构。场景要点：塔钟的黄铜后板、层层咬合的齿轮、钟表匠手里的放大镜。","pos":[{"tag":"n.","zh":"机械装置；机械结构；传动部件"},{"tag":"n.","zh":"机制；机理；途径；方法"}],"collocations":[{"phrase":"a locking mechanism","zh":"锁定装置"},{"phrase":"a defence mechanism","zh":"防御机制"},{"phrase":"a reaction mechanism","zh":"反应机理"},{"phrase":"an institutional mechanism","zh":"制度性机制"},{"phrase":"the market mechanism","zh":"市场机制"},{"phrase":"the underlying mechanism","zh":"底层机制；内在机理"},{"phrase":"a mechanism for settling disputes","zh":"解决争端的机制"}],"forms":[{"label":"名词复数","form":"mechanisms"}],"derivatives":[{"word":"mechanical","pos":"adj.","zh":"机械的；机械式的；呆板的"},{"word":"mechanically","pos":"adv.","zh":"机械地；用机械方式"},{"word":"mechanics","pos":"n.","zh":"力学；机械学；运作方式"},{"word":"mechanize","pos":"v.","zh":"机械化；使机械化"},{"word":"mechanization","pos":"n.","zh":"机械化"},{"word":"mechanistic","pos":"adj.","zh":"机械论的；用机械式因果解释的"}],"senses":[{"no":"01","title":"A set of moving parts","titleCN":"一套活动部件","definition":"the parts of a device that move together to perform a particular action","definitionCN":"装置中一起运动、完成特定动作的那些部件","example":"The locking mechanism jammed after years of use.","exampleCN":"使用多年之后，锁具装置卡住了。","why":"Greek mēkhanē named a device, and the first English sense was the structure of a machine. The physical set of parts is the core image in its most concrete form.","whyCN":"希腊语 mēkhanē 指装置，英语最早的义项就是机器的结构。这一套实体部件，就是核心意象最具体的形态。"},{"no":"02","title":"The working structure inside a machine","titleCN":"机器内部的工作结构","definition":"the arrangement and interaction of a machine's parts, considered as a whole","definitionCN":"机器各部件作为整体时的排列与相互作用","example":"He explained the mechanism of the clock, gear by gear.","exampleCN":"他一个齿轮一个齿轮地讲解这座钟的机械结构。","why":"Once the parts are seen together, attention shifts from the pieces to how they transmit motion. The word now names the logic inside the device.","whyCN":"当部件被放在一起看，注意力就从零件本身转到它们如何传递运动。这个词于是命名装置内部的那套逻辑。"},{"no":"03","title":"An institutional mechanism","titleCN":"制度性机制","definition":"an established arrangement of rules, offices, and procedures that produces a result or handles a problem","definitionCN":"由规则、机构和程序构成的既定安排，用来产生某种结果或处理某个问题","example":"The treaty set up a mechanism for settling border disputes.","exampleCN":"这项条约建立了一套解决边界争端的机制。","why":"Institutions can be read as parts of a machine: each office turns one wheel, and the arrangement yields a decision. The physical picture is applied to procedure.","whyCN":"制度可以被读成机器的零件：每个机构带动一只轮子，整套安排产出一个决定。物理画面被套用到了程序上。"},{"no":"04","title":"A biological mechanism","titleCN":"生物机理","definition":"a set of bodily or cellular processes that produces a particular effect","definitionCN":"身体或细胞层面的一组过程，产生特定效果","example":"The immune mechanism recognises the virus within hours.","exampleCN":"免疫机制在数小时内就识别出这种病毒。","why":"A living body also has interlocking parts, though they are cells and signals rather than gears. The image survives because the result still depends on the parts acting in order.","whyCN":"活的躯体也有相互咬合的部件，只不过它们是细胞与信号，而不是齿轮。意象仍然成立，因为结果依旧依赖各部件按次序行动。"},{"no":"05","title":"A psychological mechanism","titleCN":"心理机制","definition":"a repeated mental process by which a person copes with feelings or situations","definitionCN":"一个人用来应对情绪或处境的、反复出现的心理过程","example":"Mocking others can work as a defence mechanism.","exampleCN":"嘲笑别人可以起到防御机制的作用。","why":"The mind is treated as an apparatus with parts: a feeling enters, a routine process turns it, and a behaviour comes out. The word lends machinery to psychology.","whyCN":"心灵被当作一台有部件的装置：一种情绪进入，一套惯常过程把它转动，一种行为出来。这个词把机械感借给了心理学。"},{"no":"06","title":"A reaction mechanism in chemistry","titleCN":"化学中的反应机理","definition":"the step-by-step sequence by which reactants become products, including intermediate states","definitionCN":"反应物变成产物的逐步序列，包括中间状态","example":"The reaction mechanism involves two short-lived intermediates.","exampleCN":"这个反应机理涉及两种寿命很短的中间体。","why":"A reaction is a process with stages, and each stage hands the matter on to the next like one gear driving another. The word names the hidden chain.","whyCN":"反应是一个分阶段的过程，每一阶段把物质交给下一阶段，就像一只齿轮带动另一只。这个词命名的正是那条看不见的链条。"},{"no":"07","title":"The philosophical doctrine of mechanism","titleCN":"哲学上的机械论","definition":"the view that natural events can be explained entirely by the motion of matter, without purpose or vital force","definitionCN":"认为自然事件完全可以由物质运动来解释、无需目的或生命力 的观点","example":"Mechanism holds that life can be explained by matter and motion alone.","exampleCN":"机械论认为生命仅凭物质与运动就能得到解释。","why":"Here the metaphor is taken all the way: the whole of nature is declared to be one machine. The word stops naming a device and starts naming a world view.","whyCN":"这里把比喻推到了底：整个自然被宣告为一台机器。这个词不再命名某个装置，而开始命名一种世界观。"},{"no":"08","title":"A means or channel for doing something","titleCN":"做事的手段或渠道","definition":"a method, channel, or route through which something can be done","definitionCN":"完成某事所经由的方法、渠道或途径","example":"The committee has no mechanism for enforcing its decisions.","exampleCN":"委员会没有执行其决定的机制。","why":"If a result is produced by parts working in order, then any such arrangement is a way to get the result. The concrete device thins into 'means'.","whyCN":"如果结果由部件按次序工作产生，那么任何这样的安排都是取得结果的一条路。具体装置于是淡化成“手段”。"}],"etymology":{"intro":{"en":"Mechanism came into English in the 1660s from Modern Latin mechanismus, built on Greek mēkhanē 'machine, device'. The Greek-to-Latin route is clear; the deeper Indo-European link is disputed.","cn":"mechanism 于 17 世纪 60 年代由现代拉丁语 mechanismus 进入英语，后者建立在希腊语 mēkhanē“机械、装置”之上。希腊语到拉丁语的路径清楚；更深的印欧语关联存在争议。"},"items":[{"era":"1660s","en":"First recorded in English meaning 'the structure of a machine, engine, or other contrivance for controlling or utilizing natural forces'. The source is Modern Latin mechanismus.","cn":"英语中最早记录于 17 世纪 60 年代，意为“机器、引擎或其他用来控制或利用自然力的装置的结构”。来源是现代拉丁语 mechanismus。"},{"era":"1670s","en":"The broader sense 'a mechanical contrivance or agency of any kind' is recorded. From here the word begins to detach from literal hardware and to name any working arrangement.","cn":"较宽的义项“任何种类的机械装置或作用机构”有记录。自此这个词开始脱离字面上的硬件，用来命名任何一套运作安排。"},{"era":"MODERN LATIN","en":"Mechanismus was formed from Greek mēkhanē plus the Latin noun suffix -ismus. It is a scholarly coinage, not an inherited Latin word.","cn":"mechanismus 由希腊语 mēkhanē 加拉丁名词后缀 -ismus 构成。它是学术性的新造词，不是继承下来的拉丁词。"},{"era":"GREEK","en":"Greek mēkhanē, with the Doric variant makhana, meant 'device, tool, machine', and also 'contrivance, cunning'. It is the source of machine and mechanic as well as mechanism.","cn":"希腊语 mēkhanē（多里斯方言作 makhana）意为“装置、工具、机械”，也有“计谋、机巧”的意思。它既是 machine、mechanic 的来源，也是 mechanism 的来源。"},{"era":"PIE","en":"Watkins derived mēkhanē from PIE *magh- 'to be able, have power', the root behind may, might and magic. Beekes rejects this on formal grounds and treats the Greek word as Pre-Greek, so the deepest root is disputed and best marked source uncertain.","cn":"沃特金斯把 mēkhanē 追溯到原始印欧语 *magh-“能够、有力量”，该词根也是 may、might、magic 的来源。比克斯从形式证据上反对这一联系，认为这个希腊词属于前希腊语底层，因此最深词源有争议，宜标为来源不确定。"},{"era":"MODERN ENGLISH","en":"Mechanic, mechanical, mechanics, mechanize and mechanistic all belong to the same family. Mechanism keeps two lives: a concrete device, and an abstract system of parts and processes.","cn":"mechanic、mechanical、mechanics、mechanize、mechanistic 都属于同一词族。mechanism 保有两条命：一个是具体装置，一个是由部件与过程构成的抽象系统。"}]},"similar":{"note":{"en":"The first group separates the whole machine, the mass noun, the person and the adjective. The second group compares mechanism with apparatus, device, process and system.","cn":"第一组区分整台机器、集合名词、人和形容词；第二组把 mechanism 与 apparatus、device、process、system 作比较。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"machine","ipa":"/məˈʃiːn/","tag":"whole device","definition":"a complete device with moving parts that does a job. Mechanism is the arrangement inside such a device, or the abstract version of that arrangement.","definitionCN":"一台有活动部件、能完成某项工作的完整装置。mechanism 是这种装置内部的排列，或这种排列的抽象版本。"},{"word":"machinery","ipa":"/məˈʃiːnəri/","tag":"mass noun","definition":"machines as a group, or the moving parts of a machine taken as a mass. It is uncountable, while a mechanism is one countable arrangement.","definitionCN":"机器的总称，或作为整体看的一台机器的活动部件。它不可数，而 mechanism 是一套可数的排列。"},{"word":"mechanic","ipa":"/məˈkænɪk/","tag":"person","definition":"a person who repairs or operates machines. It names a worker, not the working arrangement.","definitionCN":"修理或操作机器的人。它命名的是工人，而不是运作的结构。"},{"word":"mechanistic","ipa":"/ˌmekəˈnɪstɪk/","tag":"adjective","definition":"explaining things as if they were produced by machinery. It describes a view or style, not a device.","definitionCN":"把事物当作由机械产生来解释的。它描述一种观点或风格，而不是一件装置。"}]},{"heading":"NEAR MEANING","entries":[{"word":"apparatus","ipa":"/ˌæpəˈreɪtəs/","tag":"equipment","definition":"a set of equipment assembled for a particular purpose, often scientific. It names the whole set-up, while mechanism stresses how the parts work together.","definitionCN":"为特定目的组装的一套设备，常用于科学场景。它命名整套装备，而 mechanism 强调部件如何一起运作。"},{"word":"device","ipa":"/dɪˈvaɪs/","tag":"object","definition":"an object invented to do a particular job. A device is what it is; a mechanism is how it works.","definitionCN":"为完成特定工作而发明的物件。device 说的是“它是什么”，mechanism 说的是“它怎样运作”。"},{"word":"process","ipa":"/ˈprəʊses/","tag":"sequence","definition":"a series of actions that leads to a result. It gives the order of stages; mechanism adds the interlocking parts that carry the stages out.","definitionCN":"导向结果的一系列行动。它给出阶段的顺序；mechanism 则补上执行这些阶段的咬合部件。"},{"word":"system","ipa":"/ˈsɪstəm/","tag":"organized whole","definition":"an organized set of parts or rules. It is broader than mechanism: a system may be social or biological, and it need not have a visible causal chain.","definitionCN":"有组织的部件或规则集合。它比 mechanism 更宽：系统可以是社会的或生物的，也不必有可见的因果链。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Greek mēkhanē 'device', machine and mechanic, and the modern family mechanical / mechanics / mechanize.","cn":"只用真实成分与真实同族词：希腊语 mēkhanē“装置”，machine 与 mechanic，以及现代词族 mechanical／mechanics／mechanize。"},"normal":[{"en":"Greek mēkhanē meant 'device, tool, machine'. Mechanism is the Latin-built noun for the way such a device is put together.","cn":"希腊语 mēkhanē 意为“装置、工具、机械”。mechanism 是拉丁语构造的名词，指这种装置被组装起来的方式。"},{"en":"Machine, mechanic and mechanism share one Greek source. The machine is the whole object, the mechanic is the person, and the mechanism is the working arrangement.","cn":"machine、mechanic、mechanism 共享同一个希腊来源。机器是整体物件，技师是人，机制则是运作的排列。"},{"en":"Mechanical is the adjective, mechanics is the science of forces and motion, and mechanize is to replace hands with machinery.","cn":"mechanical 是形容词，mechanics 是研究力与运动的科学，mechanize 则是用机械取代人手。"},{"en":"A defence mechanism, a reaction mechanism and a market mechanism all keep the same picture: parts in contact, each turning the next.","cn":"防御机制、反应机理与市场机制都保留同一幅画面：部件相互接触，每一枚带动下一枚。"},{"en":"Mechanistic is the adjective for a view that treats everything as machinery; it is a judgement about an explanation, not a description of a device.","cn":"mechanistic 是形容词，指把一切当作机械的看法；它是对某种解释的评判，而不是对装置的描述。"}],"abstract":[{"en":"Picture a row of gears. No single gear can do the job alone; the result appears only when each one passes motion to the next.","cn":"想象一排齿轮。没有任何一只齿轮能独自完成工作；只有当每一只把运动传给下一只，结果才出现。"},{"en":"A mechanism is a way of hiding the work: you see a handle turn, but the useful result happens inside the box.","cn":"机制是一种把劳动藏起来的方式：你看见手柄在转，真正有用的结果却发生在盒子内部。"},{"en":"The same word serves a lock, an immune system and a treaty because all three produce a result through parts that depend on one another.","cn":"同一个词能用于一把锁、一套免疫系统和一项条约，因为这三者都通过彼此依赖的部件产出一个结果。"}]},"examples":[{"en":"The engineer traced the fault to a worn cam in the valve mechanism.","cn":"工程师把故障追查到阀门装置里一只磨损的凸轮。"},{"en":"Scientists still argue about the exact mechanism by which the drug works.","cn":"科学家仍在争论这种药起效的确切机理。"},{"en":"The two countries agreed on a mechanism for sharing river water.","cn":"两国就共享河水的一套机制达成了一致。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“麦克你怎”——麦克，你怎把这一排齿轮装进盒子？→ mechanism 机械装置、机制","word":"mechanism"},"root":"源自希腊语 mēkhanē“机械、装置”，经现代拉丁语 mechanismus 进入英语，核心是“一组咬合部件按次序把运动传下去”。","sensesIntro":{"en":"Eight senses of mechanism, all from one picture: interlocking parts, each doing one small job, together producing a result — whether the parts are gears, cells, institutions, or steps in a reaction.","cn":"mechanism 的八个义项都来自同一幅画面：相互咬合的部件，每个只做一件小事，合起来产出一个结果——无论这些部件是齿轮、细胞、机构，还是反应中的步骤。"},"semanticMap":{"core":{"en":"CORE IMAGE: a row of interlocking gears, each passing motion to the next.","cn":"核心意象：一排咬合的齿轮，每一只把运动传给下一只。"},"chain":["PARTS IN CONTACT","ONE TURNS THE NEXT","A CONTROLLED MOTION","A RESULT PRODUCED","A PROCESS LAID BARE","A MEANS TO AN END"],"branches":[{"senses":"S1 · S2","en":"HARDWARE: a lock or a clock is a set of parts, and the mechanism is both the parts and the way they move together.","cn":"硬件：一把锁或一座钟是一套部件，mechanism 既是这些部件，也是它们一起运动的方式。"},{"senses":"S3 · S8","en":"ARRANGEMENTS AND MEANS: institutions and procedures can be arranged like parts, and any such arrangement is a way to get a result.","cn":"安排与手段：机构与程序可以像部件一样被安排，而任何这样的安排都是取得结果的一条路。"},{"senses":"S4 · S5","en":"LIFE AND MIND: immune responses and defence routines are hidden processes whose parts still depend on one another.","cn":"生命与心灵：免疫反应与防御套路都是隐藏的过程，其部件同样彼此依赖。"},{"senses":"S6","en":"CHEMISTRY: a reaction mechanism is the step-by-step chain that turns reactants into products.","cn":"化学：反应机理是把反应物变成产物的逐步链条。"},{"senses":"S7","en":"PHILOSOPHY: mechanism turns the metaphor into a world view, declaring all of nature to be one machine.","cn":"哲学：机械论把比喻提升为世界观，宣告整个自然就是一台机器。"}]},"affixes":{"intro":{"en":"Mechanism is Greek mēkhanē fitted with a Latin noun suffix. English then adds -ical, -ics, -ize and -ation, and the same Greek root also gives machine and machinery.","cn":"mechanism 是希腊语 mēkhanē 装上拉丁名词后缀构成的。英语随后加上 -ical、-ics、-ize、-ation，同一个希腊词根还给出 machine 与 machinery。"},"latinIntro":{"en":"Modern Latin mechanismus is a scholarly compound of Greek mēkhanē and Latin -ismus. Latin also borrowed the Greek noun as machina, which is the direct source of English machine and machinery.","cn":"现代拉丁语 mechanismus 是希腊语 mēkhanē 与拉丁后缀 -ismus 的学术复合词。拉丁语还把希腊名词借作 machina，这正是英语 machine 与 machinery 的直接来源。"},"items":[{"word":"mechanism","structure":"Greek mēkhanē (device) + Latin -ismus","meaning":"a working arrangement of parts; a system that produces a result","meaningCN":"部件的运作排列；产生结果的机制（mēkhanē 装置 + -ismus 名词后缀）","example":"The clock's mechanism needs cleaning every year.","exampleCN":"这座钟的机械结构每年都要清洗。"},{"word":"mechanisms","structure":"mechanism + plural -s","meaning":"two or more mechanisms","meaningCN":"两套或更多机制（复数 -s）","example":"The body uses several mechanisms to control heat.","exampleCN":"身体用好几套机制来控制体温。"},{"word":"mechanistic","structure":"mechanism + -istic (adjective)","meaning":"explaining things as if by machinery","meaningCN":"机械论的；机械式解释的（-istic 构成形容词）","example":"A mechanistic view leaves no room for purpose.","exampleCN":"机械论的观点不给目的留下空间。"},{"word":"mechanize","structure":"mechan- + -ize (verb)","meaning":"to replace manual work with machinery","meaningCN":"使机械化（-ize 构成动词）","example":"The farm mechanized harvesting in the 1950s.","exampleCN":"这个农场在 20 世纪 50 年代实现了收割机械化。"},{"word":"mechanization","structure":"mechanize + -ation (noun of process)","meaning":"the process of introducing machinery","meaningCN":"机械化（-ation 构成过程名词）","example":"Mechanization cut the need for seasonal labour.","exampleCN":"机械化减少了对季节性劳动力的需求。"},{"word":"mechanical","structure":"mechanic + -al (adjective)","meaning":"working by machinery; done without thought","meaningCN":"机械的；机械式的；呆板的（-al 构成形容词）","example":"The lift stopped because of a mechanical fault.","exampleCN":"电梯因机械故障停了下来。"},{"word":"mechanically","structure":"mechanical + -ly (adverb)","meaning":"by means of machinery; without thought","meaningCN":"机械地；用机械方式（-ly 构成副词）","example":"She answered mechanically, without listening.","exampleCN":"她机械地回答，根本没在听。"},{"word":"mechanics","structure":"mechanic + -ics (science or activity)","meaning":"the science of forces and motion; the way something works","meaningCN":"力学；机械学；运作方式（-ics 表示学科）","example":"The mechanics of the trade are taught in the first term.","exampleCN":"这门行业的具体运作方式在第一学期教授。"},{"word":"mechanic","structure":"Latin mechanicus, from Greek mēkhanikos","meaning":"a person who repairs machines","meaningCN":"机械师；修理工（拉丁语 mechanicus，源自希腊语）","example":"The mechanic replaced the worn bearing.","exampleCN":"修理工更换了磨损的轴承。"},{"word":"machine","structure":"Latin machina, from Greek mēkhanē","meaning":"a device with moving parts that does work","meaningCN":"机器（拉丁语 machina，源自希腊语 mēkhanē）","example":"The machine prints two thousand labels an hour.","exampleCN":"这台机器每小时印两千张标签。"},{"word":"machinery","structure":"machine + -ery (collective noun)","meaning":"machines as a group; the working parts of a machine","meaningCN":"机器总称；机器的运转部件（-ery 构成集合名词）","example":"The factory replaced its old machinery.","exampleCN":"工厂更换了旧机器。"},{"word":"mechano-","structure":"Greek mēkhanē + combining form -o-","meaning":"a prefix meaning mechanical or machine-related","meaningCN":"表示“机械的、与机械有关的”构词成分","example":"A mechanoreceptor responds to touch or pressure.","exampleCN":"机械感受器对触碰或压力作出反应。"}],"latinEntries":[{"word":"mechanismus","structure":"Greek mēkhanē + Latin -ismus","meaning":"the structure of a machine","meaningCN":"机器的结构（现代拉丁语新造词）"},{"word":"machina","structure":"Latin borrowing of Greek mēkhanē","meaning":"machine, engine, device, trick","meaningCN":"机器、引擎、装置、计谋"},{"word":"mechanicus","structure":"Latin adjective from Greek mēkhanikos","meaning":"mechanical; a person skilled in machines","meaningCN":"机械的；精通机械的人"}]}},{"word":"media","ipa_uk":"/ˈmiːdiə/","ipa_us":"/ˈmiːdiə/","definition_zh":"媒体；传媒；传播媒介；（medium 的复数）介质、媒介","definition_en":"the organizations and channels that spread news and information to the public, or the plural of medium in the sense of a substance or channel","core_image":"许多人站在同一条传声管道两侧：信息从一头进去，从另一头被所有人听见","scene":"The story reached the public through three national media outlets within an hour.","sceneCN":"这里 media 是「媒体机构、传媒」（第 2 个义项：报纸、电视、网站等新闻机构）；句意：这条新闻在一小时内经由三家全国性媒体机构传到了公众耳中。场景要点：三块不同的屏幕、同一条正在播出的新闻、屏幕前抬头看的人。","pos":[{"tag":"n.","zh":"媒体；传媒（报纸、广播、网络等机构的总称）"},{"tag":"n.","zh":"medium 的复数：媒介；介质；手段"}],"collocations":[{"phrase":"the mass media","zh":"大众传媒"},{"phrase":"social media","zh":"社交媒体"},{"phrase":"media coverage","zh":"媒体报道"},{"phrase":"a media outlet","zh":"一家媒体机构"},{"phrase":"media attention","zh":"媒体关注"},{"phrase":"mainstream media","zh":"主流媒体"},{"phrase":"media literacy","zh":"媒介素养"}],"forms":[{"label":"复数（单数为 medium；作“传媒”时通常与单数同形）","form":"media"}],"derivatives":[{"word":"medium","pos":"n./adj.","zh":"媒介；介质；手段；中等的"},{"word":"medial","pos":"adj.","zh":"中间的；内侧的"},{"word":"median","pos":"n./adj.","zh":"中位数；中间值；中间的"},{"word":"mediate","pos":"v.","zh":"调解；居中传达"},{"word":"mediation","pos":"n.","zh":"调解；调停"},{"word":"multimedia","pos":"n./adj.","zh":"多媒体；多媒体的"}],"senses":[{"no":"01","title":"The media as a collective body","titleCN":"作为集合体的媒体","definition":"newspapers, broadcasting, and online news organizations considered together as one social force","definitionCN":"把报纸、广播和网络新闻机构合在一起，视为一股社会力量","example":"The media ignored the report for a week.","exampleCN":"媒体有一个星期没有理会这份报告。","why":"Many separate channels are treated as one thing because they all stand between events and the public. The plural form becomes a collective name for that middle layer.","whyCN":"许多彼此分开的渠道被当作一个东西，因为它们都站在事件与公众之间。复数形式于是变成了这一中间层的集合名称。"},{"no":"02","title":"News organizations and journalists","titleCN":"新闻机构与记者群体","definition":"the specific outlets, editors, and reporters who gather and publish news","definitionCN":"采集并发布新闻的具体机构、编辑与记者","example":"Three media outlets carried the story on their front pages.","exampleCN":"三家媒体机构把这条新闻放上了头版。","why":"Here the collective is broken back into its members. Media is short for media organizations, and the word points to the people and desks doing the work.","whyCN":"这里集合体又被拆回它的成员。media 是 media organizations 的简写，词指向的是做这份工作的人与编辑部。"},{"no":"03","title":"Channels of communication","titleCN":"传播渠道","definition":"the different means by which a message is carried to an audience, such as print, radio, or film","definitionCN":"把信息送达受众的不同手段，如印刷、广播或电影","example":"Print and broadcast are different media for the same message.","exampleCN":"印刷与广播是传递同一条信息的两种不同媒介。","why":"Medium means 'that which stands in the middle'. A channel stands between a message and its audience, so each channel is a medium and several are media.","whyCN":"medium 意为“处在中间的东西”。渠道站在信息与受众之间，所以每个渠道是一个 medium，多个渠道就是 media。"},{"no":"04","title":"Plural of medium: substances that carry something","titleCN":"medium 的复数：承载某物的介质","definition":"the plural of medium for a physical substance through which light, sound, or another effect travels","definitionCN":"medium 的复数，指光、声音或其他效应在其中传播的物理物质","example":"Sound travels through different media at different speeds.","exampleCN":"声音在不同介质中的传播速度不同。","why":"Air, water and glass each sit between a source and a receiver. This is the oldest physical sense of medium, and media is simply its plural.","whyCN":"空气、水、玻璃都位于源头与接收者之间。这是 medium 最古老的物理义，而 media 只是它的复数。"},{"no":"05","title":"Social media as platforms","titleCN":"社交媒体平台","definition":"the online platforms on which users create and share content with one another","definitionCN":"用户在其中创作并相互分享内容的网络平台","example":"The campaign spread through social media in two days.","exampleCN":"这场活动两天内就通过社交媒体传开了。","why":"The channel no longer belongs to a publisher: every user is also a sender. The old 'middle layer' becomes a set of platforms in the middle of everyone.","whyCN":"渠道不再属于出版方：每个用户同时也是发送者。旧的“中间层”变成了位于所有人中间的一组平台。"},{"no":"06","title":"Storage media","titleCN":"存储介质","definition":"the physical materials or devices on which data is kept, such as disks or tapes","definitionCN":"用来保存数据的物理材料或设备，如磁盘或磁带","example":"The archive was moved to newer storage media.","exampleCN":"档案被转移到了更新的存储介质上。","why":"Data has to sit in something. The storage material stands between the data and the machine that reads it, so it is a medium and several are media.","whyCN":"数据必须待在某种东西里。存储材料站在数据与读取它的机器之间，所以它是一个 medium，多个就是 media。"},{"no":"07","title":"Art media: the materials of a work","titleCN":"艺术媒介：作品所用的材料","definition":"the materials an artist uses, such as oil, watercolour, clay, or video","definitionCN":"艺术家使用的材料，如油画颜料、水彩、黏土或影像","example":"The artist works in mixed media.","exampleCN":"这位艺术家使用综合媒材创作。","why":"Paint and clay are substances that carry an image the way wire carries a signal. The plural media names the set of such materials.","whyCN":"颜料与黏土是承载图像的物质，就像导线承载信号。复数 media 命名这样一组材料。"},{"no":"08","title":"Culture media in biology","titleCN":"生物学中的培养基","definition":"the plural of medium for the nutrient substances in which microorganisms or cells are grown","definitionCN":"medium 的复数，指培养微生物或细胞所用的营养基质","example":"The bacteria were grown on three different culture media.","exampleCN":"这些细菌在三种不同的培养基上培养。","why":"A culture medium is the substance between a cell and its nutrients. It is a technical survival of the Latin sense, kept alive in laboratories.","whyCN":"培养基是细胞与其养分之间的物质。它是拉丁义项在实验室里保留下来的技术性用法。"}],"etymology":{"intro":{"en":"Media is the plural of medium, which English took from Latin in the 1580s. The 'news media' sense is a 20th-century development; the dates below are those given by standard etymological references.","cn":"media 是 medium 的复数，medium 于 16 世纪 80 年代由拉丁语进入英语。“新闻传媒”这一义项是 20 世纪的产物；以下年代采用通行词源资料的说法。"},"items":[{"era":"1927","en":"Media is first recorded in English meaning 'newspapers, radio, TV, etc.', perhaps abstracted from mass-media. The plural form was reinterpreted as a collective singular.","cn":"media 于 1927 年首次在英语中记录为“报纸、广播、电视等”，可能是从 mass-media 中提取出来的。这个复数形式被重新解释为一个集合单数。"},{"era":"1923","en":"Mass-media, with the singular mass-medium, is recorded as a technical term in advertising. It named the means of communication that reach large numbers of people.","cn":"mass-media（单数作 mass-medium）于 1923 年作为广告业的技术术语有记录。它指能到达大量人群的传播手段。"},{"era":"1580s","en":"Medium entered English meaning 'a middle ground, quality, or degree; that which holds a middle place'. It came from Latin medium, the neuter of medius 'in the middle'.","cn":"medium 于 16 世纪 80 年代进入英语，意为“中间地带、中间性质或程度；处于中间位置的东西”。它来自拉丁语 medium，即 medius“在中间”的中性形式。"},{"era":"LATIN","en":"Latin medium meant 'the middle, midst, center; interval'. The sense 'intervening substance through which a force is conveyed' is recorded in English from the 1590s, and 'channel of communication' from about 1600.","cn":"拉丁语 medium 意为“中间、中央、间隔”。英语中“力量借以传递的中间物质”这一义项从 16 世纪 90 年代有记录，“传播渠道”义约从 1600 年起有记录。"},{"era":"PIE","en":"Medium goes back to PIE *medhyo- 'middle', the root also behind mediate, median, medieval (medium aevum) and Mediterranean.","cn":"medium 可追溯到原始印欧语 *medhyo-“中间”，该词根也是 mediate、median、medieval（medium aevum）与 Mediterranean 的来源。"},{"era":"MODERN ENGLISH","en":"The print-publication sense of medium is from 1795 and fed the later media. In current usage media as 'the press and broadcasters' takes either a plural or a singular verb, while media as the plural of medium remains plural.","cn":"medium 的“印刷出版物”义始于 1795 年，并滋养了后来的 media。在当代用法中，表示“新闻与广播机构”的 media 可接复数动词也可接单数动词；而作为 medium 复数的 media 仍是复数。"}]},"similar":{"note":{"en":"The first group separates the singular medium, the rare plural medias, the process noun mediation and the statistical median. The second group compares media with mass media, social media, the press and a plain channel.","cn":"第一组区分单数 medium、罕见复数 medias、过程名词 mediation 与统计学的 median；第二组把 media 与 mass media、social media、the press 以及普通的 channel 作比较。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"medium","ipa":"/ˈmiːdiəm/","tag":"singular","definition":"one channel, substance, or means. It is the singular of media, and the pair keeps the Latin number distinction in careful writing.","definitionCN":"一个渠道、一种物质或一种手段。它是 media 的单数；在严谨写作中，这对词保留拉丁语的单复数区别。"},{"word":"medias","ipa":"/ˈmiːdiəz/","tag":"rare plural","definition":"a rare double plural sometimes used for several communication channels. Because media is already the plural of medium, many editors reject it.","definitionCN":"有时用来指多个传播渠道的罕见双重复数。由于 media 已是 medium 的复数，许多编辑不接受这种形式。"},{"word":"mediation","ipa":"/ˌmiːdiˈeɪʃn/","tag":"process noun","definition":"the act of helping two sides reach agreement. It comes from the verb mediate 'to stand in the middle', not from media as news organizations.","definitionCN":"帮助双方达成一致的行为。它来自动词 mediate“站在中间”，而不是来自表示新闻机构的 media。"},{"word":"median","ipa":"/ˈmiːdiən/","tag":"statistics","definition":"the middle value in a set of numbers, or a middle line. It shares the 'middle' root but belongs to measurement, not communication.","definitionCN":"一组数字中的中间值，或一条中线。它共享“中间”词根，却属于测量，而不属于传播。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mass media","ipa":"/ˌmæs ˈmiːdiə/","tag":"reach","definition":"the media that reach very large audiences, such as television and national newspapers. It names the reach, while media alone can include small outlets.","definitionCN":"能到达极大规模受众的媒体，如电视与全国性报纸。它命名的是覆盖范围，而单说 media 也可以包括小型机构。"},{"word":"social media","ipa":"/ˌsəʊʃl ˈmiːdiə/","tag":"platforms","definition":"platforms where users themselves create and share content. It is a subset of media in which the audience also publishes.","definitionCN":"由用户自己创作并分享内容的平台。它是 media 的一个子集，在其中受众也同时发布内容。"},{"word":"press","ipa":"/pres/","tag":"print and news","definition":"newspapers and the journalists who work for them. It is narrower than media: the press is print-centred, while media includes broadcast and online.","definitionCN":"报纸以及为其工作的记者。它比 media 窄：press 以印刷为中心，而 media 包括广播与网络。"},{"word":"channel","ipa":"/ˈtʃænl/","tag":"route","definition":"a route through which something is passed. It is the plain word for the middle layer; media is the institutional and collective name for such channels.","definitionCN":"某物借以传递的路径。它是描述中间层的平实词；media 则是这类渠道在机构与集合层面的名称。"}]}]},"mnemonics":{"normalIntro":{"en":"Real grammar and real relatives: media is the plural of medium, from Latin medius 'middle', and the same root gives mediate, median and medieval.","cn":"只用真实语法与真实同族词：media 是 medium 的复数，medium 来自拉丁语 medius“中间”，同一词根还给出 mediate、median、medieval。"},"normal":[{"en":"Media is the plural of medium. One channel is a medium; several channels are media, just as one datum becomes data.","cn":"media 是 medium 的复数。一个渠道是 medium，多个渠道就是 media，正如一个 datum 变成 data。"},{"en":"Medium means 'the middle thing'. A newspaper stands in the middle between an event and its readers, so it is a medium of communication.","cn":"medium 意为“中间的那个东西”。报纸站在事件与读者之间，所以它是传播的媒介。"},{"en":"Mass media and social media are compounds: one stresses reach, the other stresses that users publish too.","cn":"mass media 与 social media 都是复合词：前者强调覆盖范围，后者强调用户也在发布。"},{"en":"Mediation is not media: mediate means 'to stand in the middle' between two sides, and mediation is the act of helping them agree.","cn":"mediation 不是 media：mediate 意为“站在两方中间”，mediation 是帮助他们达成一致的行为。"},{"en":"In careful writing, 'the media are' and 'the media is' are both defended; the plural form is old, but the collective use is modern.","cn":"在严谨写作中，“the media are”与“the media is”都有人辩护；复数形式是旧的，集合用法却是现代的。"}],"abstract":[{"en":"Picture a pipe between two rooms. Whatever is shouted into one end comes out the other; the pipe itself is the medium.","cn":"想象两个房间之间的一根管道。从一端喊进去的东西从另一端出来；这根管道本身就是媒介。"},{"en":"When the pipe is owned by a few companies, it stops being just a pipe and becomes an institution with its own interests.","cn":"当这根管道被少数公司拥有，它就不再只是一根管道，而变成一个有自身利益的机构。"},{"en":"Social media removes the pipe: everyone holds an end of it, so the middle layer is made of the crowd itself.","cn":"社交媒体拆掉了管道：每个人都握着管道的一端，于是中间层由人群自己构成。"}]},"examples":[{"en":"The media were barred from the courtroom.","cn":"媒体被禁止进入法庭。"},{"en":"Water is a better medium for sound than air.","cn":"水比空气更适合作为声音的介质。"},{"en":"The gallery shows paintings, video and mixed media.","cn":"这家画廊展出绘画、影像和综合媒材作品。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“米迪亚”——米迪亚站在中间，把同一条消息递给了屋里的所有人 → media 媒体、媒介","word":"media"},"root":"media 是 medium“中间物、媒介”的复数，medium 来自拉丁语 medius“中间的”，核心是“站在信息与受众之间的那条渠道”。","sensesIntro":{"en":"Eight senses of media, all from one position: something placed in the middle, between a source and a receiver — a newspaper between an event and the public, air between a sound and an ear, or a disk between data and a machine.","cn":"media 的八个义项都来自同一个位置：某物被放在中间，位于源头与接收者之间——报纸在事件与公众之间，空气在声音与耳朵之间，磁盘在数据与机器之间。"},"semanticMap":{"core":{"en":"CORE IMAGE: a channel standing in the middle, carrying something from one side to the other.","cn":"核心意象：一条站在中间的渠道，把某物从一头送到另一头。"},"chain":["A MIDDLE PLACE","SOMETHING IN BETWEEN","A CHANNEL FOR A FORCE","NEWS PASSES THROUGH","THE CHANNEL BECOMES AN INSTITUTION","EVERYONE HEARS AT ONCE"],"branches":[{"senses":"S1 · S2","en":"THE COLLECTIVE: the middle layer can be named as one body, or broken back into the outlets and reporters that fill it.","cn":"集合体：这一中间层可以被命名为一个整体，也可以拆回填满它的机构与记者。"},{"senses":"S3 · S4","en":"CHANNELS AND SUBSTANCES: a communication route and a physical medium are both what stands between source and receiver.","cn":"渠道与物质：传播路径与物理介质，都是站在源头与接收者之间的东西。"},{"senses":"S5","en":"PLATFORMS: social media distributes the middle layer among the users themselves.","cn":"平台：社交媒体把这一中间层分散到了用户自己手中。"},{"senses":"S6 · S7","en":"MATERIALS: a disk holds data and paint holds an image; in both cases the material is the medium.","cn":"材料：磁盘承载数据，颜料承载图像；两种情形里，材料都是媒介。"},{"senses":"S8","en":"BIOLOGY: a culture medium is the nutrient layer between a cell and what feeds it.","cn":"生物学：培养基是细胞与其养分之间那一层营养物质。"}]},"affixes":{"intro":{"en":"Media is not built with an English suffix: it is the Latin plural of medium, and English later added -al, -an, -ate and -ation to the same root. Compounds such as multimedia and intermediary extend it further.","cn":"media 不是用英语后缀构成的：它是 medium 的拉丁语复数，英语后来在同一词根上加了 -al、-an、-ate、-ation。multimedia、intermediary 这类复合词进一步扩展了它。"},"latinIntro":{"en":"Latin medius 'in the middle' gives the neuter noun medium 'the middle', the verb mediare 'to be in the middle, mediate', and the adjective medianus. English keeps the neuter plural media unchanged.","cn":"拉丁语 medius“在中间”给出中性名词 medium“中间”，动词 mediare“处于中间、调解”，以及形容词 medianus。英语原样保留了中性复数 media。"},"items":[{"word":"media","structure":"medium + Latin neuter plural -a","meaning":"channels or substances in the middle; the news media","meaningCN":"居于中间的渠道或介质；新闻传媒（拉丁中性复数 -a）","example":"The media covered the trial every day.","exampleCN":"媒体每天都报道这场审判。"},{"word":"medium","structure":"Latin medium, neuter of medius 'middle'","meaning":"one channel, substance, or means","meaningCN":"一个渠道、一种介质或一种手段（拉丁语 medium“中间”）","example":"Radio was the dominant medium of the 1930s.","exampleCN":"无线电广播是 20 世纪 30 年代的主导媒介。"},{"word":"medial","structure":"medi- + -al (adjective)","meaning":"located in the middle; inner","meaningCN":"中间的；内侧的（-al 构成形容词）","example":"The injury affected the medial ligament of the knee.","exampleCN":"伤及了膝盖内侧的韧带。"},{"word":"median","structure":"medi- + -an (adjective and noun)","meaning":"the middle value; situated in the middle","meaningCN":"中位数；中间的（-an 构成形容词与名词）","example":"The median income rose slightly last year.","exampleCN":"去年的收入中位数略有上升。"},{"word":"mediate","structure":"medi- + -ate (verb)","meaning":"to stand between two sides and help them agree","meaningCN":"调解；居中传达（-ate 构成动词）","example":"A neutral official mediated the dispute.","exampleCN":"一位中立官员调解了这场争端。"},{"word":"mediation","structure":"mediate + -ion (noun of action)","meaning":"the act of mediating","meaningCN":"调解；调停（-ion 构成行为名词）","example":"The talks ended in mediation rather than a strike.","exampleCN":"谈判以调解而非罢工收场。"},{"word":"mediator","structure":"mediate + -or (person who does)","meaning":"a person who mediates","meaningCN":"调解人；中间人（-or 表示行为者）","example":"The mediator met both sides separately.","exampleCN":"调解人分别会见了双方。"},{"word":"multimedia","structure":"multi- (many) + media","meaning":"content that combines several media forms","meaningCN":"多媒体；综合多种媒介的内容（multi- 多 + media）","example":"The museum uses multimedia to explain the site.","exampleCN":"博物馆用多媒体来讲解这处遗址。"},{"word":"intermediary","structure":"inter- (between) + medi- (middle) + -ary","meaning":"a person or body that acts between two sides","meaningCN":"中间人；中介机构（inter- 之间 + medi- 中间 + -ary）","example":"The bank acted as an intermediary in the sale.","exampleCN":"银行在这笔交易中充当了中介。"},{"word":"medieval","structure":"medi- (middle) + aevum (age) + -al","meaning":"relating to the Middle Ages","meaningCN":"中世纪的（medi- 中间 + aevum 时代 + -al）","example":"The town has a well-preserved medieval wall.","exampleCN":"这座镇子有一段保存完好的中世纪城墙。"},{"word":"Mediterranean","structure":"medi- (middle) + terra (land) + -anean","meaning":"the sea in the middle of the land","meaningCN":"地中海（medi- 中间 + terra 陆地 + -anean，字面“陆地中间的海”）","example":"The ship crossed the Mediterranean in six days.","exampleCN":"这艘船用六天横渡了地中海。"}],"latinEntries":[{"word":"medium","structure":"neuter of medius 'middle'","meaning":"the middle, midst, center; interval","meaningCN":"中间、中央、间隔"},{"word":"medius","structure":"Latin adjective, from PIE *medhyo- 'middle'","meaning":"in the middle, between","meaningCN":"在中间的；位于两者之间的"},{"word":"mediare","structure":"medius + -are (verb)","meaning":"to be in the middle; to mediate","meaningCN":"处于中间；调解"}]}},{"word":"mediate","ipa_uk":"/ˈmiːdieɪt/","ipa_us":"/ˈmiːdieɪt/","definition_zh":"居中调解；斡旋；促成和解；作为中介传导；（形容词）间接的","definition_en":"to stand between two sides and help them reach an agreement, or to be the middle layer through which something is carried or passed on","core_image":"长桌中间空着的一把椅子：两边的人都够不到对方，只有这把椅子能同时听见两边","scene":"The union and the company had stopped talking, so a retired judge was asked to mediate.","sceneCN":"这里 mediate 是「居中调解」（第 2 个义项：站在两方之间斡旋，促成对话）；句意：工会与公司已经停止对话，于是请来一位退休法官居中调解。场景要点：一张长桌、两方各自抱臂坐着、中间空着的一把椅子。","pos":[{"tag":"vi./vt.","zh":"调解；斡旋；居中促成（争端、协议）"},{"tag":"adj.","zh":"间接的；居中的（多用于哲学与医学语境）"}],"collocations":[{"phrase":"mediate between the two sides","zh":"在双方之间调解"},{"phrase":"mediate a dispute","zh":"调解争端"},{"phrase":"mediate an agreement","zh":"斡旋达成协议"},{"phrase":"mediate a settlement","zh":"促成和解方案"},{"phrase":"mediate talks","zh":"为谈判做中间人"},{"phrase":"be mediated by","zh":"经由……传导；由……作为中介"},{"phrase":"mediate on behalf of","zh":"代表……出面斡旋"}],"forms":[{"label":"三单（he/she/it）","form":"mediates"},{"label":"过去式（已经发生）","form":"mediated"},{"label":"过去分词（完成／被动）","form":"mediated"},{"label":"现在分词（进行体）","form":"mediating"}],"derivatives":[{"word":"mediation","pos":"n.","zh":"调解；仲裁；中介作用"},{"word":"mediator","pos":"n.","zh":"调解人；中间人；中保"},{"word":"mediatrix","pos":"n.","zh":"女调解人（较少用，源自拉丁语阴性形式）"},{"word":"mediated","pos":"adj.","zh":"经中介的；间接获得的"},{"word":"unmediated","pos":"adj.","zh":"无中介的；直接的"},{"word":"mediatory","pos":"adj.","zh":"调解的；斡旋的"}],"senses":[{"no":"01","title":"Stand in the middle","titleCN":"站在中间：占据中间位置","definition":"to be or occupy a position between two things, points or extremes","definitionCN":"处在两物、两点或两个极端之间的位置","example":"A narrow strip of neutral ground mediated between the two front lines.","exampleCN":"一条狭窄的中立地带横在两道前线之间。","why":"Mediate comes from Latin medius, 'middle'. The earliest uses describe sheer position: something simply sits between two others, with no suggestion of speaking or settling anything.","whyCN":"mediate 来自拉丁语 medius“中间”。最早的用法只描述位置：某物就横在两物之间，并不含说话或调停的意思。"},{"no":"02","title":"Act as go-between","titleCN":"充当中间人：在两方之间斡旋","definition":"to intervene between two parties in order to bring them together or reconcile them","definitionCN":"在两方之间介入，使他们重新接触或和解","example":"She mediated between the landlord and the tenants for three hours.","exampleCN":"她在房东与租客之间斡旋了三个小时。","why":"Recorded from the 1610s, this sense turns the middle position into an action: the person who occupies the gap begins to carry words across it.","whyCN":"这一义项自 17 世纪 10 年代有记录，把“处在中间”变成动作：占据空隙的人开始把话从一边带到另一边。"},{"no":"03","title":"Settle a dispute","titleCN":"调解解决：把争端谈停下来","definition":"to help two sides reach an agreement, or to settle a dispute by acting as the middle party","definitionCN":"帮助两方达成一致，或作为中间方把争端解决掉","example":"The panel mediated a settlement that both sides accepted.","exampleCN":"调解小组促成了一个双方都接受的解决方案。","why":"The 1560s sense 'settle by mediation, harmonize' was probably back-formed from mediation or mediator. The space in the middle is now measured by its result: an agreement exists.","whyCN":"16 世纪 60 年代“通过调解解决、使和谐”的义项，很可能是从 mediation 或 mediator 逆构而来。中间那块空间现在用结果来衡量：协议出现了。"},{"no":"04","title":"Be the medium","titleCN":"作为介质：把力量或信号带过去","definition":"to serve as the substance or channel through which a force, signal or quality is carried","definitionCN":"作为某种力量、信号或性质得以传递的介质或通道","example":"Sound is mediated by air before it reaches the ear.","exampleCN":"声音在到达耳朵之前要经过空气的传导。","why":"This sense grows from medium, the same 'middle' root: an intervening substance through which something is conveyed, a meaning recorded in the 1590s.","whyCN":"这一义项从 medium 长出来，仍是同一个“中间”词根：某种介于其间的物质把东西输送过去，这一含义在 16 世纪 90 年代已有记录。"},{"no":"05","title":"Convey indirectly","titleCN":"间接传达：话经中间层才到","definition":"to pass on information or feeling through an intermediate person or thing rather than face to face","definitionCN":"不直接面对面，而是经由中间的人或物传递信息或情感","example":"Her letters mediated the news that no one in the family could say aloud.","exampleCN":"家里没人说得出口的消息，由她的信间接传达了出来。","why":"Whatever must pass through a middle layer arrives altered. The word therefore also names the softening or shaping that happens on the way.","whyCN":"凡是要穿过中间层的东西，到达时都会发生变化。因此这个词也指传递途中发生的缓冲与变形。"},{"no":"06","title":"Adjective: not immediate","titleCN":"形容词：间接的、非直接的","definition":"reached through an intermediate step or cause rather than directly","definitionCN":"经由中间步骤或中间原因达到，而非直接达到","example":"A mediate cause is one that acts through something else.","exampleCN":"间接原因是指要通过别的因素才起作用的原因。","why":"The adjective was recorded in the early 15th century as 'intermediate', from Medieval Latin mediatus. It marks distance between a cause and its effect.","whyCN":"这个形容词在 15 世纪初以“中间的”这一义项被记录，来自中世纪拉丁语 mediatus。它标记的是原因与结果之间的距离。"},{"no":"07","title":"Mediated knowledge","titleCN":"间接认识：知识经符号与工具抵达","definition":"knowledge or experience that reaches the mind through symbols, instruments or other people rather than directly","definitionCN":"经由符号、仪器或他人抵达头脑的知识或经验，而非亲身直接获得","example":"What we know of the deep ocean is mediated knowledge, gathered by robots and charts.","exampleCN":"我们对深海的了解是间接知识，由机器人和海图收集而来。","why":"Once the middle layer is acknowledged, philosophy asks what it does to what passes through. The word becomes a name for the gap between world and mind.","whyCN":"一旦承认中间层的存在，哲学就要问它对穿过的东西做了什么。这个词于是成了世界与头脑之间那道缝隙的名字。"},{"no":"08","title":"Formal mediation","titleCN":"正式调解：法律、劳资与外交程序","definition":"in law, labour relations and diplomacy, to conduct a formal process in which a third party helps the sides reach terms","definitionCN":"在法律、劳资关系与外交中，主持一个由第三方帮助各方达成条件的正式程序","example":"The government asked the United Nations to mediate the ceasefire talks.","exampleCN":"政府请联合国来调解停火谈判。","why":"Institutions take the private act and give it rules, a room and a record. Mediate then names a procedure rather than a personality.","whyCN":"机构把这种私人行为接管过来，给它规则、房间和记录。此时 mediate 命名的是一套程序，而不是某个人的性情。"},{"no":"09","title":"Religious mediator","titleCN":"宗教上的中保：在神与人之间","definition":"in theology, to stand between God and humanity and bring the two together","definitionCN":"在神学中，站在神与人之间，使两者得以相连","example":"In Christian doctrine, Christ mediates between God and man.","exampleCN":"在基督教教义中，基督在神与人之间作中保。","why":"The noun mediator was first applied to Christ, and the verb inherited that vertical picture: the middle position is not between equals but between heaven and earth.","whyCN":"名词 mediator 最早用于基督，动词继承了这幅垂直的画面：中间的位置不在平等的两方之间，而在天与地之间。"}],"etymology":{"intro":{"en":"Mediate comes from Latin medius 'middle' through the verb mediare. The same root gives medium and media, so the modern 'go-between' sense and the modern 'channel' sense are two branches of one physical picture. Dates are approximate.","cn":"mediate 经由拉丁语动词 mediare 来自 medius“中间”。同一个词根也给出 medium 与 media，因此现代“中间人”义与“渠道”义是同一幅物理画面的两个分支。年代为大致估计。"},"items":[{"era":"1540s","en":"First recorded in English as 'divide in two equal parts', a sense now obsolete. It comes from Latin mediatus, past participle of mediare 'to halve', later 'to be in the middle'.","cn":"英语中最早记录于 16 世纪 40 年代，意为“分成相等的两半”，此义今已废弃。它来自拉丁语 mediatus，即 mediare 的过去分词；mediare 意为“对半分”，后义为“处在中间”。"},{"era":"1560s","en":"The sense 'settle by mediation, harmonize, reconcile' appears, perhaps as a back-formation from mediation or mediator rather than as a direct development of the Latin verb.","cn":"出现“通过调解解决、使和谐、使和解”的义项，这也许是从 mediation 或 mediator 逆构而来，而不是拉丁语动词的直接发展。"},{"era":"1610s","en":"The central modern sense is recorded: 'act as a mediator, intervene for the purpose of reconciliation'. The person in the middle now speaks.","cn":"核心的现代义项有记录：“充当调解人，为促成和解而介入”。处在中间的那个人现在开口说话了。"},{"era":"1640s","en":"The positional sense 'occupy a middle place or position' is recorded, keeping the literal picture of something that lies between two others.","cn":"记录到表示位置的义项“占据中间的位置”，保留了某物横在另两物之间的字面画面。"},{"era":"EARLY 15C","en":"The adjective is recorded as 'intermediate', from Medieval Latin mediatus, the past-participle adjective of mediare. Mediately and immediate belong to the same family.","cn":"形容词以“中间的”这一义项记录于 15 世纪初，来自中世纪拉丁语 mediatus，即 mediare 的过去分词形容词。mediately 与 immediate 属于同一词族。"},{"era":"PIE *MEDHYO-","en":"The root *medhyo- 'middle' also lies behind medium, media, immediate, intermediate, medieval and Mediterranean. It has nothing to do with Latin medicus 'physician', the source of medical: the shared medi- shape is coincidence.","cn":"词根 *medhyo-“中间”也是 medium、media、immediate、intermediate、medieval、Mediterranean 的来源。它与 medical 的来源拉丁语 medicus“医生”毫无关系：共同的 medi- 外形只是巧合。"}]},"similar":{"note":{"en":"The first group shares the Latin 'middle' root but splits into a plural, a channel, a process and a person. The second group compares the words for stepping between people, which differ in how much authority the middle party has.","cn":"第一组共享拉丁语“中间”词根，但分成复数、渠道、过程与人四个身份。第二组比较“介入他人之间”的几个词，区别在于中间方握有多少裁决权。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"media","ipa":"/ˈmiːdiə/","tag":"plural of medium","definition":"the plural of medium, now used collectively for newspapers, broadcasting and online platforms. It is a set of channels, not an act of reconciling.","definitionCN":"medium 的复数，现集合指报纸、广播与网络平台。它是一组渠道，不是调解行为。"},{"word":"medium","ipa":"/ˈmiːdiəm/","tag":"channel or middle size","definition":"a substance or agency through which something is conveyed, or a middle size or degree. The noun keeps the literal 'middle layer' that mediate uses figuratively.","definitionCN":"借以传递某物的介质或机构，也可指中等的尺寸或程度。这个名词保留了 mediate 用作比喻时那个字面上的“中间层”。"},{"word":"mediation","ipa":"/ˌmiːdiˈeɪʃn/","tag":"the process","definition":"the process of intervening to help two sides reach agreement. It is the noun of the act, recorded in the late 14th century, older in English than the modern verb sense.","definitionCN":"介入并帮助两方达成一致的过程。它是这一行为的名词，14 世纪末已有记录，在英语里比动词的现代义项更老。"},{"word":"mediator","ipa":"/ˈmiːdieɪtə/","tag":"the person","definition":"a person who mediates, especially one who helps disputing parties reconcile. It names the occupant of the middle chair.","definitionCN":"进行调解的人，尤指帮助争执双方和解的人。它命名的是中间那把椅子上的人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"arbitrate","ipa":"/ˈɑːbɪtreɪt/","tag":"authority to decide","definition":"to act as an umpire and give a binding decision. An arbitrator can impose an outcome; a mediator can only help the sides agree.","definitionCN":"充当裁判并作出有约束力的裁决。仲裁者可以强加结果；调解者只能帮助双方自行达成一致。"},{"word":"intervene","ipa":"/ˌɪntəˈviːn/","tag":"step in","definition":"to come between parties or events, often without being asked. Intervention may be hostile or helpful; mediation is always aimed at agreement.","definitionCN":"介入双方或事件之间，常非受邀而为。介入可能是敌意的，也可能是善意的；调解则总是以达成一致为目标。"},{"word":"intercede","ipa":"/ˌɪntəˈsiːd/","tag":"plead for one side","definition":"to plead on behalf of someone, especially to someone in authority. The intercessor speaks for one party, while a mediator must keep both at the table.","definitionCN":"为某人向有权者求情。说情者为一方说话，而调解人必须把两方都留在桌边。"},{"word":"negotiate","ipa":"/ˈneɡəʊʃieɪt/","tag":"the parties themselves talk","definition":"to discuss in order to reach an agreement. In negotiation the two sides speak for themselves; mediation adds a third person between them.","definitionCN":"为达成协议而商谈。谈判时双方自己开口；调解则在两者之间再加一个人。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Latin medius 'middle', the verb mediare, and the family medium, media, mediation, mediator, immediate.","cn":"只用真实成分与真实同族词：拉丁语 medius“中间”、动词 mediare，以及 medium、media、mediation、mediator、immediate 这一族。"},"normal":[{"en":"medi- means 'middle'. To mediate is to put yourself in the middle, where both sides can reach you.","cn":"medi- 表示“中间”。mediate 就是把自己放到中间，让两边都够得着你。"},{"en":"In Latin, mediare first meant 'to halve', then 'to be in the middle'. The English verb began as 'divide in two', which is now obsolete.","cn":"拉丁语 mediare 最初意为“对半分”，后来才是“处在中间”。英语动词最初也表示“分成两半”，此义今已废弃。"},{"en":"The 1610s sense is the one to remember: 'act as a mediator'. The person in the middle starts to carry words across the gap.","cn":"要记住的是 17 世纪 10 年代那个义项：“充当调解人”。处在中间的人开始把话带过空隙。"},{"en":"medium and media come from the same medius: the middle layer becomes a channel, and a set of channels becomes the media.","cn":"medium 与 media 来自同一个 medius：中间层变成渠道，一组渠道就成了媒体。"},{"en":"immediate is im- 'not' plus medi- 'middle': no middle, no delay. That contrast is the clearest proof that medi- means 'middle'.","cn":"immediate 是 im-“不”加 medi-“中间”：没有中间，也就没有延迟。这个对比最能证明 medi- 就是“中间”。"}],"abstract":[{"en":"Picture two rooms with a thick wall and no door. The mediator is not the wall and not either room; the mediator is the door.","cn":"想象两个房间之间有一堵厚墙，没有门。调解人不是墙，也不属于任何一个房间；调解人就是那扇门。"},{"en":"A mediator holds no weapon and no vote. The only power in the middle chair is that both sides are still willing to hear the sentence spoken from it.","cn":"调解人手里没有武器，也没有投票权。中间那把椅子唯一的权力，是两边仍愿意听从这里说出的话。"},{"en":"The same word covers the bridge and the signal that crosses it: a middle layer can be a person, a substance, or a screen.","cn":"同一个词既指桥，也指过桥的信号：中间层可以是人、是物质，也可以是一块屏幕。"}]},"examples":[{"en":"A former colonial judge was brought in to mediate the border dispute.","cn":"一位前殖民地法官被请来调解这场边界争端。"},{"en":"The two departments could not speak directly, so the director mediated.","cn":"两个部门无法直接对话，于是由总监居中斡旋。"},{"en":"Nothing reaches us unmediated: even the sky we see passes through instruments and models.","cn":"没有什么是无中介地抵达我们的：连我们看见的天空也要穿过仪器与模型。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“米迪埃特”——米迪站在两边之间，左手拉住一个、右手拉住一个 → mediate 居中调解（只借音，不表词源）","word":"mediate"},"root":"源自拉丁语 medius“中间”，经动词 mediare“处在中间”而来，核心是“把自己放到两方之间的空位上”。","sensesIntro":{"en":"Nine senses of mediate, all built on one position: a body placed in the middle, which first merely occupies the gap, then speaks across it, then becomes the channel through which anything at all must pass.","cn":"mediate 的九个义项都建立在同一个位置上：一个被放在中间的身体。它先是占据空隙，继而隔着空隙说话，最后成为任何东西都必须穿过的通道。"},"semanticMap":{"core":{"en":"CORE IMAGE: a chair placed between two parties who cannot reach each other.","cn":"核心意象：一把椅子被放在两个够不到对方的阵营之间。"},"chain":["TWO SIDES APART","A PLACE IN THE MIDDLE","SOMEONE STEPS IN","WORDS CROSS THE GAP","AN AGREEMENT IS MADE","THE MIDDLE BECOMES A CHANNEL"],"branches":[{"senses":"S1","en":"POSITION: the oldest picture is spatial — something simply lies between two others.","cn":"位置：最古老的画面是空间的——某物就横在另两物之间。"},{"senses":"S2 · S3","en":"RECONCILIATION: the middle person starts to speak, and the talking ends in a settlement.","cn":"和解：中间的人开始说话，而这场谈话最终落到一份和解上。"},{"senses":"S4 · S5","en":"CHANNEL: the middle layer carries sound, news or feeling, and therefore alters what it carries.","cn":"通道：中间层运送声音、消息或情感，因此也改变了它所运送的东西。"},{"senses":"S6 · S7","en":"INDIRECTION: in grammar and philosophy the same gap becomes 'not immediate' and 'known through something else'.","cn":"间接性：在语法与哲学里，同一道空隙变成“非直接的”与“经由他物而知的”。"},{"senses":"S8 · S9","en":"INSTITUTION: law and diplomacy turn the act into a procedure, and theology turns the middle chair into a mediator between heaven and earth.","cn":"制度：法律与外交把这一行为变成程序，神学则把中间那把椅子变成天地之间的中保。"}]},"affixes":{"intro":{"en":"Mediate is a Latin verb borrowed whole: the stem medi- 'middle' plus the verb ending -ate. English then adds -ion, -or and un- to build the rest of the family.","cn":"mediate 是整体借入的拉丁语动词：词干 medi-“中间”加动词词尾 -ate。英语再以 -ion、-or 与 un- 构成其余词族。"},"latinIntro":{"en":"Latin medius 'middle' gives the stem; mediare 'to halve, to be in the middle' gives the verb; mediatio and mediator give the nouns. The root goes back to PIE *medhyo-, also behind medium and media.","cn":"拉丁语 medius“中间”提供词干；mediare“对半分、处在中间”提供动词；mediatio 与 mediator 提供名词。这个词根可追溯到原始印欧语 *medhyo-，medium 与 media 也来自它。"},"items":[{"word":"mediate","structure":"medi- (middle) + -ate (verb)","meaning":"to be in the middle; to bring two sides together","meaningCN":"处在中间；使两方走到一起（medi- 中间 + -ate 动词词尾）","example":"A neutral country offered to mediate the talks.","exampleCN":"一个中立国提出为谈判作调解。"},{"word":"mediation","structure":"mediat- + -ion (noun of action)","meaning":"the act or process of mediating","meaningCN":"调解；斡旋（-ion 构成行为名词）","example":"The contract was saved by two weeks of mediation.","exampleCN":"合同靠两周的调解得以保全。"},{"word":"mediator","structure":"mediat- + -or (person who acts)","meaning":"one who mediates between parties","meaningCN":"调解人；中间人（-or 表示施动者）","example":"The mediator met each side separately before the joint session.","exampleCN":"调解人在联席会议前分别见了双方。"},{"word":"mediatrix","structure":"mediat- + -trix (feminine agent)","meaning":"a female mediator","meaningCN":"女调解人（-trix 为拉丁语阴性施动后缀）","example":"The order honours the Virgin as mediatrix.","exampleCN":"该修会尊圣母为中保。"},{"word":"mediated","structure":"mediate + -ed (past participle)","meaning":"carried or reached through an intermediary","meaningCN":"经中介传递的；间接获得的（-ed 构成分词形容词）","example":"The mediated version of the story was kinder than the original.","exampleCN":"经中介转述的版本比原话温和。"},{"word":"unmediated","structure":"un- (not) + mediated","meaning":"direct, with nothing in between","meaningCN":"无中介的；直接的（un- 表否定）","example":"She wanted unmediated contact with the readers.","exampleCN":"她想要与读者直接接触，不要中间环节。"},{"word":"immediate","structure":"im- (not) + medi- (middle) + -ate","meaning":"with no middle step or delay","meaningCN":"立即的；直接的（im- 不 + medi- 中间，即“没有中间”）","example":"The reply was immediate.","exampleCN":"回复立刻就到了。"},{"word":"intermediate","structure":"inter- (between) + medi- (middle) + -ate","meaning":"lying or occurring between two stages","meaningCN":"中间的；中级的（inter- 在……之间 + medi- 中间）","example":"She joined an intermediate class after the placement test.","exampleCN":"分级测试后她进了中级班。"},{"word":"medium","structure":"medi- (middle) + -um (neuter noun ending)","meaning":"a middle layer; a channel of communication","meaningCN":"介质；媒介；中间物（-um 为中性名词词尾）","example":"Water is a good medium for sound.","exampleCN":"水是声音的良好介质。"},{"word":"media","structure":"medium + -a (neuter plural)","meaning":"the channels of public communication","meaningCN":"媒体；传播渠道（-a 为中性复数词尾）","example":"The media covered the talks from outside the building.","exampleCN":"媒体在大楼外报道了会谈。"},{"word":"medieval","structure":"medi- (middle) + aevum (age) + -al","meaning":"of the middle ages","meaningCN":"中世纪的（medi- 中间 + aevum 时代）","example":"The town wall is a medieval survival.","exampleCN":"这道城墙是中世纪留下的。"},{"word":"Mediterranean","structure":"medi- (middle) + terra (land) + -anean","meaning":"the sea in the middle of the lands","meaningCN":"地中海（medi- 中间 + terra 陆地，即“陆地中间的海”）","example":"The Mediterranean lies between three continents.","exampleCN":"地中海位于三大洲之间。"}],"latinEntries":[{"word":"medius","structure":"PIE *medhyo- 'middle'","meaning":"in the middle, between","meaningCN":"中间的；在两者之间"},{"word":"mediare","structure":"medius + -are (verb ending)","meaning":"to halve; to be in the middle","meaningCN":"对半分；处在中间"},{"word":"mediatio","structure":"mediat- + -io (noun of action)","meaning":"a division in the middle; mediation","meaningCN":"从中间分开；调解"},{"word":"mediator","structure":"mediat- + -or (agent noun)","meaning":"one who intervenes between parties","meaningCN":"在双方之间介入的人；调解人"}]}},{"word":"medical","ipa_uk":"/ˈmedɪkl/","ipa_us":"/ˈmedɪkl/","definition_zh":"医疗的；医学的；内科的；身体状况的；（名词）体检","definition_en":"relating to the practice, profession or study of medicine, to treatment that is not surgical, or to a person's health and health records","core_image":"白大褂口袋里露出一截听诊器，背后夹着一叠病历","scene":"She kept a medical kit in the car and a copy of her hospital records in her bag.","sceneCN":"这里 medical 是「医疗的、医学的」（第 1 个义项：属于医疗职业与医学学科）；句意：她在车里放着医药箱，包里带着一份病历复印件。场景要点：一只白色药箱、一叠写满记录的纸、袋口露出的听诊器。","pos":[{"tag":"adj.","zh":"医疗的；医学的；内科的；与健康状况有关的"},{"tag":"n.","zh":"体检（英式口语，medical examination 的缩略）"}],"collocations":[{"phrase":"medical care","zh":"医疗照护"},{"phrase":"medical treatment","zh":"医疗；内科治疗"},{"phrase":"medical history","zh":"病史"},{"phrase":"medical school","zh":"医学院"},{"phrase":"medical records","zh":"病历；医疗记录"},{"phrase":"medical examination","zh":"体检；医学检查"},{"phrase":"medical leave","zh":"病假"}],"forms":[{"label":"名词复数（“体检”义；形容词无屈折）","form":"medicals"}],"derivatives":[{"word":"medicine","pos":"n.","zh":"医学；医术；药物"},{"word":"medicinal","pos":"adj.","zh":"有药效的；药用的"},{"word":"medicate","pos":"v.","zh":"用药物治疗；给……用药"},{"word":"medication","pos":"n.","zh":"药物；用药治疗"},{"word":"medically","pos":"adv.","zh":"从医学上讲；医学上"},{"word":"medic","pos":"n.","zh":"医生；医学生；战地卫生员"}],"senses":[{"no":"01","title":"Of the profession","titleCN":"医疗职业与学科：属于医生这一行","definition":"relating to the profession, practice or study of medicine","definitionCN":"与医学职业、医疗实践或医学学科有关的","example":"She applied to three medical schools and was accepted by two.","exampleCN":"她申请了三所医学院，被其中两所录取。","why":"Medical entered English in the 1640s from Late Latin medicalis, 'of a physician', from medicus 'physician'. The adjective first names whatever belongs to doctors.","whyCN":"medical 于 17 世纪 40 年代从晚期拉丁语 medicalis 进入英语，意为“医生的”，源自 medicus“医生”。这个形容词最初用来命名一切属于医生的东西。"},{"no":"02","title":"Medical versus surgical","titleCN":"内科的：与外科相对的那一半","definition":"relating to treatment by drugs and other non-surgical means, as opposed to surgery","definitionCN":"指以药物及其他非手术手段进行的治疗，与外科相对","example":"He was moved from the surgical ward to the medical ward for observation.","exampleCN":"他从外科病房转到内科病房接受观察。","why":"Inside one profession, medical marks the branch that treats with medicine rather than the knife. The word draws a line within the hospital, not outside it.","whyCN":"在同一个行业内部，medical 标记的是用药物而不是用刀的那一支。这个词画的是医院内部的界线，而不是对外的界线。"},{"no":"03","title":"The patient's condition","titleCN":"身体状况与病史：属于这个人的健康","definition":"relating to a person's health, illnesses and physical condition","definitionCN":"与某人的健康、疾病和身体状况有关的","example":"The form asks for your medical history and any allergies.","exampleCN":"这张表格要求填写你的病史和过敏情况。","why":"The adjective shifts from the profession to the patient: what belongs to the physician's domain becomes the record of a body's past.","whyCN":"这个形容词从职业转到病人身上：原本属于医生领域的东西，变成了一个身体过往的记录。"},{"no":"04","title":"A medical: the check-up","titleCN":"体检：形容词被剪成一个名词","definition":"a medical examination","definitionCN":"体检；医学检查","example":"He passed his medical and joined the crew in March.","exampleCN":"他通过了体检，三月加入了船员队伍。","why":"Recorded from 1917 as a shortening of medical examination. English often clips a familiar adjective-plus-noun phrase into the adjective alone.","whyCN":"1917 年起有记录，是 medical examination 的缩略。英语常把熟悉的“形容词加名词”词组剪成只剩形容词。"},{"no":"05","title":"A medical: the doctor","titleCN":"医学生、医生：旧时的口语名词","definition":"in older colloquial use, a medical student or a doctor","definitionCN":"旧时口语中指医科学生或医生","example":"The old novels speak of a medical coming to the house at midnight.","exampleCN":"旧小说里常写一位医生半夜上门。","why":"The noun use is recorded from 1823. A person is named by what he or she studies or practises, so the adjective stands alone as a human subject.","whyCN":"名词用法自 1823 年有记录。人被以他所学或所做的事来称呼，于是这个形容词单独站出来指人。"},{"no":"06","title":"Medical evidence","titleCN":"法律与保险中的医学鉴定","definition":"used of reports, evidence and certificates that come from doctors and carry legal or official weight","definitionCN":"指来自医生、具有法律或官方效力的报告、证据与证明","example":"The court ordered a medical report before deciding on the claim.","exampleCN":"法院在裁定索赔之前下令出具一份医学报告。","why":"Once medicine enters law, its documents become evidence. Medical marks the source of authority behind the paper.","whyCN":"一旦医学进入法律，它的文书就成了证据。medical 标记的是这张纸背后的权威来源。"},{"no":"07","title":"Medical equipment","titleCN":"器械与技术：复合词里的限定语","definition":"used in compounds for equipment, imaging and technology employed in health care","definitionCN":"用于复合词，指医疗照护中使用的设备、影像与技术","example":"The charity shipped medical supplies and two portable ultrasound machines.","exampleCN":"这家慈善机构运去了医疗物资和两台便携超声仪。","why":"As a classifying adjective it can attach to any object used in care, from a glove to a scanner, without changing its own meaning.","whyCN":"作为分类形容词，它可以附着在任何用于照护的物件上，从手套到扫描仪，而自身含义不变。"},{"no":"08","title":"Medical leave","titleCN":"病假与证明：制度里的一个类别","definition":"used in employment contexts for leave or certificates that excuse absence because of illness","definitionCN":"用于雇佣语境，指因病请假或证明缺勤正当的证明文件","example":"She took five days of medical leave after the operation.","exampleCN":"手术之后她请了五天病假。","why":"Institutions need a word for absence backed by a doctor. Medical turns an illness into a recognised administrative category.","whyCN":"机构需要一个词来指“有医生作保的缺勤”。medical 把一场病变成一个被承认的行政类别。"},{"no":"09","title":"Medical, not medicinal","titleCN":"与 medicinal 的分界：说用途，不说药效","definition":"describing the setting or profession of health care, not the healing power of a substance","definitionCN":"描述医疗的场景或职业，而不是某物质本身具有的治疗效力","example":"Medical use is the right phrase for a clinic; medicinal use describes a herb that actually heals.","exampleCN":"诊所的用途该说医疗用途；而药用价值说的是某种草药确实能治病。","why":"Medicinal arrived first, in the mid-14th century, meaning 'having curative properties'. Medical came later and names the profession, so the pair divides into 'who treats' and 'what cures'.","whyCN":"medicinal 先到，14 世纪中叶就有，意为“具有治疗效力的”。medical 来得更晚，命名的是职业，于是这一对词分成“谁来治”与“什么能治”。"}],"etymology":{"intro":{"en":"Medical is a Latin adjective borrowed through French, built on medicus 'physician'. Its root means 'take appropriate measures', not 'middle', and it has no connection with method. Dates are approximate.","cn":"medical 是经法语借入的拉丁语形容词，建立在 medicus“医生”之上。它的词根意为“采取恰当措施”，不是“中间”，并且与 method 毫无关系。年代为大致估计。"},"items":[{"era":"1640s","en":"First recorded in English as 'pertaining to the art or profession of healing, or to those who practise it'. It came through French médical from Late Latin medicalis 'of a physician'.","cn":"英语中最早记录于 17 世纪 40 年代，意为“与治疗之术或行业、与行医者有关的”。它经法语 médical 来自晚期拉丁语 medicalis“医生的”。"},{"era":"LATIN medicus","en":"Latin medicus was both a noun, 'physician, surgeon, medical man', and an adjective, 'healing, medicinal'. It comes from medeor 'to cure, heal', originally 'know the best course for'.","cn":"拉丁语 medicus 既是名词“医生、外科医生、医者”，也是形容词“治疗的、药用的”。它来自 medeor“治愈、治疗”，原义为“知道最好的做法”。"},{"era":"PIE *MED-","en":"The root *med- means 'take appropriate measures'. De Vaan explains medeor as a shift from 'measure' to 'distribute a cure, heal'; Avestan vi-mad- 'physician' belongs to the same family.","cn":"词根 *med- 意为“采取恰当措施”。de Vaan 把 medeor 解释为从“量度”转向“分配药剂、治疗”；阿维斯陀语 vi-mad-“医生”同属这一族。"},{"era":"MID-14C","en":"The earlier English adjective in this sense was medicinal, 'having healing or curative properties', from Latin medicinalis. Medical later took over the professional sense.","cn":"英语中较早表示这一意义的形容词是 medicinal，即“有治疗或治愈效力的”，来自拉丁语 medicinalis。medical 后来接管了职业性的那一层意义。"},{"era":"1823 / 1917","en":"The noun is recorded from 1823 colloquially for 'a medical student or practitioner', and from 1917 as a shortening of medical examination.","cn":"名词用法 1823 年起有口语记录，指“医科学生或医生”；1917 年起则是 medical examination（体检）的缩略。"},{"era":"NOT METHOD","en":"Medical and method share only their letters. Method is Greek methodos, meta 'in pursuit of' plus hodos 'road'; no Latin medicus is involved. The -met- shape in the two words is a coincidence, and medicine (c. 1200) likewise comes from medicina, not from medical.","cn":"medical 与 method 只共享字母外形。method 是希腊语 methodos，由 meta“追寻”加 hodos“路”构成，其中没有任何拉丁语 medicus 的成分。两个词里的 -met- 外形纯属巧合；medicine（约 1200 年）同样来自 medicina，而不是来自 medical。"}]},"similar":{"note":{"en":"The first group is the real medic- family: the substance, the healing property, the act of dosing, and the pills themselves. The second group compares adjectives used in and around health care.","cn":"第一组是真正的 medic- 词族：医学本身、治疗效力、用药动作、以及药片本身。第二组比较医疗领域内外的几个形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"medicine","ipa":"/ˈmedɪsn/","tag":"the field or the substance","definition":"the science and practice of treating disease, or a substance taken to treat illness. It is the thing and the field; medical is only the adjective that points at them.","definitionCN":"治疗疾病的科学与实践，或用来治病的物质。它是事物与领域本身；medical 只是指向它们的形容词。"},{"word":"medicinal","ipa":"/məˈdɪsɪnl/","tag":"having healing power","definition":"having curative properties, or used as a medicine. A medicinal herb heals; a medical herb is merely one a doctor might study.","definitionCN":"具有治疗效力的，或作药用的。medicinal 的草药能治病；medical 的草药只是医生可能会研究的那种草。"},{"word":"medicate","ipa":"/ˈmedɪkeɪt/","tag":"verb: to dose","definition":"to treat with medicine, or to add a drug to something. It names the act that medical describes only indirectly.","definitionCN":"用药物治疗，或往某物里加药。它命名的是 medical 只间接描述的那个动作。"},{"word":"medication","ipa":"/ˌmedɪˈkeɪʃn/","tag":"the drug or the regime","definition":"a medicinal substance, or the treatment of a condition with drugs. Since 1942 it has been the everyday word for prescribed pills.","definitionCN":"药物，或用药物处理某种病情。自 1942 年起，它成了“处方药”的日常说法。"}]},{"heading":"NEAR MEANING","entries":[{"word":"clinical","ipa":"/ˈklɪnɪkl/","tag":"at the bedside","definition":"relating to the observation and treatment of patients, or to a clinic. Clinical stresses the setting and the method; medical stresses the profession as a whole.","definitionCN":"与病人的观察和治疗有关的，或与诊所相关的。clinical 强调场景与方法；medical 强调整个行业。"},{"word":"therapeutic","ipa":"/ˌθerəˈpjuːtɪk/","tag":"having a healing effect","definition":"relating to the healing of disease, or having a calming or restorative effect. It is closer to medicinal than to medical.","definitionCN":"与疾病治疗有关的，或有镇静、康复效果的。它更接近 medicinal，而不是 medical。"},{"word":"surgical","ipa":"/ˈsɜːdʒɪkl/","tag":"the operating branch","definition":"relating to surgery. It is the usual opposite of medical inside a hospital, where medical means treatment by drugs rather than by operation.","definitionCN":"与外科手术有关的。在医院内部它常是 medical 的对立面，那里的 medical 指用药物治疗而非手术。"},{"word":"paramedical","ipa":"/ˌpærəˈmedɪkl/","tag":"beside medicine","definition":"relating to the auxiliary services that support medical work, such as ambulance crews and lab technicians. The prefix para- 'beside' marks the supporting role.","definitionCN":"与辅助医疗服务有关的，如救护人员与化验员。前缀 para-“在旁边”标记的是支持性的角色。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Latin medicus 'physician', mederi 'to heal', the older adjective medicinal, and the modern family medicine, medication, medic.","cn":"只用真实成分与真实同族词：拉丁语 medicus“医生”、mederi“治疗”、更早的形容词 medicinal，以及现代的 medicine、medication、medic 词族。"},"normal":[{"en":"medic- means 'physician'. Medical is simply the adjective of the doctor's world, as in medical school and medical records.","cn":"medic- 表示“医生”。medical 就是医生那个世界的形容词，如 medical school（医学院）、medical records（病历）。"},{"en":"The deeper root *med- means 'take appropriate measures'. Healing began as the art of knowing the right measure.","cn":"更深的词根 *med- 意为“采取恰当措施”。治疗最初就是“知道该用多少分量”的技艺。"},{"en":"medicinal is older and means 'having healing power'; medical is younger and means 'of the profession'. A medicinal plant heals, a medical student studies.","cn":"medicinal 更老，意为“有治疗效力的”；medical 更年轻，意为“属于这一行业的”。药草能治病，医学生则在读书。"},{"en":"A medical (noun) is a check-up: the adjective swallowed the noun examination in 1917.","cn":"名词 a medical 就是体检：1917 年这个形容词把名词 examination 吞掉了。"},{"en":"Method looks similar but is Greek: meta plus hodos 'road'. Medical has no road in it, only a physician.","cn":"method 看着像，其实是希腊语：meta 加 hodos“路”。medical 里面没有路，只有一个医生。"}],"abstract":[{"en":"Picture a white coat with two pockets: one holds a stethoscope, the other a folder of records. The coat is medical; the herb in the garden is medicinal.","cn":"想象一件白大褂有两个口袋：一个装听诊器，一个装一叠病历。这件外套是 medical；园子里的那株草药是 medicinal。"},{"en":"The word always points at people and their apparatus, never at the power of a plant. That is why a hospital is medical and a cough syrup is medicinal.","cn":"这个词总是指向人及其器械，从不指向植物的效力。所以医院是 medical，止咳糖浆是 medicinal。"},{"en":"A whole institution hides behind three syllables: school, ward, record, certificate, leave. Each is a room the adjective has learned to enter.","cn":"三个音节背后藏着一整套机构：学院、病房、病历、证明、病假。每一个都是这个形容词学会进入的房间。"}]},"examples":[{"en":"The village has no medical staff, only a nurse who comes twice a week.","cn":"这个村子没有医务人员，只有一名每周来两次的护士。"},{"en":"The insurance company asked for the medical report before paying.","cn":"保险公司在付款前要求提供医学报告。"},{"en":"She was on medical leave for a month and came back thinner and quieter.","cn":"她休了一个月病假，回来时瘦了，也沉默了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“麦迪扣”——麦迪把白大褂的扣子扣好，口袋里插着听诊器 → medical 医疗的、医学的（只借音，不表词源）","word":"medical"},"root":"源自拉丁语 medicus“医生”与 mederi“治疗”，词根 *med- 意为“采取恰当措施”，核心是“为身体采取正确的救治手段”。","sensesIntro":{"en":"Nine senses of medical, all radiating from one point: whatever belongs to the physician's world — the school, the ward, the record, the certificate, the machine — and finally the patient's own body as that world describes it.","cn":"medical 的九个义项都从一个点辐射出去：一切属于医生世界的东西——学院、病房、病历、证明、机器——最后是那个世界所描述的病人身体本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: a white coat whose pockets hold a stethoscope and a folder of records.","cn":"核心意象：一件白大褂，口袋里装着听诊器和一叠病历。"},"chain":["MEASURE WHAT IS WRONG","TAKE THE RIGHT MEASURES","THE HEALING ART","THOSE WHO PRACTISE IT","WHAT BELONGS TO THEM","THE PATIENT AND THE PAPER"],"branches":[{"senses":"S1 · S2","en":"THE PROFESSION: medical names the field and also the drug-treating half of it, set against surgery.","cn":"行业：medical 命名这一领域，也命名其中用药治疗的那一半，与外科相对。"},{"senses":"S3","en":"THE BODY: the adjective moves from doctors to the patient, naming health, illness and history.","cn":"身体：这个形容词从医生移到病人身上，命名健康、疾病与病史。"},{"senses":"S4 · S5","en":"CLIPPED NOUNS: English shortens 'medical examination' to a medical, and once shortened 'medical man' to the same form.","cn":"截短名词：英语把 medical examination 缩成 a medical，也曾把 medical man 缩成同一个形式。"},{"senses":"S6 · S8","en":"INSTITUTIONS: law, insurance and employment turn medical into documents, evidence and leave.","cn":"制度：法律、保险与雇佣把 medical 变成文书、证据与病假。"},{"senses":"S7 · S9","en":"OBJECTS AND BOUNDARY: the adjective classifies equipment, and stops short of medicinal, which describes healing power rather than professional setting.","cn":"物件与边界：这个形容词为器械分类，同时止步于 medicinal——后者描述治疗效力，而不是职业场景。"}]},"affixes":{"intro":{"en":"Medical is Latin medicus plus the adjective ending -alis, softened in English to -al. The stem medic- is not a free English word, but it carries the whole family.","cn":"medical 是拉丁语 medicus 加形容词词尾 -alis，进入英语后软化为 -al。词干 medic- 在英语里不能单独成词，却撑起整个词族。"},"latinIntro":{"en":"Latin medicus 'physician' and mederi 'to heal' go back to PIE *med- 'take appropriate measures'. Latin medicina gave English medicine; medicinalis gave medicinal; medicatio gave medication. There is no Greek element in medical.","cn":"拉丁语 medicus“医生”与 mederi“治疗”可追溯到原始印欧语 *med-“采取恰当措施”。拉丁语 medicina 给出英语 medicine；medicinalis 给出 medicinal；medicatio 给出 medication。medical 里没有任何希腊语成分。"},"items":[{"word":"medical","structure":"medic- (physician) + -al (adjective)","meaning":"of or relating to medicine and physicians","meaningCN":"医疗的；医学的（medic- 医生 + -al 形容词词尾）","example":"The medical team arrived before the ambulances.","exampleCN":"医疗队在救护车之前就到了。"},{"word":"medicine","structure":"medic- (physician) + -ine (noun)","meaning":"the healing art; a remedy","meaningCN":"医学；医术；药物（-ine 构成名词）","example":"Medicine has changed more in thirty years than in three centuries.","exampleCN":"医学在三十年里的变化超过了过去三个世纪。"},{"word":"medicinal","structure":"medicin- + -al (adjective)","meaning":"having curative properties","meaningCN":"有治疗效力的；药用的","example":"The root has a medicinal taste that children hate.","exampleCN":"这种根有孩子讨厌的药味。"},{"word":"medicate","structure":"medic- + -ate (verb)","meaning":"to treat with medicine","meaningCN":"用药物治疗；给……用药（-ate 构成动词）","example":"The water is medicated with chlorine.","exampleCN":"水里加了氯。"},{"word":"medication","structure":"medicat- + -ion (noun of action)","meaning":"treatment with drugs; a medicinal substance","meaningCN":"药物治疗；药物（-ion 构成名词）","example":"He takes his medication after breakfast.","exampleCN":"他早饭后服药。"},{"word":"medically","structure":"medical + -ly (adverb)","meaning":"in medical terms; from a medical point of view","meaningCN":"从医学上讲（-ly 构成副词）","example":"The condition is medically unexplained.","exampleCN":"这种情况在医学上无法解释。"},{"word":"medic","structure":"medic- (shortened stem)","meaning":"a doctor, student of medicine, or battlefield medical orderly","meaningCN":"医生；医学生；战地卫生员（截短词干）","example":"A medic stopped the bleeding at the roadside.","exampleCN":"一名卫生员在路边止住了血。"},{"word":"biomedical","structure":"bio- (life) + medical","meaning":"relating to biology and medicine together","meaningCN":"生物医学的（bio- 生命 + medical）","example":"The lab won a grant for biomedical research.","exampleCN":"该实验室获得了生物医学研究的资助。"},{"word":"paramedical","structure":"para- (beside) + medical","meaning":"supporting medical work without being a doctor","meaningCN":"辅助医疗的（para- 在旁边 + medical）","example":"Paramedical staff handle the first response.","exampleCN":"辅助医疗人员负责第一时间的处置。"},{"word":"premedical","structure":"pre- (before) + medical","meaning":"of the studies taken before medical school","meaningCN":"医学预科的（pre- 之前 + medical）","example":"She finished her premedical courses in two years.","exampleCN":"她两年读完了医学预科课程。"},{"word":"medicament","structure":"medic- + -ment (noun)","meaning":"a substance used as a remedy","meaningCN":"药物；药剂（-ment 构成名词）","example":"The old pharmacopoeia lists hundreds of medicaments.","exampleCN":"那本旧药典列了数百种药剂。"}],"latinEntries":[{"word":"medicus","structure":"PIE *med- 'take appropriate measures'","meaning":"physician; healing, medicinal","meaningCN":"医生；治疗的、药用的"},{"word":"mederi","structure":"from *med- with a verbal ending","meaning":"to cure, heal; originally 'to know the best course for'","meaningCN":"治愈；原义“知道最好的做法”"},{"word":"medicina","structure":"medicus + -ina (noun)","meaning":"the healing art; a remedy","meaningCN":"医术；药物"}]}},{"word":"mental","ipa_uk":"/ˈmentl/","ipa_us":"/ˈmentl/","definition_zh":"心理的；精神的；心智的；脑力的；精神疾病的；（英口）发疯的","definition_en":"relating to the mind, to thinking and feeling, or to psychiatric illness","core_image":"颅骨里亮着的一盏灯：看不见的思虑在里面持续燃烧","scene":"The coach spends the first hour on mental preparation and only then lets the players touch the ball.","sceneCN":"这里 mental 是「心智的、心理的」（第 1 个义项：属于头脑与思维活动）；句意：教练第一个小时做心理准备，之后才让球员碰球。场景要点：场边围坐的队员、闭上的眼睛、教练手里的战术板。","pos":[{"tag":"adj.","zh":"心理的；精神的；心智的；脑力的"},{"tag":"n.","zh":"精神失常的人（英式口语，含贬义）"}],"collocations":[{"phrase":"mental health","zh":"心理健康"},{"phrase":"mental illness","zh":"精神疾病"},{"phrase":"mental hospital","zh":"精神病院"},{"phrase":"mental state","zh":"精神状态"},{"phrase":"mental arithmetic","zh":"心算"},{"phrase":"mental capacity","zh":"心智能力；（法律）行为能力"},{"phrase":"mental preparation","zh":"心理准备"}],"forms":[{"label":"名词复数（英式口语“疯子”义，少用；形容词无屈折）","form":"mentals"}],"derivatives":[{"word":"mentality","pos":"n.","zh":"心态；思维方式；智力水平"},{"word":"mentally","pos":"adv.","zh":"心理上；精神上；在脑中"},{"word":"mentalist","pos":"n.","zh":"读心术表演者；唯心论者"},{"word":"mentalism","pos":"n.","zh":"心灵主义；唯心论"},{"word":"mentalistic","pos":"adj.","zh":"心灵主义的；唯心论的"},{"word":"mentalize","pos":"v.","zh":"心智化；把……理解为心理活动"}],"senses":[{"no":"01","title":"Of the mind","titleCN":"心智的：发生在头脑里的事","definition":"relating to the mind or to thinking, as opposed to the body","definitionCN":"与心智或思维有关的，与身体相对","example":"Reading a map is a mental skill, not a physical one.","exampleCN":"看地图是一项心智技能，而不是体力技能。","why":"Mental entered English in the early 15th century from Late Latin mentalis, from Latin mens 'mind'. The adjective simply marks what happens inside the head.","whyCN":"mental 于 15 世纪初从晚期拉丁语 mentalis 进入英语，源自拉丁语 mens“心智”。这个形容词只标记在头脑内部发生的事。"},{"no":"02","title":"Psychological health","titleCN":"心理的：情绪与心理状态","definition":"relating to a person's emotional and psychological condition","definitionCN":"与一个人的情绪与心理状况有关的","example":"The clinic offers mental health services for teenagers.","exampleCN":"这家诊所为青少年提供心理健康服务。","why":"Mental health is recorded from 1803. Once the mind has a health of its own, the adjective moves from describing thought to naming a field of care.","whyCN":"mental health 自 1803 年有记录。一旦心智有了自己的健康，这个形容词就从描述思维转为命名一个照护领域。"},{"no":"03","title":"Of the soul","titleCN":"精神的：心灵层面的旧义","definition":"in older use, relating to the soul or the inner, spiritual life","definitionCN":"在较早用法中，与灵魂或内在精神生活有关的","example":"The old prayer asks for mental peace rather than bodily comfort.","exampleCN":"那篇古老的祷文求的是心灵的安宁，而不是身体的舒适。","why":"In Middle English, mental also meant 'of the soul, spiritual'. Before medicine divided mind from body, the word covered the whole inner life.","whyCN":"在中古英语里，mental 也意为“灵魂的、精神的”。在医学把心智与身体分开之前，这个词覆盖的是整个内在生活。"},{"no":"04","title":"Intellectual effort","titleCN":"脑力的：劳动落在头脑上","definition":"requiring or involving thought and intellect rather than physical work","definitionCN":"需要或涉及思考与智力，而非体力劳动","example":"Mental labour can exhaust a person as surely as lifting does.","exampleCN":"脑力劳动照样能把人累垮，就像搬运一样。","why":"From the 1520s the word meant 'done or performed in the mind'. Effort shifts from the muscles to the brain, and the adjective follows it.","whyCN":"自 16 世纪 20 年代起，这个词意为“在头脑中完成的”。力气从肌肉转到大脑，形容词也跟着转了过去。"},{"no":"05","title":"Done inside the head","titleCN":"默算默想：不外化的过程","definition":"performed silently in the mind, without writing or speaking","definitionCN":"不写出来也不说出来，在脑中默默完成","example":"She did the sum mentally and wrote only the answer.","exampleCN":"她心算了那道题，只写下答案。","why":"Mental arithmetic keeps the whole operation invisible. The adjective marks work that leaves no trace until the result appears.","whyCN":"心算把整个运算过程藏了起来。这个形容词标记的是那种直到结果出现才留下痕迹的劳动。"},{"no":"06","title":"Psychiatric illness","titleCN":"精神疾病的：临床标签","definition":"relating to psychiatric illness, its institutions and its patients","definitionCN":"与精神疾病、其机构及病人有关的","example":"He was admitted to a mental hospital after the second episode.","exampleCN":"第二次发作后，他被送进了精神病院。","why":"Mental patient is recorded from 1859 and mental hospital from 1891. Once institutions exist, the adjective becomes a clinical address.","whyCN":"mental patient 自 1859 年有记录，mental hospital 自 1891 年有记录。一旦机构存在，这个形容词就变成了一个临床门牌号。"},{"no":"07","title":"Slang: crazy","titleCN":"口语：发疯的、脑子有毛病的","definition":"in informal British English, crazy or wildly unreasonable","definitionCN":"在英式口语中，指发疯的或极不合理的","example":"You are mental if you think that jump is safe.","exampleCN":"你要是觉得那样跳下去没事，那你真是疯了。","why":"The slang sense 'crazy, deranged' is recorded from 1927, probably from combinations such as mental patient. A clinical label leaks into the playground.","whyCN":"“发疯的、精神错乱的”这一俚语义自 1927 年有记录，很可能来自 mental patient 一类的组合。临床标签漏进了操场。"},{"no":"08","title":"Slang noun: a mad person","titleCN":"口语名词：疯子","definition":"in informal British English, a person who is mentally ill or behaves wildly","definitionCN":"在英式口语中，指精神失常或行为失控的人","example":"The driver was a complete mental and should never have been on the road.","exampleCN":"那个司机完全是个疯子，根本就不该上路。","why":"English often turns an adjective into a noun for a person who has the quality. Here the medical label becomes an insult.","whyCN":"英语常把形容词直接变成指人的名词。在这里，医学标签变成了骂人的话。"},{"no":"09","title":"Legal and clinical capacity","titleCN":"法律与临床：心智能力","definition":"in law and medicine, used of a person's ability to understand, decide and be responsible","definitionCN":"在法律与医学中，指一个人理解、决定与承担责任的能力","example":"The court asked whether the accused had the mental capacity to understand the charge.","exampleCN":"法院问的是被告是否有心智能力理解这项指控。","why":"Law needs the mind as a measurable fact, not a metaphor. Mental capacity turns the inner life into something a form can record.","whyCN":"法律需要把心智当成可测量的事实，而不是比喻。mental capacity 把内在生活变成表格上可以填写的东西。"}],"etymology":{"intro":{"en":"Mental comes from Latin mens (genitive mentis) 'mind' through Late Latin mentalis. Its root is PIE *men- 'to think'. The medical and middle senses of the letters 'ment' belong to other roots entirely. Dates are approximate.","cn":"mental 经由晚期拉丁语 mentalis 来自拉丁语 mens（属格 mentis）“心智”。它的词根是原始印欧语 *men-“思考”。字母 ment 所对应的“医疗”与“中间”两族词，属于完全另外的词根。年代为大致估计。"},"items":[{"era":"EARLY 15C","en":"First recorded as 'in, of, or pertaining to the mind; characteristic of the intellect'. It came from Late Latin mentalis 'of the mind', an adjective built on Latin mens.","cn":"最早记录为“在心智之中的、属于心智的；智力特征的”。它来自晚期拉丁语 mentalis“心智的”，是建立在拉丁语 mens 之上的形容词。"},{"era":"LATIN mens","en":"Latin mens (genitive mentis) means 'mind, intellect, thought, intention'. The stem ment- is what English borrows in mental, mentality and dementia.","cn":"拉丁语 mens（属格 mentis）意为“心智、智力、思想、意图”。英语在 mental、mentality、dementia 中借入的正是词干 ment-。"},{"era":"PIE *MEN-","en":"The root *men- (1) means 'to think'. It also lies behind English mind, a native Germanic cousin of Latin mens rather than a borrowing from it.","cn":"词根 *men-（第一支）意为“思考”。它也是英语 mind 的来源——mind 是拉丁语 mens 在日耳曼语里的本族表亲，而不是从拉丁语借来的。"},{"era":"MIDDLE ENGLISH","en":"Mental also meant 'of the soul, spiritual' in Middle English. The word covered the inner life before medicine separated mind from body.","cn":"在中古英语里，mental 也意为“灵魂的、精神的”。在医学把心智与身体分开之前，这个词覆盖的是整个内在生活。"},{"era":"1520s","en":"The sense 'done or performed in the mind' is recorded, the sense behind mental arithmetic and mental rehearsal.","cn":"记录到“在头脑中完成的”这一义项，它正是 mental arithmetic 与 mental rehearsal 背后的意思。"},{"era":"1803 / 1859 / 1927","en":"Mental health is recorded from 1803, mental illness from 1819, mental patient from 1859 and mental hospital from 1891. The slang sense 'crazy, deranged' follows in 1927, probably from those combinations.","cn":"mental health 自 1803 年有记录，mental illness 自 1819 年，mental patient 自 1859 年，mental hospital 自 1891 年。俚语义“发疯的、精神错乱的”在 1927 年出现，很可能来自这些组合。"}]},"similar":{"note":{"en":"The first group separates the native noun mind, the derived noun mentality, the adverb and the person word. The second group places mental against the adjectives it is most often confused with, including its usual opposite.","cn":"第一组区分本族名词 mind、派生名词 mentality、副词与指人的词。第二组把 mental 与最常混淆的几个形容词放在一起，包括它通常的对立面。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mind","ipa":"/maɪnd/","tag":"the noun itself","definition":"the faculty of thinking, or a person's thoughts and attention. It is the native English cousin of Latin mens, while mental is the borrowed adjective built on mens.","definitionCN":"思维的能力，或一个人的想法与注意力。它是拉丁语 mens 在英语里的本族表亲，而 mental 是建立在 mens 上的借入形容词。"},{"word":"mentality","ipa":"/menˈtæləti/","tag":"a habitual outlook","definition":"a typical way of thinking, or the level of a person's intellectual power. It is a countable pattern of mind, not a synonym of mental.","definitionCN":"典型的思维方式，或一个人的智力水平。它是可数的思维模式，不是 mental 的同义词。"},{"word":"mentally","ipa":"/ˈmentəli/","tag":"adverb","definition":"in the mind, or with respect to the mind. It modifies a verb ('mentally rehearsed') where mental would modify a noun.","definitionCN":"在脑中，或就心智而言。它修饰动词（如 mentally rehearsed），而 mental 修饰名词。"},{"word":"mentalist","ipa":"/ˈmentəlɪst/","tag":"person noun","definition":"a performer who appears to read minds, or a believer in mentalism. It never means 'a mental person'.","definitionCN":"看似能读心的表演者，或心灵主义的信奉者。它从不表示“精神失常的人”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"psychological","ipa":"/ˌsaɪkəˈlɒdʒɪkl/","tag":"scientific and emotional","definition":"relating to the study of the mind and behaviour, or to a person's inner emotional state. It is more technical than mental and often replaces it in careful writing.","definitionCN":"与心理学研究或一个人的内在情绪状态有关的。它比 mental 更技术化，在严谨写作中常替代 mental。"},{"word":"psychiatric","ipa":"/ˌsaɪkiˈætrɪk/","tag":"clinical treatment","definition":"relating to the medical treatment of mental illness. It names the clinic, while mental can still be a neutral word for the mind.","definitionCN":"与精神疾病的医学治疗有关的。它命名的是临床，而 mental 仍可中性地指心智。"},{"word":"intellectual","ipa":"/ˌɪntəˈlektʃuəl/","tag":"capacity for thought","definition":"relating to the intellect and its exercise, especially in learning and analysis. It praises the work of the mind; mental merely locates it.","definitionCN":"与智力及其运用有关的，尤其在学习与分析中。它赞赏头脑的工作；mental 只标明位置。"},{"word":"physical","ipa":"/ˈfɪzɪkl/","tag":"the usual opposite","definition":"relating to the body rather than the mind. The pair mental and physical organises everyday talk about health, training and fatigue.","definitionCN":"与身体而非心智有关的。mental 与 physical 这一对词组织起了日常关于健康、训练与疲劳的说法。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Latin mens (genitive mentis) 'mind', PIE *men- 'to think', the English cousin mind, and the family mentality, mentally, dementia.","cn":"只用真实成分与真实同族词：拉丁语 mens（属格 mentis）“心智”、原始印欧语 *men-“思考”、英语表亲 mind，以及 mentality、mentally、dementia 词族。"},"normal":[{"en":"mens, mentis means 'mind'. Mental is the adjective of that noun: whatever belongs to the mind.","cn":"mens、mentis 意为“心智”。mental 就是这个名词的形容词：一切属于心智的东西。"},{"en":"The root *men- means 'to think', and it also gives the native English word mind. Mental is the borrowed twin of mind.","cn":"词根 *men- 意为“思考”，它也给出英语本族词 mind。mental 是 mind 的借入版双胞胎。"},{"en":"mentality is mental plus -ity: not the mind itself but its habitual shape, a way of thinking.","cn":"mentality 是 mental 加 -ity：不是心智本身，而是它习惯性的形状，即一种思维方式。"},{"en":"mentally is the adverb: it tells you where the work happens, as in mentally rehearsed.","cn":"mentally 是副词：它告诉你工作发生在哪里，如 mentally rehearsed（在脑中排练）。"},{"en":"Keep the fixed phrases straight: mental health, mental illness, mental hospital. These are clinical and neutral, not insults.","cn":"把固定搭配记准：mental health、mental illness、mental hospital。这些是临床且中性的说法，不是骂人。"}],"abstract":[{"en":"Picture a lit lamp inside a skull. Nobody outside can see the flame, only its light falling on what the person does next.","cn":"想象颅骨里点着一盏灯。外面的人看不见火焰，只看见火光落在这个人接下来的动作上。"},{"en":"The same lamp can be described in three registers: mental is everyday, psychological is scientific, psychiatric is clinical. One flame, three vocabularies.","cn":"同一盏灯可以用三种语域描述：mental 是日常的，psychological 是科学的，psychiatric 是临床的。一团火焰，三套词汇。"},{"en":"Because the light is invisible, the word is easily abused: it can name care, or it can become an insult. The phrase tells you which.","cn":"正因为光看不见，这个词容易被滥用：它可以命名照护，也可以变成侮辱。是哪个，要看它所在的短语。"}]},"examples":[{"en":"The injury healed in weeks, but the mental scars took years.","cn":"伤在几周内就愈合了，但心理上的伤痕花了好几年。"},{"en":"He ran the whole interview in his head, mentally correcting every answer.","cn":"他在脑子里把整场面试过了一遍，逐条修正每个回答。"},{"en":"The report calls for better mental health care in rural schools.","cn":"报告呼吁改善乡村学校的心理健康照护。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“门头儿”——门头儿里面亮着一盏灯，那是脑子里转个不停的念头 → mental 心理的、心智的（只借音，不表词源）","word":"mental"},"root":"源自拉丁语 mens（属格 mentis）“心智”，词根 *men- 意为“思考”，核心是“在头脑内部进行的活动”。","sensesIntro":{"en":"Nine senses of mental, all lit by one lamp inside the skull: first it simply marks where thought happens, then it names health, effort, silence, illness, insult and finally a legal fact.","cn":"mental 的九个义项都被颅骨里的同一盏灯照亮：它先只标记思考发生的位置，继而命名健康、劳动、沉默、疾病、辱骂，最后成为一种法律事实。"},"semanticMap":{"core":{"en":"CORE IMAGE: a lamp burning inside a skull, visible only through what the person does.","cn":"核心意象：颅骨里燃着的一盏灯，只能通过这个人的举动被看见。"},"chain":["INSIDE THE HEAD","NOT THE BODY","A HEALTH OF ITS OWN","WORK DONE IN SILENCE","AN ILLNESS WITH A WARD","A WORD THAT CAN INSULT"],"branches":[{"senses":"S1 · S3","en":"THE INNER LIFE: the oldest sense marks the mind, and once also the soul, as a region distinct from the body.","cn":"内在生活：最老的义项标记心智——也曾标记灵魂——作为区别于身体的一个区域。"},{"senses":"S2","en":"HEALTH: mental health gives the inner life a condition that can be cared for.","cn":"健康：mental health 给内在生活一个可以被照护的状态。"},{"senses":"S4 · S5","en":"EFFORT: thought becomes labour, and labour can be done with no visible trace.","cn":"劳动：思考变成劳作，而这种劳作可以不留可见痕迹。"},{"senses":"S6 · S8","en":"ILLNESS: the clinical label builds hospitals and patients, and then turns into a playground insult.","cn":"疾病：临床标签建起了医院与病人，随后又变成操场上的骂人话。"},{"senses":"S7 · S9","en":"JUDGEMENT: slang decides who is crazy; law decides who can understand and be responsible.","cn":"判断：俚语义断定谁疯了；法律则断定谁能理解、谁能负责。"}]},"affixes":{"intro":{"en":"Mental is Latin ment- 'mind' plus the adjective ending -al. The suffix is productive in English; the stem ment- is not a free word, but it recurs in mentality, dementia and mentalize.","cn":"mental 是拉丁语 ment-“心智”加形容词词尾 -al。这个后缀在英语里能产；词干 ment- 不能单独成词，却在 mentality、dementia、mentalize 中反复出现。"},"latinIntro":{"en":"Late Latin mentalis was built on Latin mens (genitive mentis) 'mind', from PIE *men- 'to think'. The same root supplies dementia (de- 'away' + mens) and the native English mind.","cn":"晚期拉丁语 mentalis 建立在拉丁语 mens（属格 mentis）“心智”之上，源自原始印欧语 *men-“思考”。同一词根也给出 dementia（de-“离开”+ mens）以及英语本族词 mind。"},"items":[{"word":"mental","structure":"ment- (mind) + -al (adjective)","meaning":"of or relating to the mind","meaningCN":"心理的；心智的（ment- 心智 + -al 形容词词尾）","example":"The test measures mental rather than manual speed.","exampleCN":"这项测试测的是思维速度，而不是手的速度。"},{"word":"mentality","structure":"mental + -ity (noun of state)","meaning":"a way of thinking; mental character","meaningCN":"心态；思维方式（-ity 构成状态名词）","example":"The team's mentality changed after the first win.","exampleCN":"首胜之后，球队的心态变了。"},{"word":"mentally","structure":"mental + -ly (adverb)","meaning":"in the mind; with respect to the mind","meaningCN":"心理上；在脑中（-ly 构成副词）","example":"She counted the steps mentally before jumping.","exampleCN":"起跳前她在心里数了步子。"},{"word":"mentalist","structure":"mental + -ist (person)","meaning":"a mind-reading performer; a believer in mentalism","meaningCN":"读心术表演者；心灵主义者（-ist 指人）","example":"The mentalist guessed the card without touching it.","exampleCN":"那位读心术表演者没碰牌就猜中了。"},{"word":"mentalism","structure":"mental + -ism (doctrine)","meaning":"the view that mind or consciousness is fundamental","meaningCN":"心灵主义；唯心论（-ism 表学说）","example":"Mentalism treats consciousness as the basic stuff of reality.","exampleCN":"心灵主义把意识当作现实的基本材料。"},{"word":"mentalistic","structure":"mentalist + -ic (adjective)","meaning":"relating to mentalism or to explanations in mental terms","meaningCN":"心灵主义的；用心理术语解释的（-ic 构成形容词）","example":"Behaviourists rejected mentalistic explanations.","exampleCN":"行为主义者拒斥用心理术语所作的解释。"},{"word":"mentalize","structure":"mental + -ize (verb)","meaning":"to understand behaviour as arising from mental states","meaningCN":"心智化；把行为理解为心理状态的产物（-ize 构成动词）","example":"Children learn to mentalize through play.","exampleCN":"儿童在游戏中学着理解他人的心理。"},{"word":"dementia","structure":"de- (away) + ment- (mind) + -ia (condition)","meaning":"a condition in which the mind has gone away","meaningCN":"痴呆；认知功能衰退（de- 离开 + ment- 心智 + -ia 状态）","example":"The early signs of dementia were mistaken for tiredness.","exampleCN":"痴呆的早期迹象被误认为是疲劳。"},{"word":"demented","structure":"de- (away) + ment- (mind) + -ed","meaning":"out of one's mind; wildly foolish","meaningCN":"精神错乱的；荒唐的（-ed 构成形容词）","example":"The plan was demented from the first page.","exampleCN":"这个计划从第一页起就荒唐透顶。"},{"word":"memento","structure":"Latin memento 'remember', imperative of meminisse","meaning":"an object kept as a reminder","meaningCN":"纪念物；使人想起某事的物件（源自拉丁语祈使式“记得”）","example":"He kept the ticket as a memento of the trip.","exampleCN":"他把那张票留着，作为那次旅行的纪念。"}],"latinEntries":[{"word":"mens","structure":"PIE *men- 'to think'","meaning":"mind, intellect, thought, intention","meaningCN":"心智、智力、思想、意图"},{"word":"mentalis","structure":"ment- + -alis (adjective)","meaning":"of the mind","meaningCN":"心智的"},{"word":"demens","structure":"de- (away) + mens (mind)","meaning":"out of one's mind, insane","meaningCN":"失去理智的；精神错乱的"}]}},{"word":"method","ipa_uk":"/ˈmeθəd/","ipa_us":"/ˈmeθəd/","definition_zh":"方法；办法；条理；体系；（学科或艺术的）方法论体系","definition_en":"a particular way of doing something, especially one that is planned and systematic, or the order and system that such a way produces","core_image":"一条被反复踩出的小路：草被踩平了，路指向远处的目标","scene":"The lab still uses a method that has not changed in forty years.","sceneCN":"这里 method 是「方法」（第 1 个义项：做某事的特定程序）；句意：这个实验室仍在使用一套四十年没变过的方法。场景要点：一排贴着编号的旧仪器、墙上手写的步骤表、被踩得发亮的地面。","pos":[{"tag":"n.","zh":"方法；办法；条理；体系"}],"collocations":[{"phrase":"scientific method","zh":"科学方法"},{"phrase":"a method of doing something","zh":"做某事的方法"},{"phrase":"teaching method","zh":"教学法"},{"phrase":"method acting","zh":"方法派表演"},{"phrase":"there is method in one's madness","zh":"看似疯狂，实有章法"},{"phrase":"by this method","zh":"用这种方法"},{"phrase":"a reliable method","zh":"可靠的方法"}],"forms":[{"label":"名词复数","form":"methods"}],"derivatives":[{"word":"methodical","pos":"adj.","zh":"有条理的；按部就班的"},{"word":"methodically","pos":"adv.","zh":"有条理地；系统地"},{"word":"methodology","pos":"n.","zh":"方法论；一套研究方法"},{"word":"methodological","pos":"adj.","zh":"方法论的；方法上的"},{"word":"methodologist","pos":"n.","zh":"方法论学者"},{"word":"methodize","pos":"v.","zh":"使有条理；使系统化"}],"senses":[{"no":"01","title":"A way of doing something","titleCN":"方法：做某事的特定路数","definition":"a particular procedure for doing something, especially a planned and systematic one","definitionCN":"做某事的特定程序，尤指有计划、有系统的程序","example":"The lab still uses a method that has not changed in forty years.","exampleCN":"这个实验室仍在使用一套四十年没变过的方法。","why":"Method reached English in the early 15th century from Greek methodos, originally 'pursuit, a following after'. A method is a path that has already been walked and can be walked again.","whyCN":"method 于 15 世纪初从希腊语 methodos 进入英语，原义为“追寻、跟随其后”。方法就是一条已经被人走过、还可以再走一遍的路。"},{"no":"02","title":"Orderliness","titleCN":"条理：做事有章法","definition":"the quality of acting in an orderly, systematic way rather than at random","definitionCN":"做事有条理、有系统，而非随意的品质","example":"There was method in the way she sorted the files, though no one else could see it.","exampleCN":"她整理文件的方式自有章法，只是别人看不出来。","why":"From the 1610s the word also named 'orderliness, regularity'. The path is no longer a particular route but the habit of always walking on one.","whyCN":"自 17 世纪 10 年代起，这个词也指“有条理、有规律”。此时路不再是一条具体路线，而是“总要沿着某条路走”的习惯。"},{"no":"03","title":"A complete system","titleCN":"体系：成套的规则","definition":"a complete set of rules or procedures for attaining an end","definitionCN":"为达到某一目的而设的一整套规则或程序","example":"The school adopted a new method for teaching reading.","exampleCN":"学校采用了一套新的阅读教学体系。","why":"The sense 'a system or complete set of rules' is recorded from the 1680s. Once a path is written down as rules, it can be taught to strangers.","whyCN":"“体系或完整规则集”这一义项自 17 世纪 80 年代有记录。一旦一条路被写成规则，它就能教给陌生人。"},{"no":"04","title":"Scientific method","titleCN":"科学方法：学科自己的路","definition":"the established procedure of a discipline for testing claims and producing knowledge","definitionCN":"某一学科为检验主张、生产知识而确立的程序","example":"The scientific method is less a single recipe than a set of habits of doubt.","exampleCN":"科学方法与其说是一份单一配方，不如说是一组怀疑的习惯。","why":"Greek methodos already meant 'scientific inquiry, method of inquiry'. Science did not invent the word; it inherited the oldest sense.","whyCN":"希腊语 methodos 本就意为“科学探究、探究的方法”。科学没有发明这个词，它继承的是最古老的义项。"},{"no":"05","title":"Teaching and acting methods","titleCN":"教学法与表演体系：一门手艺的路","definition":"a named system of practice in teaching or in the arts, such as the direct method or method acting","definitionCN":"教学或艺术中以人名或特征命名的实践体系，如直接教学法、方法派表演","example":"Method acting asks the performer to draw on real memories.","exampleCN":"方法派表演要求演员调动真实的记忆。","why":"A system with a name becomes a school. Method here is a path that a whole profession agrees to walk together.","whyCN":"一套有名字的体系会变成一派。这里的 method 是一整门行业同意一起走的那条路。"},{"no":"06","title":"Old medical sense","titleCN":"医学旧义：系统化的治疗方案","definition":"in early use, the regular, systematic treatment of disease","definitionCN":"在早期用法中，指对疾病的规律化、系统化治疗","example":"The medieval physician spoke of a method for fevers, not a single remedy.","exampleCN":"中世纪的医生讲的是治疗热病的一套方法，而不是某一味药。","why":"The first English sense, in the early 15th century, was 'regular, systematic treatment of disease'. The word entered through medicine before it belonged to everything else.","whyCN":"英语中的第一个义项是 15 世纪初的“对疾病的规律化、系统化治疗”。这个词先通过医学进来，然后才属于一切别的事物。"},{"no":"07","title":"Method in programming","titleCN":"编程中的方法：对象身上的函数","definition":"in object-oriented programming, a function or procedure attached to an object or class","definitionCN":"在面向对象编程中，附着于对象或类上的函数或过程","example":"The method returns a new list instead of changing the old one.","exampleCN":"这个方法返回一个新列表，而不修改旧列表。","why":"The metaphor survives in code: a method is still a fixed route the object knows how to take when it is called.","whyCN":"这个比喻在代码里活了下来：方法仍是对象被调用时知道该怎么走的一条固定路线。"},{"no":"08","title":"A method of inquiry","titleCN":"探究之路：哲学意义上的方法","definition":"in philosophy, the deliberate path of doubt or reasoning by which a conclusion is reached","definitionCN":"在哲学中，为抵达结论而有意采取的怀疑或推理之路","example":"Descartes began with a method of doubt that would leave only certainty standing.","exampleCN":"笛卡尔从一种怀疑的方法开始，只为留下确定的东西。","why":"Methodos was literally a following after something. Philosophy turns that pursuit into a rule for how to pursue anything at all.","whyCN":"methodos 字面上就是“跟在某物之后追”。哲学把这趟追寻变成一条规则，规定该怎样追寻任何东西。"},{"no":"09","title":"Method in one's madness","titleCN":"习语：疯狂里藏着章法","definition":"in the phrase 'there is method in one's madness', used when apparently foolish behaviour turns out to have a purpose","definitionCN":"在短语 there is method in one's madness 中，指看似荒唐的行为其实自有目的","example":"He shuffles the cards for ten minutes, but there is method in his madness.","exampleCN":"他把牌洗了十分钟，看似荒唐，其实自有章法。","why":"Shakespeare's phrase 'though this be madness, yet there is method in it' (Hamlet) gave English a fixed way to say that a path is hidden inside chaos.","whyCN":"莎士比亚的句子“though this be madness, yet there is method in it”（《哈姆雷特》）给了英语一个固定说法：混乱里藏着一条路。"}],"etymology":{"intro":{"en":"Method is Greek: meta 'in pursuit of' plus hodos 'road, way'. Latin borrowed it as methodus and passed it to French and English. It has no connection with medical, despite the shared -met- shape. Dates are approximate.","cn":"method 是希腊词：meta“追寻”加 hodos“路、道”。拉丁语把它借作 methodus，再传给法语和英语。尽管有共同的 -met- 外形，它与 medical 毫无关系。年代为大致估计。"},"items":[{"era":"EARLY 15C","en":"First recorded in English as 'regular, systematic treatment of disease', through Latin methodus 'way of teaching or going' and Greek methodos.","cn":"英语中最早记录于 15 世纪初，意为“对疾病的规律化、系统化治疗”，经拉丁语 methodus“教学或行走之道”与希腊语 methodos 而来。"},{"era":"GREEK methodos","en":"Greek methodos meant 'scientific inquiry, method of inquiry, investigation', and originally 'pursuit, a following after'.","cn":"希腊语 methodos 意为“科学探究、探究的方法、调查”，原义为“追寻、跟随其后”。"},{"era":"GREEK meta + hodos","en":"The word joins meta 'in pursuit or quest of' and hodos 'a way, path, track, road', also 'a journey'. Hodos is of uncertain origin; Beekes suggests PIE *sod- 'course', and it is traditionally linked to Slavic words for 'course'.","cn":"这个词由 meta“追寻、求索”与 hodos“路、路径、轨道、道路”（也指“旅程”）组合而成。hodos 的来源不确定；Beekes 提出原始印欧语 *sod-“行程”，传统上也把它与斯拉夫语表示“行程”的词联系起来。"},{"era":"1580s / 1610s / 1680s","en":"The sense widened to 'any way of doing anything' in the 1580s, to 'orderliness, regularity' in the 1610s, and to 'a system or complete set of rules' in the 1680s.","cn":"词义在 16 世纪 80 年代扩展到“做任何事的方式”，17 世纪 10 年代扩展到“有条理、有规律”，17 世纪 80 年代扩展到“体系或完整的一套规则”。"},{"era":"1923","en":"The phrase method acting is recorded in reference to the theory associated with the Russian director Konstantin Stanislavski.","cn":"method acting 这一说法有记录，指与俄国导演康斯坦丁·斯坦尼斯拉夫斯基相关的理论。"},{"era":"NOT MEDICAL","en":"Medical goes back to Latin medicus 'physician', with no Greek element. Meta- in method is the Greek preposition 'in pursuit of', not the modern prefix meaning 'beyond' or 'after'; the two words only share letters.","cn":"medical 追溯到拉丁语 medicus“医生”，不含希腊语成分。method 里的 meta- 是希腊语介词“追寻”，不是现代表示“超越、之后”的前缀；两个词只共享字母。"}]},"similar":{"note":{"en":"The first group is the word family built on method: the adjective, the adverb and the study of method. The second group compares the nouns English uses for 'a way of doing something', which differ in scale and in who owns the way.","cn":"第一组是建立在 method 上的词族：形容词、副词与研究方法的学问。第二组比较英语里表示“做某事的方式”的几个名词，区别在于尺度大小与“这条路归谁”。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"methodology","ipa":"/ˌmeθəˈdɒlədʒi/","tag":"the study of methods","definition":"the branch of knowledge that studies methods, or the set of methods used in a field. It is not a longer synonym of method: a methodology can contain several methods.","definitionCN":"研究方法的学问分支，或某一领域所使用的一套方法。它不是 method 的加长同义词：一套方法论里可以包含好几种方法。"},{"word":"methodical","ipa":"/məˈθɒdɪkl/","tag":"adjective of manner","definition":"done according to a method; orderly and systematic. It describes a person or a procedure, not a route.","definitionCN":"按方法进行的；有条理、有系统的。它描述人或程序，而不描述一条路线。"},{"word":"methodically","ipa":"/məˈθɒdɪkli/","tag":"adverb","definition":"in an orderly, step-by-step way. It answers 'how', while method answers 'by what route'.","definitionCN":"有条理地、一步一步地。它回答“怎样做”，而 method 回答“走哪条路”。"},{"word":"methodize","ipa":"/ˈmeθədaɪz/","tag":"verb, rare","definition":"to reduce something to order or system. The verb turns the noun into an action; it is rare outside formal writing.","definitionCN":"把某物整理成秩序或体系。这个动词把名词变成动作；在正式写作之外很少见。"}]},{"heading":"NEAR MEANING","entries":[{"word":"approach","ipa":"/əˈprəʊtʃ/","tag":"a way of tackling","definition":"a way of dealing with a problem or subject, often including the attitude behind it. It is broader and softer than method, which implies explicit steps.","definitionCN":"处理问题或课题的方式，常包含背后的态度。它比 method 更宽、更软，而 method 暗示明确的步骤。"},{"word":"technique","ipa":"/tekˈniːk/","tag":"skill in a single act","definition":"a particular way of carrying out a single task, especially one requiring skill. Techniques are the small parts inside a method.","definitionCN":"完成单项任务的具体方式，尤指需要技巧的那种。technique 是 method 内部的一个个小零件。"},{"word":"means","ipa":"/miːnz/","tag":"instrument, not procedure","definition":"a thing or resource used to achieve an end. Means answers 'with what'; method answers 'in what order'.","definitionCN":"为达到目的而使用的东西或资源。means 回答“用什么”，method 回答“按什么顺序”。"},{"word":"procedure","ipa":"/prəˈsiːdʒə/","tag":"official sequence","definition":"an established or official sequence of steps. It is more bureaucratic than method and often written down by an authority.","definitionCN":"既定的或官方的步骤顺序。它比 method 更带行政色彩，常由某个权威写下来。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Greek meta 'in pursuit of' plus hodos 'road', the Latin borrowing methodus, and the family methodical, methodology, methodize.","cn":"只用真实成分与真实同族词：希腊语 meta“追寻”加 hodos“路”、拉丁语借词 methodus，以及 methodical、methodology、methodize 词族。"},"normal":[{"en":"hodos means 'road'. A method is literally 'a following after on a road': meta plus hodos.","cn":"hodos 意为“路”。method 字面上就是“沿路跟随”：meta 加 hodos。"},{"en":"In method, meta- does not mean 'beyond' or 'after' as it does in modern English; it means 'in pursuit of'. The Greek preposition is about chasing, not about position.","cn":"在 method 里，meta- 不像现代英语那样表示“超越”或“之后”，而是“追寻”。这个希腊语介词讲的是追赶，不是位置。"},{"en":"Methodology is not a fancy word for method: it is the study of methods, or the whole set of them used in a field.","cn":"methodology 不是 method 的高级说法：它是对方法的研究，或某一领域所使用的整套方法。"},{"en":"Methodical describes the person who always walks on a path; method names the path itself.","cn":"methodical 描述那个总沿着路走的人；method 命名的是那条路本身。"},{"en":"Medical looks similar but is Latin medicus 'physician'. One word has a road in it, the other has a doctor.","cn":"medical 看着像，其实是拉丁语 medicus“医生”。一个词里装着一条路，另一个词里装着一位医生。"}],"abstract":[{"en":"Picture grass in a field. One path is visible because many feet chose the same line; that line is a method.","cn":"想象一片草地。有一条路看得见，是因为许多脚选择了同一条线；那条线就是 method。"},{"en":"A path can be walked by one person or written down for a school. The moment it is written down, method becomes methodology.","cn":"一条路可以由一个人走，也可以写下来给一个学派。写下来的那一刻，method 就变成了 methodology。"},{"en":"Method is the order of steps, not the tool in your hand. A hammer is a means; how you swing it is a technique; the sequence is the method.","cn":"method 是步骤的顺序，不是你手里的工具。锤子是 means；怎么挥是 technique；先后次序才是 method。"}]},"examples":[{"en":"No method will save a study that was badly designed in the first place.","cn":"如果一项研究一开始就设计得很糟，任何方法都救不了它。"},{"en":"She works without method, yet somehow finishes before everyone else.","cn":"她做事毫无章法，却总能比别人先做完。"},{"en":"The two laboratories use different methods and keep getting different numbers.","cn":"两个实验室用不同的方法，得到的数字也一直不同。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“卖瑟德”——卖瑟德把一条踩出来的小路画在纸上，卖给后来的人照着走 → method 方法、办法（只借音，不表词源）","word":"method"},"root":"源自希腊语 methodos“追寻、探究”，由 meta“追寻”加 hodos“路”构成，核心是“沿着一条路追到目标”。","sensesIntro":{"en":"Nine senses of method, all from one image: a line worn into the grass by feet that wanted the same destination. It can be one path, the habit of taking paths, or the written map of them.","cn":"method 的九个义项都来自同一幅画面：一条被想抵达同一目标的脚踩出来的草径。它可以是某一条路、走路的习惯，或被写下来的路线图。"},"semanticMap":{"core":{"en":"CORE IMAGE: a path worn into grass, pointing at a destination.","cn":"核心意象：一条被踩进草地的小路，指向某个目的地。"},"chain":["A GOAL AHEAD","FEET CHOOSE A LINE","THE LINE IS A PATH","THE PATH REPEATS","THE PATH IS WRITTEN DOWN","A SCHOOL WALKS IT"],"branches":[{"senses":"S1 · S6","en":"THE PATH: the oldest senses name a procedure, first for curing disease, then for anything at all.","cn":"路：最老的义项命名一套程序，先用于治病，后用于任何事。"},{"senses":"S2 · S9","en":"THE HABIT: orderliness is walking on a path by choice, and the idiom says a path may hide inside apparent chaos.","cn":"习惯：条理是有意识地沿路走；那条习语则说，混乱里也可能藏着一条路。"},{"senses":"S3 · S4","en":"THE SYSTEM: written rules turn a path into a teachable system, and science inherits the oldest 'inquiry' sense.","cn":"体系：写下来的规则把路变成可教的体系，而科学继承的是最古老的“探究”义。"},{"senses":"S5 · S8","en":"THE SCHOOL: teaching and acting give the path a proper name, and philosophy makes the pursuit itself a rule.","cn":"学派：教学与表演给这条路一个专名，哲学则把追寻本身变成规则。"},{"senses":"S7","en":"THE CODE: in software the object still knows a fixed route to take when called.","cn":"代码：在软件里，对象被调用时仍知道该走哪条固定路线。"}]},"affixes":{"intro":{"en":"Method is a Greek compound borrowed whole: meta- plus hodos 'road'. English adds -ical, -ically, -ology, -ologist and -ize, while the same hodos builds episode, period and Exodus.","cn":"method 是整体借入的希腊语复合词：meta- 加 hodos“路”。英语加上 -ical、-ically、-ology、-ologist、-ize，而同一个 hodos 还构成 episode、period、Exodus。"},"latinIntro":{"en":"Latin took the Greek word unchanged as methodus 'way of teaching or going', and Late Latin methodicus came from Greek methodikos. Latin had its own word for 'way', modus, but method did not come from it.","cn":"拉丁语原样吸收希腊词作 methodus“教学或行走之道”，晚期拉丁语 methodicus 来自希腊语 methodikos。拉丁语自己表示“方式”的词是 modus，但 method 并非来自它。"},"items":[{"word":"method","structure":"meta- (in pursuit of) + hodos (road)","meaning":"a following after on a road; a way of doing something","meaningCN":"沿路追寻；做某事的方法（meta- 追寻 + hodos 路）","example":"They tried every method and failed with each.","exampleCN":"他们试了每一种方法，每一种都失败了。"},{"word":"methodical","structure":"method + -ical (adjective)","meaning":"done according to method; orderly","meaningCN":"按方法进行的；有条理的（-ical 构成形容词）","example":"His methodical notes filled four notebooks.","exampleCN":"他条理分明的笔记写满了四个本子。"},{"word":"methodically","structure":"methodical + -ly (adverb)","meaning":"in an orderly, step-by-step manner","meaningCN":"有条理地；一步一步地（-ly 构成副词）","example":"She checked each drawer methodically.","exampleCN":"她逐个抽屉有条理地检查。"},{"word":"methodology","structure":"method + -ology (study of)","meaning":"the study of methods; a set of methods used in a field","meaningCN":"方法论；一套研究方法（-ology 表学问）","example":"The paper was rejected for its weak methodology.","exampleCN":"这篇论文因方法论薄弱而被拒。"},{"word":"methodological","structure":"methodology + -ical (adjective)","meaning":"relating to methodology","meaningCN":"方法论的；方法上的","example":"The two studies differ on methodological grounds.","exampleCN":"这两项研究在方法上存在分歧。"},{"word":"methodologist","structure":"methodology + -ist (person)","meaning":"a specialist in methods of research","meaningCN":"方法论学者（-ist 指人）","example":"A methodologist was added to the review panel.","exampleCN":"评审组里增加了一位方法论专家。"},{"word":"methodize","structure":"method + -ize (verb)","meaning":"to arrange according to a system","meaningCN":"使有条理；使系统化（-ize 构成动词）","example":"He methodized the archive over one winter.","exampleCN":"他用一个冬天把档案整理成体系。"},{"word":"Methodist","structure":"method + -ist (adherent)","meaning":"a member of the Protestant denomination founded at Oxford in 1729","meaningCN":"卫理公会教徒（-ist 表追随者，源于其讲究方法的修行方式）","example":"The Methodist chapel still stands on the corner.","exampleCN":"卫理公会礼拜堂仍立在街角。"},{"word":"episode","structure":"epi- (besides) + eisodos (a coming in, from hodos 'way')","meaning":"an incident or instalment inserted into a larger whole","meaningCN":"插曲；（系列中的）一集（epi- 另外 + eisodos 进入，含 hodos 路）","example":"The final episode answers nothing.","exampleCN":"最后一集什么也没解答。"},{"word":"period","structure":"peri- (around) + hodos (way)","meaning":"a going round; a length of time","meaningCN":"周期；一段时间（peri- 环绕 + hodos 路，即“绕一圈”）","example":"The period lasted almost a century.","exampleCN":"这一时期持续了将近一个世纪。"},{"word":"Exodus","structure":"ex- (out) + hodos (way)","meaning":"a going out; a mass departure","meaningCN":"出走；大批离去（ex- 向外 + hodos 路）","example":"The drought set off an exodus from the villages.","exampleCN":"旱灾引发了村庄的大批出走。"},{"word":"method acting","structure":"method (system) + acting","meaning":"a performance technique that draws on the actor's own experience","meaningCN":"方法派表演（以体系命名的表演技术）","example":"Method acting changed how American films were shot.","exampleCN":"方法派表演改变了美国电影的拍摄方式。"}],"latinEntries":[{"word":"methodus","structure":"Greek methodos, meta + hodos","meaning":"way of teaching or going","meaningCN":"教学或行走之道"},{"word":"methodicus","structure":"Greek methodikos + Latin -icus","meaning":"of method; systematic","meaningCN":"方法的；系统的"}]}},{"word":"migrate","ipa_uk":"/ˈmaɪɡreɪt/","ipa_us":"/ˈmaɪɡreɪt/","definition_zh":"迁移；迁徙；移居；（数据、系统）迁移；（细胞）移动","definition_en":"to move from one place, habitat or system to another, especially over a distance and often for a season or a new life","core_image":"一群身影越过旧地平线，走向另一条尚未抵达的地平线","scene":"Every October the birds migrate south along the coast.","sceneCN":"这里 migrate 是「迁徙」（第 1 个义项：动物随季节从一处栖息地移到另一处）；句意：每年十月，鸟群沿着海岸向南迁徙。场景要点：一条海岸线、排成人字的鸟群、地平线上尚未到达的南方。","pos":[{"tag":"vi.","zh":"迁移；迁徙；移居（常与 from、to 连用）"},{"tag":"vt.","zh":"（信息技术）迁移（数据、系统、账户）"}],"collocations":[{"phrase":"migrate south","zh":"向南迁徙"},{"phrase":"migrate to a new country","zh":"移居到新的国家"},{"phrase":"migrate from A to B","zh":"从甲地迁移到乙地"},{"phrase":"migrate between two places","zh":"在两个地方之间来回迁移"},{"phrase":"seasonal migration","zh":"季节性迁徙"},{"phrase":"migrate data","zh":"迁移数据"},{"phrase":"economic migrants","zh":"经济移民"}],"forms":[{"label":"三单（he/she/it）","form":"migrates"},{"label":"过去式（已经发生）","form":"migrated"},{"label":"过去分词（完成／被动）","form":"migrated"},{"label":"现在分词（进行体）","form":"migrating"}],"derivatives":[{"word":"migration","pos":"n.","zh":"迁移；迁徙；移居"},{"word":"migrant","pos":"n./adj.","zh":"移民；候鸟；迁徙的"},{"word":"migratory","pos":"adj.","zh":"迁徙的；有迁徙习性的"},{"word":"emigrate","pos":"v.","zh":"移出；迁离本国"},{"word":"immigrate","pos":"v.","zh":"移入；迁入某国定居"},{"word":"transmigration","pos":"n.","zh":"转世；跨地域迁移"}],"senses":[{"no":"01","title":"Animals on the move","titleCN":"动物迁徙：随季节换一片栖息地","definition":"of animals, to move from one habitat or region to another at a distance, usually with the seasons","definitionCN":"指动物远距离地从一处栖息地或地区移到另一处，通常随季节而行","example":"Every October the birds migrate south along the coast.","exampleCN":"每年十月，鸟群沿着海岸向南迁徙。","why":"The animal sense is recorded from 1753. Latin migrare already meant 'to move from one place to another', and birds made the word's clearest picture.","whyCN":"动物义项自 1753 年有记录。拉丁语 migrare 本就意为“从一处移到另一处”，而鸟群给这个词提供了最清晰的画面。"},{"no":"02","title":"People settle elsewhere","titleCN":"移居：人到另一地安家","definition":"of people, to move from one place of residence to another at a distance, especially to another country","definitionCN":"指人远距离地从一处居住地迁到另一处，尤指迁往另一个国家","example":"Her grandparents migrated to the coast in the 1950s.","exampleCN":"她的祖父母在 20 世纪 50 年代移居到了海边。","why":"The sense for persons is recorded by 1770. The same movement now carries a household, a language and a future, not only a body.","whyCN":"指人的义项在 1770 年已有记录。同一种移动现在承载的是一个家庭、一门语言和一种未来，而不只是一具身体。"},{"no":"03","title":"Move from place to place","titleCN":"一般移动：只说到从一处到另一处","definition":"to pass from one place or position to another, without stressing either departure or arrival","definitionCN":"从一处或一个位置移到另一处，既不强调离开，也不强调抵达","example":"The infection migrated from the skin to the joint.","exampleCN":"感染从皮肤转移到了关节。","why":"This is the word's first English sense, recorded in the 1690s: 'to pass from one place to another'. It is the plain trunk from which the other senses branch.","whyCN":"这是这个词在英语里的第一个义项，1690 年代有记录：“从一处移到另一处”。它是其他义项分叉出来的那根主干。"},{"no":"04","title":"Data and systems","titleCN":"数据与系统迁移：换一个平台继续运行","definition":"in computing, to move data, programs or services from one system or platform to another","definitionCN":"在计算机领域，把数据、程序或服务从一个系统或平台移到另一个","example":"The company will migrate its accounts to the new platform in June.","exampleCN":"公司将在六月把账户迁移到新平台。","why":"The old picture fits exactly: something alive in one place is picked up and set down in another, and must keep working after the move.","whyCN":"旧画面严丝合缝：在一个地方运行着的东西被拿起、放到另一个地方，而且搬完之后还得继续运行。"},{"no":"05","title":"Cells and substances","titleCN":"细胞迁移：在体内移动","definition":"in biology and medicine, of cells or substances, to move within the body or from one tissue to another","definitionCN":"在生物学与医学中，指细胞或物质在体内移动，或从一种组织移到另一种","example":"These cells migrate to the wound and begin repairing it.","exampleCN":"这些细胞迁移到伤口处并开始修复。","why":"The distance shrinks to millimetres, but the verb keeps its shape: a body leaves one site and arrives at another.","whyCN":"距离缩短到毫米级，但动词的形状没变：一个个体离开一处，抵达另一处。"},{"no":"06","title":"Labour on the move","titleCN":"劳动力流动：为生计迁往别处","definition":"of workers or populations, to move from one region to another in search of work or better conditions","definitionCN":"指工人或人群为寻找工作或更好的条件而从一地区迁往另一地区","example":"Whole villages migrated to the cities when the factories opened.","exampleCN":"工厂开工后，整村整村的人迁往城市。","why":"When migration is driven by wages, the word stops describing nature and starts describing economics.","whyCN":"当迁徙由工资驱动时，这个词就不再描述自然，而开始描述经济。"},{"no":"07","title":"Switch to a new way","titleCN":"比喻：转向新的做法或平台","definition":"figuratively, to change from one practice, model or system to another","definitionCN":"比喻用法：从一种做法、模式或制度转到另一种","example":"Many readers have migrated from print to podcasts.","exampleCN":"许多读者已经从纸媒转向播客。","why":"The journey no longer has geography, only a before and an after. The verb survives because the feeling of relocation survives.","whyCN":"这趟旅程不再有地理，只剩下“之前”与“之后”。动词之所以还活着，是因为那种搬迁的感觉还活着。"},{"no":"08","title":"Round trip","titleCN":"循环迁徙：去了还会回来","definition":"to move regularly between two places, as migratory birds or pastoral families do","definitionCN":"像候鸟或游牧家庭那样，在两处之间规律地往返","example":"The herders migrate between the lowlands in winter and the high pastures in summer.","exampleCN":"牧民冬天迁到低地，夏天迁往高山牧场。","why":"Not every migration is one-way. The word covers the round trip as easily as the exodus, because it names the moving, not the staying.","whyCN":"并非所有迁徙都是单向的。这个词既能指一去不返的大迁徙，也能指往返循环，因为它命名的是“移动”，而不是“留下”。"},{"no":"09","title":"Direction left open","titleCN":"用法分界：不指明移出还是移入","definition":"used without specifying whether one is leaving a place or arriving at one, unlike emigrate and immigrate","definitionCN":"使用时不明说自己是离开某地还是抵达某地，这与 emigrate 和 immigrate 不同","example":"The report says people migrate for work, without asking which border they cross.","exampleCN":"报告说人们为工作而迁移，并不追问他们越过的是哪一道边界。","why":"The Century Dictionary put it plainly in 1897: migrate stresses the change itself, not the place of departure or of stopping. Emigrate looks back, immigrate looks forward.","whyCN":"《世纪词典》1897 年说得很清楚：migrate 强调变化本身，而不强调出发地或落脚地。emigrate 回头看，immigrate 向前看。"}],"etymology":{"intro":{"en":"Migrate comes from Latin migrare 'to move from one place to another', probably from PIE *(e)meigw- 'to change'. Its English life began with the plain sense 'pass from one place to another' and later specialised into animals, people and machines. Dates are approximate.","cn":"migrate 来自拉丁语 migrare“从一处移到另一处”，可能源自原始印欧语 *(e)meigw-“改变”。它在英语里先有“从一处到另一处”的平实义，后来才分化出动物、人与机器诸义。年代为大致估计。"},"items":[{"era":"1690s","en":"First recorded in English as 'to pass from one place to another', from Latin migratus, past participle of migrare 'to move from one place to another'.","cn":"英语中最早记录于 17 世纪 90 年代，意为“从一处移到另一处”，来自拉丁语 migratus，即 migrare“从一处移到另一处”的过去分词。"},{"era":"LATIN migrare","en":"Latin migrare is probably originally *migwros, from PIE *(e)meigw- 'to change', an extended form of the root *mei- (1) 'to change, go, move'.","cn":"拉丁语 migrare 最初大概是 *migwros，来自原始印欧语 *(e)meigw-“改变”，而这是词根 *mei-（第一支）“改变、走、移动”的扩展形式。"},{"era":"1753","en":"Of animals, 'to remove from one habitat to another at a distance' is recorded. The word's most familiar picture, a flock crossing a season, is fixed here.","cn":"记录到指动物的“远距离地从一处栖息地移到另一处”。这个词最熟悉的画面——一群鸟越过一个季节——在这里固定下来。"},{"era":"1770","en":"Of persons, 'to pass or remove from one place of residence to another at a distance' is recorded, especially from one country to another.","cn":"记录到指人的“远距离地从一处居住地迁到另一处”，尤指从一个国家到另一个国家。"},{"era":"1897","en":"The Century Dictionary draws the line still taught today: migrate stresses the change, not the departure or the stopping place; emigrate views the person leaving, immigrate views the person arriving.","cn":"《世纪词典》划出了今天仍在教的界线：migrate 强调变化，而不强调出发地或落脚地；emigrate 着眼于离开的人，immigrate 着眼于抵达的人。"},{"era":"MODERN ENGLISH","en":"The computing sense, to move data or services to another system, extends the old picture into machines. The family keeps its bearings: migration (1610s), migrant (1760), emigrate (1778), immigrate (1620s).","cn":"计算机义“把数据或服务迁到另一系统”把旧画面延伸到机器上。这个词族的方向感仍在：migration（17 世纪 10 年代）、migrant（1760）、emigrate（1778）、immigrate（17 世纪 20 年代）。"}]},"similar":{"note":{"en":"The first group is the family built on migrate: the process, the person or animal, and the adjective. The second group separates the words that name a move with a direction, which migrate deliberately leaves out.","cn":"第一组是建立在 migrate 上的词族：过程、人（或动物）、形容词。第二组区分那些带方向的“迁移”词，而 migrate 恰恰有意不指明方向。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"migration","ipa":"/ˌmaɪˈɡreɪʃn/","tag":"the process","definition":"the act or process of migrating, or a group of people or animals doing it. It is the noun of the event, not a synonym of the verb.","definitionCN":"迁移的行为或过程，或正在迁移的一群人或动物。它是这一事件的名词，不是动词的同义词。"},{"word":"migrant","ipa":"/ˈmaɪɡrənt/","tag":"the person or animal","definition":"a person or animal that migrates, or an adjective meaning 'migratory'. It names the mover, while migrate names the moving.","definitionCN":"迁移的人或动物，也可作形容词表示“迁徙的”。它命名的是移动者，而 migrate 命名的是移动本身。"},{"word":"migratory","ipa":"/ˈmaɪɡrətəri/","tag":"adjective of habit","definition":"having the habit of migrating, as a species or a way of life. It describes the pattern, not a single journey.","definitionCN":"有迁徙习性的，如某个物种或某种生活方式。它描述的是模式，而不是某一趟旅程。"},{"word":"migrational","ipa":"/ˌmaɪɡreɪʃnəl/","tag":"rare adjective","definition":"relating to migration. It is rare and mostly replaced by migratory, but it keeps the noun's abstract frame.","definitionCN":"与迁移有关的。它很少用，多半被 migratory 取代，但仍保留名词的抽象框架。"}]},{"heading":"NEAR MEANING","entries":[{"word":"emigrate","ipa":"/ˈemɪɡreɪt/","tag":"looking back","definition":"to leave one's own country and settle elsewhere. The prefix e- is Latin ex- 'out': it views the person from the place left behind.","definitionCN":"离开本国到别处定居。前缀 e- 即拉丁语 ex-“向外”：它从被留下的那个地方看这个人。"},{"word":"immigrate","ipa":"/ˈɪmɪɡreɪt/","tag":"looking forward","definition":"to come into a country to settle there. The prefix im- is Latin in- 'into': it views the person from the place of arrival.","definitionCN":"进入某国并在此定居。前缀 im- 即拉丁语 in-“进入”：它从抵达地看这个人。"},{"word":"relocate","ipa":"/ˌriːləʊˈkeɪt/","tag":"business and households","definition":"to move to a new location, often with an employer or a company. It is more administrative than migrate and usually one-way and planned.","definitionCN":"搬到新地点，常指随雇主或公司搬迁。它比 migrate 更带行政色彩，通常是单向且有计划的。"},{"word":"transmigrate","ipa":"/trænzˈmaɪɡreɪt/","tag":"across, or between bodies","definition":"to migrate across or through something, and in religion to pass into another body after death. The prefix trans- 'across' adds a crossing.","definitionCN":"跨越某地迁移；在宗教中也指死后灵魂转入另一具身体。前缀 trans-“横越”加了一层“穿过”的意思。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Latin migrare 'to move from one place to another', the PIE root *mei- 'to go, change', and the direction-marked family emigrate, immigrate, transmigrate.","cn":"只用真实成分与真实同族词：拉丁语 migrare“从一处移到另一处”、原始印欧语词根 *mei-“走、改变”，以及带方向标记的 emigrate、immigrate、transmigrate。"},"normal":[{"en":"migr- means 'move from one place to another'. Migrate is the bare movement, with no prefix telling you which way.","cn":"migr- 表示“从一处移到另一处”。migrate 是光秃秃的移动，没有前缀告诉你方向。"},{"en":"emigrate has e- (ex-, 'out'): you leave. immigrate has im- (in-, 'into'): you arrive. The same journey looks different from each end.","cn":"emigrate 带 e-（ex-，“向外”）：你离开。immigrate 带 im-（in-，“进入”）：你抵达。同一趟旅程，从两端看不一样。"},{"en":"migration is the event, migrant is the mover, migratory is the habit. Three forms, three jobs.","cn":"migration 是事件，migrant 是移动者，migratory 是习性。三个形式，三份工作。"},{"en":"The root may be PIE *(e)meigw- 'to change', linked to *mei- 'to go, move'. Latin migrare is the branch that reached English.","cn":"词根可能是原始印欧语 *(e)meigw-“改变”，与 *mei-“走、移动”相关。拉丁语 migrare 是抵达英语的那一支。"},{"en":"Computing borrowed the bird: data migrate to a new platform the way flocks move to a new coast.","cn":"计算机借用了鸟：数据迁到新平台，就像鸟群迁到一片新的海岸。"}],"abstract":[{"en":"Picture a coastline at dusk and a line of wings crossing the last of the light. Nothing in the picture says whether they will come back.","cn":"想象黄昏的海岸线，以及一排翅膀划过最后一点光。这幅画里没有任何东西说明它们会不会回来。"},{"en":"Migration is measured from the mover, not from the border. That is why the same person is an emigrant to one country and an immigrant to another.","cn":"迁徙是从移动者身上度量的，不是从边界度量的。所以同一个人对一国是移出者，对另一国是移入者。"},{"en":"The word travels as far as its picture: birds, workers, cells, files. Wherever something leaves one place and keeps living in another, migrate still fits.","cn":"这个词跟着它的画面走得一样远：鸟、工人、细胞、文件。只要某物离开一处并在另一处继续存活，migrate 就仍然适用。"}]},"examples":[{"en":"The whales migrate thousands of kilometres to breed in warmer water.","cn":"鲸鱼迁徙数千公里，到更温暖的水域繁殖。"},{"en":"Her family migrated from the north to the coast three generations ago.","cn":"她家三代以前从北方迁到了海边。"},{"en":"The archive will migrate to a new server over the weekend.","cn":"档案库将在周末迁移到新的服务器上。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“买格瑞特”——买张票，格瑞特就跨过边界去了另一片土地 → migrate 迁移、迁徙（只借音，不表词源）","word":"migrate"},"root":"源自拉丁语 migrare“从一处移到另一处”，核心是“离开一块地面，落到另一块地面”。","sensesIntro":{"en":"Nine senses of migrate, all from one motion: a body leaves one place and arrives at another. The word never says which end matters, which is why birds, workers, cells and files can all use it.","cn":"migrate 的九个义项都来自同一个动作：一个个体离开一处，抵达另一处。这个词从不说哪一端更重要，所以鸟、工人、细胞与文件都能用它。"},"semanticMap":{"core":{"en":"CORE IMAGE: a group crossing from one horizon to another, with the departure and the arrival equally unnamed.","cn":"核心意象：一群身影从一条地平线越向另一条，出发地与抵达地同样不被点名。"},"chain":["ONE PLACE LEFT","A DISTANCE CROSSED","ANOTHER PLACE REACHED","THE TRIP REPEATS","A NEW LIFE BEGINS","THE MOVE ITSELF IS THE WORD"],"branches":[{"senses":"S1 · S8","en":"SEASONS: animals and herders move on a rhythm, and the journey may be a round trip rather than an exit.","cn":"季节：动物与牧民按节奏移动，这趟旅程可能是往返，而不是出走。"},{"senses":"S2 · S6","en":"HOUSEHOLDS: people move to settle or to work, and the move carries a family or a labour force.","cn":"家庭：人为定居或为工作而移动，这一移动承载的是一个家庭或一支劳动力。"},{"senses":"S3 · S9","en":"PLAIN MOTION: the oldest sense describes movement without direction, which is exactly what separates it from emigrate and immigrate.","cn":"平实移动：最老的义项描述无方向的移动，这正是它与 emigrate、immigrate 的分界。"},{"senses":"S4 · S7","en":"SYSTEMS: data and habits change platforms, and the old geography becomes a before and an after.","cn":"系统：数据与习惯更换平台，旧的地理变成“之前”与“之后”。"},{"senses":"S5","en":"THE BODY: cells make the same journey at millimetre scale, from one tissue to another.","cn":"身体：细胞以毫米尺度完成同一趟旅程，从一种组织到另一种。"}]},"affixes":{"intro":{"en":"Migrate is Latin migr- 'move, shift' plus the verb ending -ate. Direction is added by prefixes: e- 'out', im- 'in', trans- 'across'. English also builds -ion, -ant and -ory nouns and adjectives.","cn":"migrate 是拉丁语 migr-“移动、迁徙”加动词词尾 -ate。方向由前缀补充：e-“向外”、im-“向内”、trans-“横越”。英语还用 -ion、-ant、-ory 构成名词与形容词。"},"latinIntro":{"en":"Latin migrare 'to move from one place to another' gives the stem; migratio gives migration and migrans gives migrant. The family is Latin throughout, with no Greek element.","cn":"拉丁语 migrare“从一处移到另一处”提供词干；migratio 给出 migration，migrans 给出 migrant。这个词族从头到尾都是拉丁语，没有希腊语成分。"},"items":[{"word":"migrate","structure":"migr- (move) + -ate (verb)","meaning":"to move from one place to another","meaningCN":"从一处移到另一处（migr- 移动 + -ate 动词词尾）","example":"Some species migrate only once in a lifetime.","exampleCN":"有些物种一生只迁徙一次。"},{"word":"migration","structure":"migrat- + -ion (noun of action)","meaning":"the act or process of moving to another place","meaningCN":"迁移；迁徙（-ion 构成行为名词）","example":"The migration takes three generations to complete.","exampleCN":"这场迁徙要三代人才能完成。"},{"word":"migrant","structure":"migr- + -ant (person or agent)","meaning":"one who migrates","meaningCN":"迁徙者；移民（-ant 表示施动者）","example":"The camp houses migrant workers from four provinces.","exampleCN":"营地里住着来自四个省份的务工移民。"},{"word":"migratory","structure":"migrat- + -ory (adjective)","meaning":"having the habit of migrating","meaningCN":"有迁徙习性的；迁徙的（-ory 构成形容词）","example":"The wetland is a stopover for migratory birds.","exampleCN":"这片湿地是候鸟的中转站。"},{"word":"emigrate","structure":"e- (out) + migrate","meaning":"to leave one's country and settle elsewhere","meaningCN":"移出；迁离本国（e- 向外 + migrate）","example":"His parents emigrated in 1979.","exampleCN":"他的父母在 1979 年移居国外。"},{"word":"immigrate","structure":"im- (in) + migrate","meaning":"to come into a country and settle","meaningCN":"移入；迁入定居（im- 向内 + migrate）","example":"They immigrated with two suitcases and no English.","exampleCN":"他们带着两只箱子、一句英语也不会就迁了进来。"},{"word":"transmigrate","structure":"trans- (across) + migrate","meaning":"to pass across or into another body or place","meaningCN":"跨越迁移；灵魂转世（trans- 横越 + migrate）","example":"The doctrine says the soul transmigrates after death.","exampleCN":"该教义说灵魂在死后转世。"},{"word":"emigrant","structure":"e- (out) + migrant","meaning":"a person who leaves a country","meaningCN":"移出者；迁离本国的人","example":"The ship carried emigrants to the south.","exampleCN":"这艘船把移出者载往南方。"},{"word":"immigrant","structure":"im- (in) + migrant","meaning":"a person who comes to settle in a country","meaningCN":"移入者；迁入定居的人","example":"The city grew fast on immigrant labour.","exampleCN":"这座城市靠移民劳动力迅速扩张。"},{"word":"emigration","structure":"e- (out) + migration","meaning":"the act of leaving one's country","meaningCN":"移出；迁离（e- 向外 + migration）","example":"Emigration emptied the upland villages.","exampleCN":"人口迁出使高地村庄空了下来。"},{"word":"immigration","structure":"im- (in) + migration","meaning":"the act of entering and settling in a country","meaningCN":"移入；迁入定居（im- 向内 + migration）","example":"Immigration rules changed again last spring.","exampleCN":"移民入境规定去年春天又变了。"},{"word":"transmigration","structure":"trans- (across) + migration","meaning":"a passing across, or the passing of a soul into another body","meaningCN":"跨越迁移；灵魂转世（trans- 横越 + migration）","example":"Transmigration is central to the doctrine.","exampleCN":"转世之说在该教义中处于核心位置。"}],"latinEntries":[{"word":"migrare","structure":"PIE *(e)meigw- 'to change'","meaning":"to move from one place to another","meaningCN":"从一处移到另一处"},{"word":"migratio","structure":"migrat- + -io (noun of action)","meaning":"a removal, change of abode","meaningCN":"迁离；更换住处"},{"word":"migrans","structure":"present participle of migrare","meaning":"one who is migrating","meaningCN":"正在迁移的人或物"}]}},{"word":"military","ipa_uk":"/ˈmɪlɪtri/","ipa_us":"/ˈmɪləteri/","definition_zh":"军事的；军队的；军用的；军人式的；军队；军方","definition_en":"relating to soldiers, armed forces, or war; also, as a noun, the armed forces of a country taken as one body","core_image":"一队士兵踏着同一节奏行进，枪挎在肩，靴底压过碎石","scene":"At dawn the military column moved through the pass without a sound, rifles slung and boots crunching on the gravel.","sceneCN":"这里 military 是「军事的、军队的」（第 1 个义项：属于军队或战争的）；句意：黎明时分，这支军队的队伍悄无声息地穿过山口，枪挎在肩上，靴子踩得碎石作响。场景要点：天刚亮、狭窄山口、成列行进的士兵、肩上的步枪、碎石上传来的靴声。","pos":[{"tag":"adj.","zh":"军事的；军队的；军用的；军人式的"},{"tag":"n.","zh":"军队；军方（与定冠词连用，the military）"}],"collocations":[{"phrase":"military service","zh":"兵役；服兵役"},{"phrase":"military operation","zh":"军事行动"},{"phrase":"the military","zh":"军队；军方（作为一个整体）"},{"phrase":"military personnel","zh":"军事人员；军人"},{"phrase":"military spending","zh":"军费开支"},{"phrase":"military discipline","zh":"军纪；军队的纪律"},{"phrase":"military aid","zh":"军事援助"}],"forms":[{"label":"形容词比较级（more 式）","form":"more military"},{"label":"名词复数","form":"militaries"}],"derivatives":[{"word":"militarism","pos":"n.","zh":"军国主义；尚武精神"},{"word":"militarist","pos":"n.","zh":"军国主义者；军事迷"},{"word":"militaristic","pos":"adj.","zh":"军国主义的；黩武的"},{"word":"militarize","pos":"v.","zh":"使军事化；使军队化"},{"word":"militarization","pos":"n.","zh":"军事化"},{"word":"militarily","pos":"adv.","zh":"在军事上；以军事手段"}],"senses":[{"no":"01","title":"Of soldiers and war","titleCN":"属于军队与战争","definition":"relating to soldiers, armies, or the conduct of war in general","definitionCN":"与士兵、军队或战争行为有关的","example":"The museum's new wing is devoted to military history.","exampleCN":"博物馆的新展区专门展示军事史。","why":"Latin militaris was simply the adjective of miles, 'soldier'. Anything it described belonged to the soldier's world, and that broad belonging is still the first sense in English.","whyCN":"拉丁语 militaris 就是 miles（士兵）的形容词。它修饰的任何东西都属于士兵的世界，这种宽泛的归属至今仍是英语里的第一个义项。"},{"no":"02","title":"Done by soldiers, for soldiers","titleCN":"由军人执行、供军队使用","definition":"carried out by soldiers or intended for the armed forces, rather than merely discussing them","definitionCN":"由军人执行或供武装部队使用的，而不只是谈论军队","example":"The old airfield is now used for military training.","exampleCN":"这座旧机场现在用于军事训练。","why":"The adjective does not only label a topic; it also marks who acts and who benefits. A military operation is planned and run by soldiers, so the word moves from 'about soldiers' to 'by and for soldiers'.","whyCN":"这个形容词不只标注话题，还标明谁在行动、谁在受益。军事行动由军人筹划和执行，于是这个词从“关于士兵”走到“由士兵做、为士兵做”。"},{"no":"03","title":"Soldier-like precision","titleCN":"军人式的严整与精确","definition":"used figuratively of behaviour that is as exact, orderly, and disciplined as a soldier's","definitionCN":"比喻像军人一样精确、整齐、守纪律的行为","example":"She folded the map with military precision and handed it back.","exampleCN":"她以军人般的精确折好地图，递了回去。","why":"Soldiers drill until every movement is measured and repeated. The adjective borrows that drilled exactness and lends it to civilian actions that have nothing to do with armies.","whyCN":"士兵反复操练，直到每个动作都被量得准确、重复得整齐。这个形容词借来那种操练出来的精确，借给与军队无关的日常动作。"},{"no":"04","title":"By force, not by talk","titleCN":"诉诸武力的、尚武的","definition":"describing a solution or spirit that relies on armed force or favours it","definitionCN":"形容依靠武力或崇尚武力的解决办法与精神","example":"The dispute was settled by military means after talks failed.","exampleCN":"谈判失败后，这场争端以军事手段解决。","why":"If the soldier's instrument is force, then calling a solution military announces that force will be used. The adjective shifts from describing an institution to recommending its method.","whyCN":"如果士兵的工具是武力，那么把一个解决办法称为军事的，就是在宣告将动用武力。这个形容词从描述一种机构，转为推荐它的手段。"},{"no":"05","title":"The whole body of soldiers","titleCN":"军队（总称）","definition":"with the definite article, the armed forces of a country considered as one collective body","definitionCN":"与定冠词连用，指一国的武装力量整体","example":"The military were called in to clear the roads after the flood.","exampleCN":"洪水过后，军队被调来清理道路。","why":"The adjective became a noun by taking 'the': the military, short for the military forces. A collective noun names all the soldiers as one thing, just as the column in the core image moves as one body.","whyCN":"这个形容词加上定冠词就变成了名词：“the military”，是“the military forces”的省略。集合名词把所有士兵命名成一个东西，正如核心意象里的队伍作为一个整体移动。"},{"no":"06","title":"The military as a power bloc","titleCN":"军方：作为政治权力机构","definition":"the armed forces viewed as an institution that can act in politics and hold power","definitionCN":"把武装部队看作能够在政治中行动、掌握权力的机构","example":"The military seized power overnight and closed the parliament.","exampleCN":"军方一夜之间夺取政权，并关闭了议会。","why":"Once the column of soldiers acts as a single actor in public life, 'the military' stops meaning a crowd of men and starts meaning an institution with its own will and weight.","whyCN":"一旦这支队伍在公共生活中作为一个单一行动者行事，the military 就不再指一群士兵，而开始指一个有自己的意志与分量的机构。"},{"no":"07","title":"One soldier, old-fashioned","titleCN":"旧式的单个军人","definition":"in older usage, a soldier or a military man, countable and now rare","definitionCN":"旧时用法，指一名军人或军事人员，可数，现已罕见","example":"The old novel describes a retired officer simply as 'a military'.","exampleCN":"那本旧小说把一名退役军官径称为“一名军人”。","why":"The noun first named one person, 'a military man' (1736), before it named the whole body. The singular use survives only as an archaism, a fossil of the earlier step.","whyCN":"这个名词先指一个人，即“a military man”（1736 年），后来才指整个群体。单数用法只作为古语残存下来，是较早那一步的化石。"},{"no":"08","title":"Service in the ranks","titleCN":"军旅、服役","definition":"in phrases such as 'in the military', the state or career of serving in the armed forces","definitionCN":"在“in the military”一类短语中，指在武装部队中服役的状态或经历","example":"He spent six years in the military before returning to the farm.","exampleCN":"他服役六年，之后回到农场。","why":"To be in the military is to stand inside that collective body. The core image of a formed column becomes a place a person can enter, belong to, and leave.","whyCN":"身处军队，就是站进那个集体之中。核心意象里列队成形的队伍，变成了一个人可以进入、归属并离开的地方。"},{"no":"09","title":"A field of study","titleCN":"军事学科与军事史","definition":"used attributively to name an academic field whose subject is armies, wars, and defence","definitionCN":"作定语，命名以军队、战争与防务为对象的学科领域","example":"She teaches military history at the war college.","exampleCN":"她在军事学院教授军事史。","why":"The same adjective that marks soldiers' business can mark the study of that business. The object of the field is still the column, only now it is observed from a desk instead of a trench.","whyCN":"标记士兵事务的同一个形容词，也可以标记对这一事务的研究。这个领域的对象仍是那支队伍，只是现在是从书桌前观察，而不是从战壕里。"}],"etymology":{"intro":{"en":"Military is a Latin adjective that English borrowed through French in the fifteenth century; the collective noun arrived three centuries later, and the origin of the Latin base is still unsettled. Dates are approximate.","cn":"military 是 15 世纪经法语借入英语的拉丁语形容词；集合名词要晚三百年才出现，而拉丁语词根的来历至今没有定论。年代为大致估计。"},"items":[{"era":"MID-15c.","en":"First recorded in English as militari, 'pertaining to or befitting soldiers; used, done, or brought about by soldiers'. It came from Old French militaire (14c.) and directly from Latin militaris.","cn":"英语最早记录为 militari，意为“与士兵有关或适合士兵的；由士兵使用、完成或造成的”。它来自古法语 militaire（14 世纪），并直接来自拉丁语 militaris。"},{"era":"LATIN militaris","en":"Latin militaris meant 'of soldiers or war, of military service, warlike'. It was formed from miles (genitive militis), 'soldier', a word of unknown origin.","cn":"拉丁语 militaris 意为“士兵的、战争的、兵役的、尚武的”。它由 miles（属格 militis）“士兵”构成，而这个词的来历不明。"},{"era":"DISPUTED","en":"The origin of miles is unsettled. It may be Etruscan, or it may mean 'one who marches in a troop', which would connect it to Sanskrit melah 'assembly' and Greek homilos 'assembled crowd'. De Vaan finds it tempting to link it to milia 'thousands', hence *mili-it- 'who goes with the thousand'. None of these is proved.","cn":"miles 的来历没有定论。它可能来自伊特鲁里亚语，也可能意为“随队伍行进的人”，从而与梵语 melah“集会”、希腊语 homilos“聚集的人群”相联系。De Vaan 认为把它与 milia“数千”联系起来很诱人，即 *mili-it-“随千人同行的人”。这些说法都未被证明。"},{"era":"1736 / 1757","en":"The noun first meant 'a military man' (1736). 'Soldiers generally' is recorded from 1757, and it is commonly used only with the definite article.","cn":"名词最初意为“军人”（1736）。泛指“士兵、军队”的用法记录于 1757 年，而且通常只与定冠词连用。"},{"era":"1737 / 1827 / 1961","en":"The adjective spreads into fixed phrases: military age, the age at which one becomes liable for service (1737); military police (1827); and military-industrial complex, coined in Eisenhower's farewell speech (1961).","cn":"这个形容词扩散到固定短语中：military age 指应服兵役的年龄（1737）；military police 即军事警察（1827）；military-industrial complex 即军工复合体，由艾森豪威尔在告别演说中铸成（1961）。"},{"era":"MODERN / KIN","en":"Militia is a separate borrowing: 1580s, 'system of military discipline', from Latin militia 'military service', and only from the 1690s 'citizen army'. Militarism (1841) came from French militarisme. Military is the adjective, militia the citizen body, militarism the ideology.","cn":"militia 是另一次借入：16 世纪 80 年代指“军事训练制度”，来自拉丁语 militia“兵役”，到 17 世纪 90 年代才指“公民军队”。militarism（1841）来自法语 militarisme。military 是形容词，militia 是公民武装，militarism 是主义。"}]},"similar":{"note":{"en":"The first group shares the Latin miles stem but has drifted into different jobs; the second compares the ordinary words for organized fighters.","cn":"第一组共享拉丁语 miles 词干，却各自漂向不同的职责；第二组比较表示有组织武装人员的常用词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"militia","ipa":"/məˈlɪʃə/","tag":"citizen army","definition":"a body of citizens enrolled for military service in an emergency, not professional soldiers. It is a force, while military is the adjective of the professional institution.","definitionCN":"紧急时征召服役的公民队伍，不是职业军人。它是一支力量，而 military 是职业军队的形容词。"},{"word":"militant","ipa":"/ˈmɪlɪtənt/","tag":"aggressive advocate","definition":"willing to use strong or violent action for a cause, or a person who is. It describes a stance or a person, never an army as a whole.","definitionCN":"愿意为某项事业采取强硬或暴力行动的，或指这样的人。它描述一种立场或一个人，从不指整支军队。"},{"word":"militarism","ipa":"/ˈmɪlɪtərɪzəm/","tag":"ideology","definition":"the belief that a country should keep a strong military and use it aggressively. It names a doctrine, not the forces themselves.","definitionCN":"认为国家应保持强大军力并积极使用武力的信念。它命名一种主义，而不是军队本身。"},{"word":"paramilitary","ipa":"/ˌpærəˈmɪlətri/","tag":"beside the army","definition":"organized and armed like an army but outside the official armed forces. The prefix para- 'beside' marks the difference from regular military bodies.","definitionCN":"组织与武装像军队、却处于正规武装力量之外的。前缀 para-“在旁”标出它与正规军事组织的区别。"}]},{"heading":"NEAR MEANING","entries":[{"word":"army","ipa":"/ˈɑːmi/","tag":"land force","definition":"the branch of a country's forces that fights on land, or a large body of soldiers. It is one service, while the military can mean all services together.","definitionCN":"一国武装力量中在陆地作战的分支，或一大群士兵。它是一个军种，而 the military 可指所有军种的整体。"},{"word":"armed forces","ipa":"/ɑːmd ˈfɔːsɪz/","tag":"all branches","definition":"the combined military forces of a country, including army, navy, and air force. It is the full official phrase for what 'the military' names in one word.","definitionCN":"一国武装力量的总和，包括陆军、海军与空军。它是对 the military 一词所指对象的完整正式说法。"},{"word":"troops","ipa":"/truːps/","tag":"soldiers on duty","definition":"soldiers, especially those serving in a particular place or operation. It counts people, while the military names an institution.","definitionCN":"士兵，尤指在某一地点或行动中服役的人。它数的是人，而 the military 命名的是一种机构。"},{"word":"forces","ipa":"/ˈfɔːsɪz/","tag":"organized bodies","definition":"organized groups of soldiers, often qualified as land, air, or naval forces. It is a flexible plural, close to 'the military' but usually needs a qualifier.","definitionCN":"有组织的军人群体，常以陆地、空中或海上限定。它是灵活的复数，接近 the military，但通常需要限定语。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Latin miles 'soldier', its adjective militaris, the -ary ending, and the separate but related borrowings militia and militarism.","cn":"只用真实成分与真实同族词：拉丁语 miles“士兵”、它的形容词 militaris、后缀 -ary，以及另行借入但相关的 militia 与 militarism。"},"normal":[{"en":"miles is Latin for 'soldier'; militaris is its adjective. Military begins as nothing more than 'of the soldier'.","cn":"miles 是拉丁语的“士兵”，militaris 是它的形容词。military 最初不过是“士兵的”。"},{"en":"The adjective came first, in the fifteenth century; the noun 'the military' for soldiers as a body is recorded only in 1757.","cn":"形容词先出现，在 15 世纪；把士兵作为整体来称的 the military 直到 1757 年才有记录。"},{"en":"The -ary ending makes an adjective, so military, militarily, militarism and militarize all grow from the same stem with different endings.","cn":"-ary 结尾使它成为形容词，所以 military、militarily、militarism、militarize 都从同一词干加上不同词尾长出来。"},{"en":"militia is a separate borrowing from Latin militia 'military service'; its 'citizen army' sense is only from the 1690s.","cn":"militia 是从拉丁语 militia“兵役”另行借入的词；它的“公民军队”义要到 17 世纪 90 年代才出现。"},{"en":"The definite article matters: the military is the whole body, while a military is an old-fashioned way to say one soldier.","cn":"定冠词很关键：the military 指整个军队，而 a military 是旧式说法，指一名军人。"}],"abstract":[{"en":"Picture a column of boots striking gravel at the same instant. The sound is not many sounds but one sound repeated, and that is what makes it military.","cn":"想象一列靴子在同一瞬间踏在碎石上。那声音不是许多声音，而是一个声音的重复，正是这种重复使它成为“军事的”。"},{"en":"The adjective is a uniform that can be put on anything: a bridge, a budget, a history, a way of folding a map.","cn":"这个形容词是一套可以套在任何东西上的制服：一座桥、一份预算、一段历史、一种折地图的方式。"},{"en":"When the column stops marching and starts deciding, it becomes 'the military' — one actor with a will, not a crowd of men.","cn":"当这支队伍停止行进、开始作决定，它就变成了“军方”——一个有意愿的行动者，而不是一群士兵。"}]},"examples":[{"en":"Military spending rose for the third year in a row.","cn":"军费开支连续第三年上升。"},{"en":"The airfield is still under military control, and no civilian flights are allowed.","cn":"这座机场仍处于军事管制之下，不允许民用航班起降。"},{"en":"After the earthquake, the military was sent in to reopen the mountain roads.","cn":"地震之后，军队被派去重新打通山路。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“米里特力”——米里藏着一群特别有力气的壮汉，列队扛枪向前 → military 军事的；军队（只借音，不表词源）","word":"military"},"root":"源自拉丁语 miles“士兵”的形容词 militaris，核心是“属于士兵与军队的”。","sensesIntro":{"en":"Nine senses of military, all growing from one picture: a body of soldiers moving as a single column, and then acting as a single institution.","cn":"military 的九个义项都长自同一幅画面：一队士兵作为一个整体行进，随后作为一个整体机构行动。"},"semanticMap":{"core":{"en":"CORE IMAGE: a column of soldiers stepping as one body.","cn":"核心意象：一队士兵作为一个整体迈步。"},"chain":["OF THE SOLDIER","BY THE SOLDIER","AS EXACT AS DRILL","BY FORCE","THE WHOLE BODY","AN INSTITUTION WITH POWER"],"branches":[{"senses":"S1 · S2","en":"SOLDIER'S WORLD: the adjective first marks what belongs to soldiers, then what is done by them and for them.","cn":"士兵的世界：这个形容词先标记属于士兵的东西，再标记由士兵做、为士兵做的事。"},{"senses":"S3 · S4","en":"BORROWED QUALITIES: drilled exactness is lent to civilian actions, and the soldier's instrument, force, is lent to solutions.","cn":"借来的品质：操练出的精确被借给日常动作，士兵的工具即武力被借给解决办法。"},{"senses":"S5 · S6","en":"COLLECTIVE AND POLITICAL: 'the military' first names all soldiers as one body, then names that body as a power in politics.","cn":"集体与政治：the military 先把所有士兵命名成一个整体，再把这个整体命名为政治中的一种权力。"},{"senses":"S7 · S8","en":"ONE MAN AND A CAREER: the old singular names a single soldier, while 'in the military' names service inside the body.","cn":"个人与职业：旧式单数指一名军人，而 in the military 指在这个整体内部服役。"},{"senses":"S9","en":"THE STUDY: the same adjective marks the academic field that observes armies from a desk.","cn":"研究领域：同一个形容词标记从书桌前观察军队的学科。"}]},"affixes":{"intro":{"en":"Military is a Latin adjective ending in -ary; the stem milit- also carries -ia, -ism, -ist, -istic, -ize and -ation into English. The prefix para- in paramilitary is Greek, added later.","cn":"military 是带 -ary 后缀的拉丁语形容词；词干 milit- 还把 -ia、-ism、-ist、-istic、-ize 与 -ation 带进英语。paramilitary 里的前缀 para- 是后来加上的希腊语成分。"},"latinIntro":{"en":"Three Latin words sit behind the family: miles 'soldier', its adjective militaris, and militia 'military service'. The origin of miles itself is disputed, so no deeper root can be stated as fact.","cn":"这个词族背后有三个拉丁词：miles“士兵”、它的形容词 militaris，以及 militia“兵役”。miles 本身的来历有争议，因此不能把更深的词根当作事实来陈述。"},"items":[{"word":"military","structure":"milit- (soldier) + -ary (adjective)","meaning":"of soldiers or war","meaningCN":"士兵的；战争的（milit- 士兵 + -ary 形容词后缀）","example":"The country keeps a large military budget.","exampleCN":"这个国家维持着庞大的军事预算。"},{"word":"militarily","structure":"military + -ly (adverb)","meaning":"in a military way; by military means","meaningCN":"在军事上；以军事手段（-ly 构成副词）","example":"The region is militarily important but economically poor.","exampleCN":"这个地区军事上重要，经济上却贫穷。"},{"word":"militarism","structure":"military + -ism (doctrine)","meaning":"the belief in strong armed forces and their use","meaningCN":"军国主义；尚武精神（-ism 构成主义）","example":"The book traces the rise of militarism before the war.","exampleCN":"这本书追溯了战前军国主义的兴起。"},{"word":"militarist","structure":"military + -ist (person)","meaning":"a supporter of militarism","meaningCN":"军国主义者（-ist 指人）","example":"The general was widely seen as a militarist.","exampleCN":"这位将军被普遍看作军国主义者。"},{"word":"militaristic","structure":"militarist + -ic (adjective)","meaning":"marked by militarism","meaningCN":"军国主义的；黩武的（-ic 构成形容词）","example":"The parade had a strongly militaristic tone.","exampleCN":"这场阅兵带有强烈的黩武色彩。"},{"word":"militarize","structure":"military + -ize (verb)","meaning":"to make military in character","meaningCN":"使军事化（-ize 构成动词）","example":"The island was militarized during the crisis.","exampleCN":"危机期间，这座岛屿被军事化了。"},{"word":"militarization","structure":"militarize + -ation (noun of process)","meaning":"the process of becoming military","meaningCN":"军事化（-ation 构成过程名词）","example":"People protested against the militarization of the police.","exampleCN":"人们抗议警察的军事化。"},{"word":"militia","structure":"Latin militia 'military service'","meaning":"a citizen army called out in an emergency","meaningCN":"民兵组织；紧急时征召的公民武装（拉丁语“兵役”）","example":"The local militia guarded the bridge.","exampleCN":"当地民兵守卫着那座桥。"},{"word":"militant","structure":"milit- (soldier) + -ant (adjective/person)","meaning":"aggressively active for a cause","meaningCN":"好战的；激进分子（-ant 构成形容词或指人）","example":"A militant wing of the movement rejected the talks.","exampleCN":"这场运动的激进一派拒绝了谈判。"},{"word":"militate","structure":"milit- (soldier) + -ate (verb)","meaning":"to work against something, as evidence or circumstance","meaningCN":"妨碍；起不利作用（-ate 构成动词）","example":"The high cost militates against any quick repair.","exampleCN":"高昂的成本不利于任何快速修复。"},{"word":"paramilitary","structure":"para- (beside) + military","meaning":"armed like an army but outside it","meaningCN":"准军事的（para- 在旁 + military 军事的）","example":"A paramilitary group controlled the border road.","exampleCN":"一个准军事组织控制着那条边境公路。"}],"latinEntries":[{"word":"militaris","structure":"miles (soldier) + -aris (adjective)","meaning":"of soldiers or war","meaningCN":"士兵的；战争的（miles 士兵 + -aris 形容词后缀）"},{"word":"miles","structure":"root of unknown origin","meaning":"soldier","meaningCN":"士兵（词源不明，可能来自伊特鲁里亚语）"},{"word":"militia","structure":"miles (soldier) + -itia (abstract noun)","meaning":"military service, warfare","meaningCN":"兵役；战争（miles 士兵 + -itia 抽象名词后缀）"}]}},{"word":"minimize","ipa_uk":"/ˈmɪnɪmaɪz/","ipa_us":"/ˈmɪnəmaɪz/","definition_zh":"使最小化；把……降到最低；贬低；淡化","definition_en":"to reduce something to the smallest possible amount or degree, or to treat it as less important than it really is","core_image":"把一只旋钮一路拧到最左端、直到归零的位置","scene":"The surgeon spent the first hour planning a smaller incision to minimize blood loss.","sceneCN":"这里 minimize 是「把失血降到最低」（第 4 个义项：把损害、伤害减轻到最小）；句意：外科医生用第一个小时设计更小的切口，以把失血降到最低。场景要点：手术灯下的切口标记、旁边摆着的一袋备用血、医生反复比量的尺子。","pos":[{"tag":"vt.","zh":"使最小化；把……降到最低"},{"tag":"vt.","zh":"贬低；淡化；轻描淡写"}],"collocations":[{"phrase":"minimize risk","zh":"把风险降到最低"},{"phrase":"minimize cost","zh":"把成本压到最低"},{"phrase":"minimize damage","zh":"把损害减到最小"},{"phrase":"minimize the impact of","zh":"把……的影响减到最小"},{"phrase":"minimize loss","zh":"把损失降到最低"},{"phrase":"minimize the chance of error","zh":"把出错的可能性降到最低"},{"phrase":"minimize disruption","zh":"把干扰减到最小"}],"forms":[{"label":"三单（he/she/it）","form":"minimizes"},{"label":"过去式（已经发生）","form":"minimized"},{"label":"过去分词（完成／被动）","form":"minimized"},{"label":"现在分词（进行体）","form":"minimizing"}],"derivatives":[{"word":"minimum","pos":"n./adj.","zh":"最小值；最低限度；最小的"},{"word":"minimal","pos":"adj.","zh":"极小的；最低限度的"},{"word":"minimization","pos":"n.","zh":"最小化；最小化过程"},{"word":"minimizer","pos":"n.","zh":"把事物压到最小的人；求极小值者"},{"word":"minimalism","pos":"n.","zh":"极简主义"},{"word":"minimise","pos":"v.","zh":"使最小化（英式拼写）"}],"senses":[{"no":"01","title":"Reach the mathematical minimum","titleCN":"数学上取最小值","definition":"to find or reach the lowest value of a function, quantity, or variable","definitionCN":"求取或达到函数、数量、变量的最低值","example":"We minimize the cost function by adjusting both weights at once.","exampleCN":"我们同时调整两个权重，使代价函数取最小值。","why":"Latin minimus names the bottom point of a scale. The verb makes an object arrive at that point, so the mathematical sense is the image in its plainest form.","whyCN":"拉丁语 minimus 指刻度的底端。这个动词让对象抵达那个点，因此数学义是这幅意象最朴素的形态。"},{"no":"02","title":"Cost: squeeze the spending down","titleCN":"成本：把开支压到最低","definition":"to keep costs, spending, or prices as low as possible","definitionCN":"把成本、开支或价格保持在尽可能低的水平","example":"The airline minimized costs by flying older planes.","exampleCN":"这家航空公司靠飞更旧的飞机把成本压到最低。","why":"Cost is a quantity on a dial. Turning that dial to the left end is the budget version of the gesture, and it is the most common business use.","whyCN":"成本是刻度盘上的一个量。把旋钮拧到最左端，就是同一个动作在预算里的版本，也是商业中最常见的用法。"},{"no":"03","title":"Risk: keep the danger small","titleCN":"风险：把危险压小","definition":"to reduce the probability or size of a possible harm","definitionCN":"降低某种可能伤害的发生概率或规模","example":"Investors diversify their holdings to minimize risk.","exampleCN":"投资者分散持仓，以把风险降到最低。","why":"Risk is a probability of loss. Minimizing it moves that probability toward zero, the floor of its own small scale.","whyCN":"风险是损失发生的概率。最小化就是把这个概率推向零，也就是它自己那一小段刻度的底端。"},{"no":"04","title":"Damage: leave as little harm as possible","titleCN":"损害：让伤害尽量少","definition":"to limit the harm done to people, property, or the environment","definitionCN":"限制对人、财产或环境造成的伤害","example":"The spill was contained to minimize damage to the river.","exampleCN":"泄漏被控制住，以把对河流的损害减到最小。","why":"Damage is what remains after an accident. Minimizing it means shrinking the remainder, not preventing the accident itself.","whyCN":"损害是事故之后留下的东西。最小化是把这个剩余量缩小，而不是阻止事故本身。"},{"no":"05","title":"Error and delay: shrink the unwanted amount","titleCN":"错误与延误：把不需要的量缩小","definition":"to make errors, delays, or other unwanted quantities as small as possible","definitionCN":"把错误、延误或其他不想要的量做到尽可能小","example":"Every figure was checked twice to minimize the chance of error.","exampleCN":"每个数字都核对了两遍，以把出错的可能性降到最低。","why":"An error is an unwanted quantity on a scale that one would rather see at zero. The same verb now measures what should not be there.","whyCN":"错误是一把尺子上不希望出现的量，人们宁愿它停在零。这个动词于是用来衡量“本不该存在的东西”。"},{"no":"06","title":"Computing: shrink a window to a corner","titleCN":"计算机：把窗口缩到角落","definition":"to reduce a window on a screen to a small bar or icon","definitionCN":"把屏幕上的窗口缩成一条小栏或一个图标","example":"Click the minus sign to minimize the window.","exampleCN":"点击减号即可把窗口最小化。","why":"A window has a size scale whose floor is the smallest allowed bar. The command drives it to that floor, making the metaphor visible as a button.","whyCN":"窗口有一个尺寸刻度，它的底端就是允许的最小条栏。这个命令把窗口推到那层底端，让比喻变成了一个可见的按钮。"},{"no":"07","title":"Downplay a person's role","titleCN":"贬低某人的作用","definition":"to make someone's contribution or importance seem smaller than it is","definitionCN":"使某人的贡献或重要性显得比实际更小","example":"The report minimizes the role of local volunteers.","exampleCN":"这份报告贬低了当地志愿者的作用。","why":"The scale has moved from things to reputation: a person's role is described as if it occupied a smaller notch than it really does.","whyCN":"尺子从实物移到了名声：一个人的作用被说成只占一个比实际更小的刻度。"},{"no":"08","title":"Soften the seriousness of something","titleCN":"淡化事情的严重性","definition":"to speak of a problem or danger as less serious than it is","definitionCN":"把问题或危险说得没有实际那么严重","example":"Officials minimized the seriousness of the leak.","exampleCN":"官员们淡化了这次泄漏的严重性。","why":"Here the quantity being reduced is not the harm but the reported size of the harm; the words shrink the picture while the thing stays the same.","whyCN":"这里被缩小的不是伤害本身，而是伤害被报告出来的大小；话把画面缩小了，而事情本身没有变。"},{"no":"09","title":"Engineering: cut a design down to essentials","titleCN":"工程：把设计削减到本质","definition":"to reduce the number of parts, steps, or features in a design to the smallest workable set","definitionCN":"把设计中的零件、步骤或功能削减到可工作的最小集合","example":"The redesign minimizes moving parts and therefore wear.","exampleCN":"重新设计把活动部件减到最少，因此也减少了磨损。","why":"Fewer parts means less on the scale. Minimizing here is not about one number but about removing everything that is not needed.","whyCN":"零件更少，意味着刻度上的东西更少。这里的最小化不是压一个数字，而是删掉一切不必要的东西。"}],"etymology":{"intro":{"en":"Minimize is an English coinage of 1802 from minimum + -ize. Its Latin base and the later 'belittle' sense are both documented; dates are those given by standard etymological references.","cn":"minimize 是 1802 年由 minimum 加 -ize 构成的英语自造词。它的拉丁词基以及后来“贬低”的义项都有记载；年代采用通行词源资料的说法。"},"items":[{"era":"1802","en":"First recorded in English meaning 'to reduce to a minimum, make as little as possible'. It is an English formation from minimum + -ize, first attested in Bentham.","cn":"英语中最早记录于 1802 年，意为“减到最低、使尽可能小”。它是由 minimum 加 -ize 构成的英语自造词，最早可考的使用者是边沁。"},{"era":"1660s","en":"Minimum entered English meaning 'the smallest portion into which matter is divisible', a sense now obsolete; it came from Latin minimum, the neuter of minimus 'smallest'.","cn":"minimum 于 17 世纪 60 年代进入英语，意为“物质可分割的最小部分”，这一义项今已废弃；它来自拉丁语 minimum，即 minimus“最小的”的中性形式。"},{"era":"LATIN","en":"Latin minimus is the superlative of minor 'smaller', and minor belongs to the same family as minus and minuere 'to lessen'. The whole set describes one end of a scale.","cn":"拉丁语 minimus 是 minor“更小的”的最高级，而 minor 与 minus、minuere“减少”同属一个词族。整组词描述的是同一把尺子的一端。"},{"era":"PIE","en":"The family goes back to PIE *mei- (2) 'small', the root also behind diminish, minute, minuscule, minister and minutia.","cn":"这个词族可追溯到原始印欧语 *mei-（第二支）“小”，该词根也是 diminish、minute、minuscule、minister、minutia 的来源。"},{"era":"1875","en":"The sense 'to depreciate, treat slightingly' is recorded. This is the branch that lets minimize mean 'belittle' as well as 'reduce', and it explains why the word can sound evasive.","cn":"“贬低、轻视地对待”这一义项于 1875 年有记录。正是这一支让 minimize 既能表示“减少”，也能表示“贬低”，也解释了它为何有时听起来像在回避。"},{"era":"MODERN ENGLISH","en":"British spelling is minimise. Minimization, minimizer, minimal and minimalism fill out the family. Maximize and minimize are a matched pair, both recorded in 1802 and both used by Bentham.","cn":"英式拼写为 minimise。minimization、minimizer、minimal、minimalism 补足了词族。maximize 与 minimize 是一对配套词，都记录于 1802 年，都出自边沁。"}]},"similar":{"note":{"en":"The first group separates the noun, the adjective, the British spelling and the rare short noun. The second group compares minimize with plain reduce, with lessen, with rhetorical downplay, and with its exact opposite, maximize.","cn":"第一组区分名词、形容词、英式拼写和一个罕见的短名词；第二组把 minimize 与普通的 reduce、与 lessen、与修辞上的 downplay，以及它的正对面 maximize 作比较。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"minimum","ipa":"/ˈmɪnɪməm/","tag":"base noun","definition":"the smallest amount or degree possible. It is the noun that minimize was built from, not a synonym of the verb.","definitionCN":"可能的最小数量或程度。它是构成 minimize 的名词词基，而不是这个动词的同义词。"},{"word":"minimal","ipa":"/ˈmɪnɪməl/","tag":"adjective","definition":"very small in amount or degree. It describes a state, while minimize names the act of bringing that state about.","definitionCN":"数量或程度极小的。它描述一种状态，而 minimize 命名把这种状态造成出来的动作。"},{"word":"minimise","ipa":"/ˈmɪnɪmaɪz/","tag":"British spelling","definition":"the British spelling of minimize, with -ise instead of -ize. It is the same word, not a different meaning.","definitionCN":"minimize 的英式拼写，用 -ise 代替 -ize。它是同一个词，不是另一个词义。"},{"word":"minim","ipa":"/ˈmɪnɪm/","tag":"rare noun","definition":"a tiny amount, or a note of very short duration. It shares the 'small' root but is not a form of the verb.","definitionCN":"极小的量，或时值很短的音符。它共享“小”的词根，却不是这个动词的词形。"}]},{"heading":"NEAR MEANING","entries":[{"word":"reduce","ipa":"/rɪˈdjuːs/","tag":"plain decrease","definition":"to make something smaller in size or amount. It names the movement, not the floor: a reduced price need not be the lowest possible price.","definitionCN":"使某物在尺寸或数量上变小。它命名移动，而不命名底端：降价并不等于降到可能的最低价格。"},{"word":"lessen","ipa":"/ˈlesn/","tag":"degree","definition":"to make something smaller in degree or intensity, often a feeling or an effect. It is more literary and more limited than minimize.","definitionCN":"使某事物在程度或强度上变小，常指感受或效果。它比 minimize 更书面，适用范围也更窄。"},{"word":"downplay","ipa":"/ˌdaʊnˈpleɪ/","tag":"rhetorical","definition":"to make something seem less important than it is. It targets the description, while minimize can target either the thing or the description.","definitionCN":"使某事物显得没有实际那么重要。它针对的是描述，而 minimize 既可针对事物，也可针对描述。"},{"word":"maximize","ipa":"/ˈmæksɪmaɪz/","tag":"direct antonym","definition":"to make as great as possible. It is the exact opposite pole: one verb turns the dial to the left, the other to the right.","definitionCN":"使尽可能大。它正是对立的那一端：一个动词把旋钮向左拧，另一个向右拧。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: minimum + -ize, the Latin superlative minimus, the *mei- 'small' family, and the matched pair minimize / maximize.","cn":"只用真实成分与真实同族词：minimum 加 -ize、拉丁最高级 minimus、*mei-“小”词族，以及成对的 minimize／maximize。"},"normal":[{"en":"Minimum is the floor of a scale and -ize means 'to make'. Minimize is simply 'to make minimum'.","cn":"minimum 是刻度的底端，-ize 意为“使……”。minimize 就是“使达到最小”。"},{"en":"Minimus is the Latin superlative of minor 'smaller'; the same root gives minimum, minor, minus and diminish.","cn":"minimus 是拉丁语 minor“更小的”的最高级；同一词根还给出 minimum、minor、minus、diminish。"},{"en":"Minimize and maximize were both recorded in 1802, both in Bentham: one drives to the floor of the scale, the other to the ceiling.","cn":"minimize 与 maximize 都记录于 1802 年，都出自边沁：一个把刻度推到低端，一个推到顶端。"},{"en":"In business writing minimize collocates with risk, cost, damage, loss and disruption — unwanted quantities that one wants near zero.","cn":"在商业写作里，minimize 常与 risk、cost、damage、loss、disruption 搭配——都是人们希望接近零的不想要的量。"},{"en":"In computing, minimize is the button that shrinks a window to a bar; the smallest allowed bar is the floor of that scale.","cn":"在计算机里，minimize 是把窗口缩成一条栏的按钮；允许的最小条栏就是那把尺子的底端。"}],"abstract":[{"en":"Picture a dial with a hard stop at the left end. You can turn it down to the stop and no further; that stop is what minimum means.","cn":"想象一只左端有硬止点的旋钮。你能把它拧到止点，再也不能多拧一格；那个止点就是 minimum 的含义。"},{"en":"A minimum is a floor, not a direction: minimizing tells you where to stop, not how much effort it takes to get there.","cn":"最小值是地板，不是方向：minimize 告诉你该停在哪里，却没说你得花多大力气走到那里。"},{"en":"The same verb can shrink a thing or shrink its description. Shrinking the description is what makes minimize sound like an excuse.","cn":"同一个动词既能缩小事物，也能缩小对事物的描述。缩小描述，正是 minimize 听起来像借口的缘故。"}]},"examples":[{"en":"Keep the lid on the pan to minimize evaporation.","cn":"盖上锅盖，把蒸发减到最少。"},{"en":"The company moved its servers abroad to minimize tax.","cn":"这家公司把服务器迁到国外，以把税负压到最低。"},{"en":"She minimized her own part in the rescue.","cn":"她把自己在救援中的作用说得很小。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“迷你麦子”——把麦子磨得越来越小，最后只剩手心里一小撮 → minimize 最小化、降到最低","word":"minimize"},"root":"由 minimum“最小量”加 -ize“使……”构成，minimum 又来自拉丁语 minimus“最小的”，核心是“把某物拧到刻度的最左端”。","sensesIntro":{"en":"Nine senses of minimize, all from one gesture: a dial is turned to the far left until it reaches the floor, whether the scale measures a function, a cost, a risk, a window, or a person's reputation.","cn":"minimize 的九个义项都来自同一个动作：把旋钮一路拧到最左端，直到触底——无论这把尺子量的是函数、成本、风险、窗口，还是一个人的名声。"},"semanticMap":{"core":{"en":"CORE IMAGE: a dial turned to the far left until it stops at the bottom of its scale.","cn":"核心意象：一只旋钮被拧到最左端，停在刻度的底端。"},"chain":["A SCALE WITH A FLOOR","TURN TO THE LEFT","CUT TO THE LEAST","SHRINK TO A CORNER","MAKE IT LOOK SMALLER","DOWN TO ZERO"],"branches":[{"senses":"S1","en":"NUMBERS: a function has a lowest value, and minimizing moves the result down to that value.","cn":"数值：函数有一个最低值，最小化就是把结果压到那个值上。"},{"senses":"S2 · S3 · S9","en":"COST AND ENGINEERING: money, risk and moving parts are quantities to be cut down to the floor.","cn":"成本与工程：金钱、风险与活动部件都是要被削到底端的量。"},{"senses":"S4 · S5","en":"HARM: damage and the chance of error are remainders to be shrunk so that as little as possible is left.","cn":"伤害：损害与出错概率都是要被缩小的剩余量，好让最后剩下的尽可能少。"},{"senses":"S6","en":"INTERFACE: the window shrinks to the smallest allowed bar, its own floor.","cn":"界面：窗口缩到允许的最小条栏，也就是它自己的底端。"},{"senses":"S7 · S8","en":"RHETORIC: a person's role or a danger is made to look smaller than it is, so the scale now measures appearance.","cn":"修辞：一个人的作用或一桩危险被说得比实际小，于是这把尺子量的是“看起来的大小”。"}]},"affixes":{"intro":{"en":"Minimize is a complete noun plus a living suffix: minimum + -ize. The same Latin superlative supplies a large family of words about smallness and reduction.","cn":"minimize 是一个完整名词加一个活后缀：minimum 加 -ize。同一个拉丁最高级还供应了一大群关于“小”与“减少”的词。"},"latinIntro":{"en":"Latin minimus 'smallest' is the superlative of minor 'smaller', itself formed from the *mei- family. Minimum is the neuter form used as a noun; minus is a related neuter form meaning 'less'.","cn":"拉丁语 minimus“最小的”是 minor“更小的”的最高级，而 minor 本身出自 *mei- 词族。minimum 是作名词用的中性形式；minus 是表示“更少”的相关中性形式。"},"items":[{"word":"minimize","structure":"minimum + -ize (verb)","meaning":"to make as small as possible","meaningCN":"使尽可能小；最小化（-ize 构成动词）","example":"The plan minimizes the number of transfers.","exampleCN":"这个方案把换乘次数减到最少。"},{"word":"minimum","structure":"minim- + -um (neuter superlative ending)","meaning":"the smallest amount or degree","meaningCN":"最小量；最低限度（-um 为中性最高级词尾）","example":"The machine needs a minimum of two litres of oil.","exampleCN":"这台机器至少需要两升油。"},{"word":"minimal","structure":"minimum + -al (adjective)","meaning":"very small; at the minimum","meaningCN":"极小的；最低限度的（-al 构成形容词）","example":"The storm caused minimal damage.","exampleCN":"这场风暴造成的损害极小。"},{"word":"minimization","structure":"minimize + -ation (noun of process)","meaning":"the process of reducing something to the least possible","meaningCN":"最小化；最小化过程（-ation 构成过程名词）","example":"Waste minimization saved the plant a fortune.","exampleCN":"把浪费最小化为工厂省下一大笔钱。"},{"word":"minimizer","structure":"minimize + -er (person or thing that does)","meaning":"one who seeks the minimum, or a device that reduces something","meaningCN":"求最小值者；把事物压到最小的人或装置（-er 表示行为者）","example":"As a minimizer, he packs only what fits in one bag.","exampleCN":"作为一个凡事求最少的人，他只带一个包能装下的东西。"},{"word":"minimise","structure":"minimize + British -ise spelling","meaning":"British spelling of minimize","meaningCN":"minimize 的英式拼写（-ise）","example":"The guide advises households to minimise water use.","exampleCN":"这份指南建议家庭把用水减到最少。"},{"word":"minim","structure":"Latin minimus, a short form","meaning":"a tiny amount; a note of short duration","meaningCN":"极小的量；短音符（来自拉丁语 minimus）","example":"The recipe calls for a minim of salt.","exampleCN":"这份食谱只要一丁点儿盐。"},{"word":"minus","structure":"Latin minus, neuter of minor","meaning":"less; the subtraction sign","meaningCN":"减去；负号；不利因素（拉丁语 minus，minor 的中性形式）","example":"Ten minus four is six.","exampleCN":"十减四等于六。"},{"word":"diminish","structure":"di- (away) + minuere (to lessen)","meaning":"to make or become smaller","meaningCN":"减少；削弱（di- 离开 + minuere 减少）","example":"The noise diminished as the train moved away.","exampleCN":"火车开远后，噪声渐渐变小。"},{"word":"minute","structure":"Latin minutus 'small', from minuere","meaning":"extremely small (as an adjective)","meaningCN":"极小的（作形容词，来自拉丁语 minutus“小的”）","example":"A minute crack appeared in the glass.","exampleCN":"玻璃上出现了一道极细的裂缝。"}],"latinEntries":[{"word":"minimus","structure":"superlative of minor 'smaller'","meaning":"smallest, least","meaningCN":"最小的；最少的"},{"word":"minor","structure":"Latin comparative, from PIE *mei- 'small'","meaning":"smaller, lesser, junior","meaningCN":"更小的；较少的；较年幼的"},{"word":"minimum","structure":"neuter of minimus, used as a noun","meaning":"the smallest thing or amount","meaningCN":"最小者；最小量（minimus 的中性形式作名词）"}]}},{"word":"minor","ipa_uk":"/ˈmaɪnə/","ipa_us":"/ˈmaɪnər/","definition_zh":"较小的；次要的；轻微的；未成年的；（音乐）小调的；未成年人；辅修科目","definition_en":"smaller, less important, or less serious than others; also a person below the legal age, or a secondary subject of study","core_image":"天平上较轻的那一端：同一对砝码里偏小的一个","scene":"The report listed three minor errors, none of which changed the conclusion.","sceneCN":"这里 minor 是「轻微的、不严重的」（第 3 个义项：程度轻、不严重）；句意：报告列出三处轻微错误，没有一处改变结论。场景要点：一份校样上三处小小的红笔改动、旁边依然通过的结论页、天平上微微上翘的一端。","pos":[{"tag":"adj.","zh":"较小的；次要的；轻微的；未成年的；（音乐）小调的"},{"tag":"n.","zh":"未成年人；辅修科目；（逻辑）小前提"}],"collocations":[{"phrase":"minor damage","zh":"轻微损坏"},{"phrase":"a minor role","zh":"次要角色；小角色"},{"phrase":"a minor accident","zh":"小事故"},{"phrase":"a minor change","zh":"细微改动"},{"phrase":"the minor leagues","zh":"（体育）小联盟；低级别联赛"},{"phrase":"a minor key","zh":"小调；小调调性"},{"phrase":"minor in history","zh":"辅修历史"}],"forms":[{"label":"名词复数（形容词无比较级形式）","form":"minors"}],"derivatives":[{"word":"minority","pos":"n.","zh":"少数；少数派；未成年状态"},{"word":"minority","pos":"adj.","zh":"少数派的；少数族群的（作定语）"},{"word":"minor league","pos":"n./adj.","zh":"小联盟；低级别的"},{"word":"minor key","pos":"n.","zh":"小调；小调调性"},{"word":"Minorite","pos":"n.","zh":"方济各会修士（历史用语，源自“小兄弟会”）"}],"senses":[{"no":"01","title":"The smaller of two things","titleCN":"两者中较小的一个","definition":"smaller in size, extent, or number when compared with a paired thing","definitionCN":"与配对的事物相比，在尺寸、范围或数量上更小","example":"The minor axis of the ellipse is the shorter one.","exampleCN":"椭圆的短轴就是较短的那条轴。","why":"Latin minor is a comparative, 'smaller'. It does not mean small in general but smaller than the other member of a pair, which is why the word so often appears beside major.","whyCN":"拉丁语 minor 是比较级，意为“更小的”。它不是泛泛地表示小，而是比同一对里的另一个更小，因此这个词常与 major 并出现。"},{"no":"02","title":"Less important: a secondary part","titleCN":"次要的：处于从属位置","definition":"less important, powerful, or influential than the main person or thing","definitionCN":"不如主要的人或事物重要、有力量或有影响","example":"He played a minor role in the negotiations.","exampleCN":"他在谈判中只起了次要作用。","why":"Rank is treated as weight on a balance. The lighter pan rises, and whatever sits there is minor: present, but not carrying the decision.","whyCN":"等级被当成天平上的重量。较轻的那一端会翘起，放在那一端的东西就是 minor：它在场，却不承担决定。"},{"no":"03","title":"Slight: not serious","titleCN":"轻微的：不严重","definition":"small enough in degree to be unimportant or easy to deal with","definitionCN":"程度小到无关紧要或容易处理","example":"She suffered only minor injuries in the crash.","exampleCN":"她在撞车中只受了轻伤。","why":"The comparison has faded and only the smallness remains. A minor injury is not measured against a major one; it is simply below the threshold of seriousness.","whyCN":"比较对象已经淡去，只剩下“小”。轻伤并不是拿来与重伤对比，它只是落在“严重”这道门槛之下。"},{"no":"04","title":"Underage: below the legal age","titleCN":"未成年的：低于法定年龄","definition":"not yet old enough to have full legal rights or responsibilities","definitionCN":"年龄尚不足以拥有完整法律权利或承担责任","example":"Minor children must be accompanied by an adult.","exampleCN":"未成年子女必须由成年人陪同。","why":"Age is another scale, and the legal threshold is the line between full and lesser status. A person below that line is minor in the eyes of the law.","whyCN":"年龄是另一把尺子，法定门槛就是完整身份与次一等身份之间的界线。线以下的人在法律眼里就是 minor。"},{"no":"05","title":"Music: a minor key or interval","titleCN":"音乐：小调或小音程","definition":"in music, belonging to a key or interval built on a minor third, shorter than the corresponding major one","definitionCN":"在音乐中，属于以小三度构成的小调或音程，比对应的大调或大音程更短","example":"The second movement slips into a minor key.","exampleCN":"第二乐章转入了小调。","why":"The interval is literally lesser: a minor third is shorter than the major third. The word keeps its comparative sense inside music theory.","whyCN":"这个音程字面上就是“较小的”：小三度比大三度短。这个词在乐理内部保留了它的比较级含义。"},{"no":"06","title":"Sports: the minor leagues","titleCN":"体育：低级别联赛","definition":"in sport, the leagues or competitions below the top professional level","definitionCN":"体育中低于顶级职业水平的联赛或赛事","example":"He spent four seasons in the minor leagues before being called up.","exampleCN":"他在小联盟打了四个赛季才被上调。","why":"The league table is a ranking, and the minor leagues sit one step below the major ones. The word marks position on that ladder, not the size of the players.","whyCN":"联赛表就是一张排名，小联盟坐在大联盟下面一级。这个词标记的是梯子上的位置，而不是球员的体型。"},{"no":"07","title":"Logic: the minor premise","titleCN":"逻辑：小前提","definition":"in a syllogism, the premise that contains the subject of the conclusion","definitionCN":"在三段论中，包含结论主项的那个前提","example":"The minor premise says that Socrates is a man.","exampleCN":"小前提说苏格拉底是人。","why":"A syllogism has a greater and a lesser premise. The one carrying the subject is the lesser member of the pair, so it inherited the name minor.","whyCN":"三段论有一个大前提和一个小前提。承载主项的那一个是这对命题中较小的一员，于是继承了 minor 这个名字。"},{"no":"08","title":"Academic: a secondary subject","titleCN":"学业：辅修科目","definition":"a subject studied at university in addition to the main subject, with fewer credits","definitionCN":"在大学里除主修之外学习的科目，所需学分较少","example":"She chose history as her minor.","exampleCN":"她选择了历史作为辅修。","why":"The degree has a major and a minor: the second subject carries less weight in the total. It is the academic version of the lighter pan.","whyCN":"学位有一个主修和一个辅修：第二门科目在总量里分量更轻。它就是天平上较轻那一端的学业版本。"},{"no":"09","title":"A person below legal age","titleCN":"未成年人（名词）","definition":"a person who has not reached the age at which the law grants full adult rights","definitionCN":"尚未达到法律授予完整成年人权利的年龄的人","example":"The club is not allowed to sell alcohol to minors.","exampleCN":"这家俱乐部不得向未成年人售酒。","why":"The adjective became a noun by leaving out the person: 'a minor person' shortened to 'a minor'. Legal writing uses it as a stable category.","whyCN":"形容词省略了所修饰的人，变成了名词：“一个未成年的人”缩成“一个未成年人”。法律文本把它用作固定类别。"}],"etymology":{"intro":{"en":"Minor is a Latin comparative borrowed whole, first through the Franciscans and then in general use. Its relation to parvus is grammatical rather than root-based, and that point is disputed in the sources.","cn":"minor 是整体借入的拉丁语比较级，先经方济各会进入英语，再进入一般用法。它与 parvus 的关系是语法性的而非词根性的，这一点在资料中存在争议。"},"items":[{"era":"EARLY 13C.","en":"First recorded in English in frere menour 'Franciscan friar', literally 'minor friar', from Latin minor. The order's founder chose Fratres Minores, 'lesser brethren', for humility.","cn":"英语中最早记录于 13 世纪早期，出现在 frere menour“方济各会修士”中，字面是“较小的修士”，来自拉丁语 minor。该会创始人选用 Fratres Minores“小兄弟会”，是出于谦卑。"},{"era":"LATIN","en":"Latin minor meant 'less, lesser, smaller, junior', figuratively 'inferior, less important'. It was formed as the masculine/feminine of minus on the mistaken assumption that minus was a neuter comparative. Latin grammars traditionally pair parvus 'small' with minor and minimus, but the roots differ: minor belongs to *mei-, while parvus has a separate origin, itself not fully settled. The pairing is suppletive, grammatical rather than etymological, and its root relation is disputed.","cn":"拉丁语 minor 意为“更少、更小、更年幼”，引申为“较低、较不重要”。它是把 minus 误当作中性比较级之后，按阳性／阴性形式造出来的。拉丁语法传统把 parvus“小”与 minor、minimus 配成一组比较级和最高级，但两者词根不同：minor 属于 *mei-，parvus 另有来源，其自身来源也未完全定论。这种配对是异根补充式，属于语法配对而非词源配对，其词根关联存在争议。"},{"era":"PIE","en":"The family goes back to PIE *mei- (2) 'small', the root also behind minus, minimum, diminish, minute and minuscule.","cn":"这个词族可追溯到原始印欧语 *mei-（第二支）“小”，该词根也是 minus、minimum、diminish、minute、minuscule 的来源。"},{"era":"15C. · 1570S","en":"The general adjectival sense 'lesser or smaller than the other' is recorded from early 15c.; 'underage' is recorded from the 1570s.","cn":"一般形容词义“比另一个更小、更次要”于 15 世纪早期有记录；“未成年的”义于 16 世纪 70 年代有记录。"},{"era":"1610S · 1690S","en":"From the 1610s the noun means 'a person below legal age'. The musical sense dates from the 1690s, for intervals and keys built on a minor third; chords follow by 1797.","cn":"名词从 17 世纪 10 年代起表示“未达法定年龄的人”。音乐义始于 17 世纪 90 年代，指以小三度构成的音程与调；和弦用法到 1797 年才出现。"},{"era":"1884 · 1890 · 1905","en":"Minor league is recorded from 1884, with the figurative extension by 1926. The academic minor is from 1890, and the verb 'to minor in' from 1905.","cn":"minor league 于 1884 年有记录，其比喻用法到 1926 年出现。学业上的“辅修”始于 1890 年，动词用法“辅修”始于 1905 年。"}]},"similar":{"note":{"en":"The first group separates the sound-alike miner, the derived noun minority and the superlative neighbour minimum. The second group compares minor with small, lesser, its opposite major, and slight.","cn":"第一组区分同音的 miner、派生名词 minority 和最高级邻词 minimum；第二组把 minor 与 small、lesser、它的反义 major 以及 slight 作比较。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"miner","ipa":"/ˈmaɪnə(r)/","tag":"same sound","definition":"a person who works in a mine. It sounds almost the same as minor but comes from mine, a different root.","definitionCN":"在矿里工作的人。它与 minor 读音几乎相同，却来自 mine 这条不同的词根。"},{"word":"minority","ipa":"/maɪˈnɒrəti/","tag":"derived noun","definition":"a smaller group, or the state of being under legal age. It is the noun built on minor, not a separate root word.","definitionCN":"少数群体，或未成年状态。它是建立在 minor 之上的名词，不是另一个词根词。"},{"word":"minimum","ipa":"/ˈmɪnɪməm/","tag":"superlative neighbour","definition":"the smallest amount possible. It comes from minimus, the superlative that sits above minor on the same Latin scale.","definitionCN":"可能的最小量。它来自 minimus，即同一把拉丁尺子上高于 minor 的最高级。"},{"word":"minor key","ipa":"/ˈmaɪnə kiː/","tag":"compound","definition":"a musical key built on a minor third. It is a fixed compound using the adjective, not a separate root word or a legal term.","definitionCN":"以小三级构成的小调。它是使用这个形容词的固定复合词，不是另一个词根词，也不是法律用语。"}]},{"heading":"NEAR MEANING","entries":[{"word":"small","ipa":"/smɔːl/","tag":"plain size","definition":"little in size or amount. It is a plain description with no comparison built in, while minor always implies a partner it is measured against.","definitionCN":"尺寸或数量小。它是没有内置比较的平实描述，而 minor 总暗示着一个被拿来对照的伙伴。"},{"word":"lesser","ipa":"/ˈlesə(r)/","tag":"formal comparative","definition":"smaller in importance or degree. It is a formal comparative close to minor, but it cannot mean 'underage' or name a musical key.","definitionCN":"在重要性或程度上更小。它是接近 minor 的正式比较级，但不能表示“未成年”，也不能指音乐调性。"},{"word":"major","ipa":"/ˈmeɪdʒə(r)/","tag":"direct opposite","definition":"greater or more important. It is the direct opposite of minor in rank, in music, in sport and in academic study.","definitionCN":"更大的；更重要的。它在等级、音乐、体育和学业上都是 minor 的直接对立面。"},{"word":"slight","ipa":"/slaɪt/","tag":"degree","definition":"small in degree and often unimportant. It overlaps minor in the 'not serious' sense, but cannot carry the ranking or legal senses.","definitionCN":"程度小，常不重要。它在“不严重”这一义项上与 minor 重叠，却不能承载等级或法律义。"}]}]},"mnemonics":{"normalIntro":{"en":"Real grammar and real relatives: minor is already a Latin comparative, major is its opposite, minority and minimum share the same smallness root.","cn":"只用真实语法与真实同族词：minor 本身就是拉丁比较级，major 是它的反面，minority 与 minimum 共享同一条“小”的词根。"},"normal":[{"en":"Minor is already a comparative in Latin, 'smaller'. English does not add -er to it, so there is no 'minorer'.","cn":"minor 在拉丁语里已经是比较级“更小的”。英语不再给它加 -er，所以不存在“minorer”这种形式。"},{"en":"Major and minor are a pair: Latin maior and minor, both comparatives, one from magnus and one from the *mei- family.","cn":"major 与 minor 是一对：拉丁语 maior 与 minor 都是比较级，一个出自 magnus，一个出自 *mei- 词族。"},{"en":"Minor key: the third is shorter than the major third, so the interval itself is literally minor.","cn":"小调：它的三度比大三度短，所以这个音程本身就是“较小的”。"},{"en":"A college minor is the smaller half of a double subject: fewer credits than the major.","cn":"大学的辅修是双主修里较小的那一半：学分比主修少。"},{"en":"Minor league teams sit below the major league; the word keeps the same 'lesser' ranking.","cn":"小联盟球队坐在大联盟下面一级；这个词保留着同一个“次一等”的排名含义。"}],"abstract":[{"en":"Picture a balance with two pans. Minor is not the pan that is empty; it is the pan that is lighter than the one opposite it.","cn":"想象一架有两只盘的天平。minor 不是空着的那只盘，而是比对面那只更轻的盘。"},{"en":"Minor does not mean tiny. It means smaller than the thing it is compared with, so a minor injury can still hurt.","cn":"minor 不等于“极小”。它表示比对照物更小，所以轻伤也仍然会疼。"},{"en":"The same ranking word moves between size, importance, age and music: in each case something sits one step below its partner.","cn":"同一个表示排位的词在尺寸、重要性、年龄和音乐之间移动：每一种情形里，都有某物比它的伙伴低一级。"}]},"examples":[{"en":"The road was closed after a minor collision.","cn":"一起小碰撞之后，这条路被封了。"},{"en":"She majored in biology with a minor in statistics.","cn":"她主修生物学，辅修统计学。"},{"en":"The film's minor characters are more memorable than its hero.","cn":"这部电影的次要角色比主角更令人难忘。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“买呢”——买呢子大衣时只剩小一号的，只好买了那件小号的 → minor 较小的、次要的","word":"minor"},"root":"源自拉丁语 minor“更小的、更少的、更年幼的”，是 minus 一系的比较级，核心是“同一对里较轻的那一端”。","sensesIntro":{"en":"Nine senses of minor, all from one position: the lighter pan of a balance, the member of a pair that is smaller, lower, younger, or less important than its partner.","cn":"minor 的九个义项都来自同一个位置：天平上较轻的那只盘，也就是一对事物中比伙伴更小、更低、更年幼或更不重要的那一个。"},"semanticMap":{"core":{"en":"CORE IMAGE: the lighter pan of a balance, always weighed against a heavier partner.","cn":"核心意象：天平上较轻的那只盘，永远与更重的伙伴一起被衡量。"},"chain":["THE LIGHTER PAN","THE SMALLER OF TWO","BELOW THE MAJOR","UNDER LEGAL AGE","A SHORTER THIRD","THE SECONDARY CHOICE"],"branches":[{"senses":"S1 · S3","en":"SIZE AND DEGREE: the shorter of two paired things, or a degree too small to count as serious.","cn":"尺寸与程度：一对事物中较短的那一个，或小到不算严重的程度。"},{"senses":"S2 · S6","en":"RANK: a lesser role in a negotiation, and the leagues that sit below the major ones.","cn":"等级：谈判中较次要的角色，以及坐在大联盟下面一级的联赛。"},{"senses":"S4 · S9","en":"AGE: the adjective and the noun both mark a person below the legal line of full adult rights.","cn":"年龄：形容词与名词都标记处于完整成年权利线以下的人。"},{"senses":"S5","en":"MUSIC: a third shorter than the major third gives the minor key its name.","cn":"音乐：比大三度短的三度，给了小调这个名字。"},{"senses":"S7 · S8","en":"FORMAL SUBSYSTEMS: the minor premise and the secondary subject are each the lesser member of a pair.","cn":"形式化的子系统：小前提与辅修科目，各自都是一对中的较小成员。"}]},"affixes":{"intro":{"en":"Minor is not built with an English affix; it is a Latin comparative borrowed whole. Its family grows through -ity, through compounds such as minor league and minor key, and through the related *mei- root.","cn":"minor 不是用英语词缀构成的，而是整体借入的拉丁比较级。它的词族通过 -ity、通过 minor league 与 minor key 这类复合词，以及通过相关的 *mei- 词根扩展。"},"latinIntro":{"en":"Latin minor, minus and minimus belong to one scale: minor 'smaller', minus 'less', minimus 'smallest'. Parvus 'small' is traditionally paired with them in grammar, but it is a different root, so the relation is suppletive rather than derivational.","cn":"拉丁语 minor、minus、minimus 属于同一把尺子：minor“更小”、minus“更少”、minimus“最小”。parvus“小”在语法传统上与它们配成一组，但它是另一条词根，因此这是异根补充关系，而不是派生关系。"},"items":[{"word":"minor","structure":"Latin minor, comparative of the *mei- family","meaning":"smaller, lesser, junior","meaningCN":"更小的；较次要的；较年幼的（拉丁语比较级）","example":"The minor road joins the highway two miles north.","exampleCN":"那条小路在往北两英里处接入高速公路。"},{"word":"minority","structure":"minor + -ity (noun of state)","meaning":"a smaller group; the state of being under age","meaningCN":"少数群体；未成年状态（-ity 构成状态名词）","example":"The proposal was supported by only a small minority.","exampleCN":"这项提案只得到一小部分人的支持。"},{"word":"minor league","structure":"minor + league (compound noun)","meaning":"a sports league below the top professional level","meaningCN":"低于顶级职业水平的体育联赛（复合名词）","example":"He played five years in the minor leagues.","exampleCN":"他在小联盟打了五年。"},{"word":"minor key","structure":"minor + key (compound noun)","meaning":"a musical key built on a minor third","meaningCN":"以小三级构成的小调（复合名词）","example":"The scene is scored in a slow minor key.","exampleCN":"这一幕配的是缓慢的小调。"},{"word":"minimum","structure":"minim- + -um (neuter superlative ending)","meaning":"the smallest amount","meaningCN":"最小量；最低限度（minimus 的中性形式）","example":"Keep the temperature at a minimum of ten degrees.","exampleCN":"把温度保持在至少十度。"},{"word":"minimize","structure":"minimum + -ize (verb)","meaning":"to reduce to the smallest amount","meaningCN":"使最小化；把……降到最低（-ize 构成动词）","example":"The new route minimizes travel time.","exampleCN":"新路线把行程时间减到最少。"},{"word":"minus","structure":"Latin minus, neuter of minor","meaning":"less; the subtraction sign; a drawback","meaningCN":"减去；负号；不利因素（minor 的中性形式）","example":"The plan has one clear minus: it is expensive.","exampleCN":"这个方案有一个明显的短板：它很贵。"},{"word":"diminish","structure":"di- (away) + minuere (to lessen)","meaning":"to make or become smaller","meaningCN":"减少；削弱（di- 离开 + minuere 减少）","example":"Interest in the case diminished over the years.","exampleCN":"这些年，人们对这桩案子的兴趣减弱了。"},{"word":"minute","structure":"Latin minutus 'small', from minuere","meaning":"extremely small (as an adjective)","meaningCN":"极小的（作形容词，来自拉丁语 minutus“小的”）","example":"The differences between the two samples are minute.","exampleCN":"两个样本之间的差异极其微小。"},{"word":"minister","structure":"Latin minister 'servant, attendant', from minus","meaning":"a person who serves in a government or church","meaningCN":"部长；大臣；牧师（拉丁语 minister“仆人”，源自 minus）","example":"The foreign minister signed the agreement.","exampleCN":"外交部长签署了这项协议。"}],"latinEntries":[{"word":"minor","structure":"Latin comparative, from PIE *mei- 'small'","meaning":"smaller, lesser, junior","meaningCN":"更小的；较少的；较年幼的"},{"word":"minus","structure":"neuter of minor, used as a noun and preposition","meaning":"less; a smaller amount","meaningCN":"更少；较小的量"},{"word":"minimus","structure":"superlative of minor","meaning":"smallest, least","meaningCN":"最小的；最少的"}]}},{"word":"mode","ipa_uk":"/məʊd/","ipa_us":"/moʊd/","definition_zh":"方式；模式；交通方式；生产方式；时尚；调式；语气；众数","definition_en":"a way in which something is done, operates, or exists; also a prevailing fashion, a musical scale, a grammatical mood, or the most frequent value in a set","core_image":"一把尺子量出恰好的一段，再照这个尺寸去做","scene":"The transport plan lists four modes — metro, bus, bicycle and walking — and asks which one the city can afford.","sceneCN":"这里 mode 是「交通方式」（第 3 个义项：交通方式）；句意：这份交通规划列出四种方式——地铁、公交、自行车和步行——并追问这座城市负担得起哪一种。场景要点：一张摊开的城市交通图、四条并排的路线、被圈出的预算数字。","pos":[{"tag":"n.","zh":"方式；模式；样式；调式；语气；众数"}],"collocations":[{"phrase":"mode of transport","zh":"交通方式"},{"phrase":"mode of production","zh":"生产方式"},{"phrase":"mode of operation","zh":"运作方式；工作模式"},{"phrase":"mode of communication","zh":"交流方式"},{"phrase":"the latest mode","zh":"最新款式；当下风尚"},{"phrase":"switch mode","zh":"切换模式"},{"phrase":"survival mode","zh":"求生模式；应急状态"}],"forms":[{"label":"名词复数","form":"modes"}],"derivatives":[{"word":"modal","pos":"adj.","zh":"形式的；模态的；语气的"},{"word":"modality","pos":"n.","zh":"形式；模态；感觉通道"},{"word":"multimodal","pos":"adj.","zh":"多模态的；多种方式的"},{"word":"modish","pos":"adj.","zh":"时髦的；流行的"},{"word":"outmoded","pos":"adj.","zh":"过时的；老式的"}],"senses":[{"no":"01","title":"A way of doing","titleCN":"行事方式","definition":"the particular way in which someone does something or something happens","definitionCN":"某人做某事或某事发生的特定方式","example":"Her mode of working is to write everything by hand before typing it.","exampleCN":"她的工作方式是先把一切手写下来，再打字。","why":"Latin modus is a measure. A way of doing something is the measure the action is cut to, so the word begins as the shape given to an activity rather than its purpose.","whyCN":"拉丁语 modus 是“尺度”。做某事的方式，就是动作被裁成的尺寸，因此这个词的起点是给一项活动定形，而不是给它定目的。"},{"no":"02","title":"A machine setting","titleCN":"设备的运行模式","definition":"one of the fixed settings in which a machine or system can operate","definitionCN":"机器或系统可以运行的固定设置之一","example":"At ten the alarm switches itself into night mode.","exampleCN":"到了十点，警报器会自动切换到夜间模式。","why":"A machine repeats the same operations, and each setting is a measure it can be set to. The word moves from human ways of acting to the repeatable ways a device acts.","whyCN":"机器重复同样的操作，每一种设置都是它可以被调到的某个尺度。这个词从人的行事方式，转到设备可重复的运行方式。"},{"no":"03","title":"A way to travel","titleCN":"交通方式","definition":"a particular means or system of moving people or goods, such as rail, road, air, or water","definitionCN":"运送人或货物的特定手段或系统，如铁路、公路、航空或水运","example":"Rail is still the cheapest mode of transport for coal.","exampleCN":"对煤炭来说，铁路仍是最便宜的运输方式。","why":"Transport is measured out by the vehicle and the route chosen. The fixed phrase 'mode of transport' treats each means of travel as one measured option among several.","whyCN":"运输由所选的交通工具与路线量定。固定短语“mode of transport”把每一种出行手段都当作若干被量定的选项之一。"},{"no":"04","title":"A way of producing","titleCN":"生产方式","definition":"the organized way in which a society or economy makes goods, especially in economic and historical writing","definitionCN":"社会或经济制造商品的有机组织方式，尤用于经济与历史写作","example":"The factory changed the mode of production from batch work to a moving line.","exampleCN":"这家工厂把生产方式从分批作业改成了流水线。","why":"Economics borrowed the measure for the whole arrangement of work: tools, labour, and ownership fitted together into one measured pattern of making things.","whyCN":"经济学借用了这个“尺度”，用来指整个劳动安排：工具、劳动力与所有权被合成一个被量定的制造格局。"},{"no":"05","title":"The prevailing fashion","titleCN":"时尚、流行款式","definition":"the current fashion or style, especially in dress, in somewhat formal or old-fashioned use","definitionCN":"当下的风尚或款式，尤指服饰，语气较正式或略显旧式","example":"Narrow coats were the mode in the winter of that year.","exampleCN":"那年冬天，窄身大衣正是风尚。","why":"French mode means fashion, a specialized use of the same word. Fashion is the measure everyone agrees to wear for a season, so the sense of 'current style' grows straight out of 'measure'.","whyCN":"法语 mode 意为“时尚”，是同一个词的专门用法。时尚就是大家在一季里共同同意穿着的尺度，所以“当下款式”这一义项直接从“尺度”长出来。"},{"no":"06","title":"A musical mode","titleCN":"音乐调式","definition":"a pattern of intervals used to organize a melody, especially one of the ancient or church modes","definitionCN":"用来组织旋律的音程模式，尤指古代调式或教会调式","example":"The second movement is built on an old church mode rather than a major key.","exampleCN":"第二乐章建立在古老的教会调式上，而不是大调上。","why":"Latin modus also meant rhythm and song. Musicians divide the octave by a measured pattern, and that pattern of intervals is literally the measure of the melody.","whyCN":"拉丁语 modus 也指节奏与歌曲。音乐家按一种被量定的模式划分八度，这种音程模式字面上就是旋律的尺度。"},{"no":"07","title":"A grammatical mood","titleCN":"语法语气","definition":"the form of a verb that shows whether it states, commands, wishes, or supposes","definitionCN":"动词的形式，表明它是在陈述、命令、祝愿还是假设","example":"In Latin the verb's mode tells whether it states a fact or gives an order.","exampleCN":"在拉丁语中，动词的语气表明它是在陈述事实还是下达命令。","why":"Grammar borrowed the word for the form that measures the speaker's attitude toward the action. Late Latin used modus for this category, and English kept it beside the more common 'mood'.","whyCN":"语法学借用了这个词，指量定说话人对动作态度的形式。晚期拉丁语用 modus 指这一范畴，英语把它与更常见的 mood 并留着。"},{"no":"08","title":"The statistical mode","titleCN":"统计学的众数","definition":"in statistics, the value that occurs most frequently in a set of data","definitionCN":"统计学中在一组数据里出现次数最多的值","example":"In this data set the mode is 4, because 4 appears more often than any other value.","exampleCN":"在这组数据中，众数是 4，因为 4 出现的次数比其他任何值都多。","why":"Statistics keeps the old sense of measure but points it at frequency: the mode is the value where the data pile up, the measure at which the set is most itself.","whyCN":"统计学保留了这个词古老的“尺度”义，却把它指向频次：众数是数据堆积之处，是这组数据最像自己的那个尺度。"},{"no":"09","title":"A whole way of being","titleCN":"整体的存在方式","definition":"a general state or manner of existence, as in 'survival mode' or 'a mode of life'","definitionCN":"总体的存在状态或生活方式，如“survival mode”或“a mode of life”","example":"During the storm the crew went into survival mode and stopped all repairs.","exampleCN":"暴风雨期间，船员进入求生模式，停止了所有修理。","why":"The measure can be applied to a whole life, not just one action. A mode of being is the overall pattern a person or group is currently cut to.","whyCN":"这个尺度可以被用在整整一种生活上，而不只是一个动作。存在方式，就是一个人或群体当下被裁成的总体格局。"}],"etymology":{"intro":{"en":"Mode comes from Latin modus 'measure' through French, and the same measure runs through music, grammar, fashion, economics, and statistics. Its look-alike mood is a different word. Dates are approximate.","cn":"mode 经法语来自拉丁语 modus“尺度”，同一把尺子贯穿音乐、语法、时尚、经济与统计。与它形近的 mood 是另一个词。年代为大致估计。"},"items":[{"era":"LATE 14c.","en":"Mode is first recorded in English meaning 'melodies, strains of music', a sense now obsolete. It came from Old French mode and directly from Latin modus.","cn":"mode 在英语中最早记录为“旋律、乐曲”，这一义项今已废弃。它来自古法语 mode，并直接来自拉丁语 modus。"},{"era":"LATIN modus","en":"Latin modus meant 'measure, extent, quantity; proper measure, rhythm, song; a way, manner, fashion, style', and in Late Latin also 'mood' in grammar and logic.","cn":"拉丁语 modus 意为“尺度、范围、数量；恰当的尺度、节奏、歌曲；方式、做法、样式、风格”，在晚期拉丁语中还指语法与逻辑中的“语气”。"},{"era":"PIE *med-","en":"Modus goes back to PIE *med- 'take appropriate measures'. The same root lies behind moderate, modest, modify, model, modern, and medicine.","cn":"modus 可追溯到原始印欧语 *med-“采取恰当的尺度”。同一词根也是 moderate、modest、modify、model、modern、medicine 的来源。"},{"era":"1640s / 1660s","en":"A second French borrowing gives mode the sense 'current fashion, prevailing style' (1640s). The central sense 'manner of acting or doing, the way in which a thing is done' is recorded by the 1660s.","cn":"另一次法语借入使 mode 获得“当下时尚、流行款式”之义（17 世纪 40 年代）。核心义“行事方式、做一件事的方式”到 17 世纪 60 年代才有记录。"},{"era":"MID-15c. / 1670s","en":"The grammatical sense 'inflectional category in conjugation' is mid-15c. In music, mode is recorded from the 1670s for the Greek method of dividing the octave, and by 1721 for modern music.","cn":"语法义“变位中的屈折范畴”出现于 15 世纪中叶。音乐中，mode 于 17 世纪 70 年代指希腊人划分八度的方法，到 1721 年指现代音乐中的调式。"},{"era":"MODERN / NOT MOOD","en":"Mood 'state of mind' (c. 1300) comes from Old English mod 'heart, frame of mind', a word of unknown origin, and has no etymological link with mode. Grammatical mood (1570s) is a different word again: it is an alteration of mode.","cn":"mood“心境”（约 1300）来自古英语 mod“心、心境”，词源不明，与 mode 没有词源关系。语法上的 mood（16 世纪 70 年代）又是另一个词：它是 mode 的变体拼写。"}]},"similar":{"note":{"en":"The first group separates mode from the look-alikes built on the same or a neighbouring stem; the second compares the ordinary words for 'the way something is done'.","cn":"第一组把 mode 与同词干或邻近词干的形近词分开；第二组比较表示“做事的方式”的常用词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mood","ipa":"/muːd/","tag":"state of mind, not from modus","definition":"a temporary state of mind or feeling. It comes from Old English mod, not from Latin modus. Only the grammatical mood is a different word, an alteration of mode.","definitionCN":"暂时的心境或情绪。它来自古英语 mod，而不是拉丁语 modus。只有语法上的 mood 是另一个词，即 mode 的变体。"},{"word":"model","ipa":"/ˈmɒdl/","tag":"small measure, a pattern","definition":"a small representation or an example to copy. It goes back to Latin modellus, a diminutive of modus, so it is 'a little measure' rather than a way of acting.","definitionCN":"小型的代表物或供模仿的范例。它可追溯到拉丁语 modellus，即 modus 的指小形式，所以它是“一个小小的尺度”，而不是行事方式。"},{"word":"modal","ipa":"/ˈməʊdl/","tag":"adjective of mode","definition":"relating to mode, especially in grammar, music, or logic. It is the adjective; mode is the noun.","definitionCN":"与 mode 有关的，尤用于语法、音乐或逻辑。它是形容词，mode 是名词。"},{"word":"modish","ipa":"/ˈməʊdɪʃ/","tag":"fashionable","definition":"fashionable, often with a hint of contempt. It is built from mode in its 'fashion' sense plus -ish.","definitionCN":"时髦的，常带一丝轻蔑。它由表示“时尚”的 mode 加 -ish 构成。"}]},{"heading":"NEAR MEANING","entries":[{"word":"method","ipa":"/ˈmeθəd/","tag":"organized procedure","definition":"a planned and organized procedure for doing something, often teachable step by step. A mode is the shape of the doing; a method is the route with steps.","definitionCN":"为做某事而计划的、有组织的程序，通常可以一步步传授。mode 是做法呈现的形态，method 是带步骤的路线。"},{"word":"manner","ipa":"/ˈmænə/","tag":"style of doing","definition":"the way in which something is done, often with attention to style or bearing. It is close to mode but more personal and less technical.","definitionCN":"做某事的方式，常带有风格或举止的意味。它接近 mode，但更个人化，技术性更弱。"},{"word":"way","ipa":"/weɪ/","tag":"general word","definition":"the most general word for how something is done. It can replace mode in most everyday sentences, though not in fixed terms such as mode of production.","definitionCN":"表示“如何做”的最通用词。它在多数日常句子里可以替换 mode，但不能替换 mode of production 这类固定说法。"},{"word":"fashion","ipa":"/ˈfæʃn/","tag":"style and prevailing custom","definition":"a prevailing custom or style, and also 'in the manner of'. It overlaps with mode in the sense 'current style', but mode is far more formal there.","definitionCN":"流行风俗或款式，也可表示“以……的方式”。它在“当下款式”一义上与 mode 重叠，但 mode 在该义上正式得多。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Latin modus 'measure', the PIE root *med-, and the English family modal, modality, model, and modify.","cn":"只用真实成分与真实同族词：拉丁语 modus“尺度”、原始印欧语词根 *med-，以及英语词族 modal、modality、model、modify。"},"normal":[{"en":"modus is Latin for 'measure'. A mode is the measure an action is cut to, which is why the word covers ways, settings, and styles at once.","cn":"modus 是拉丁语的“尺度”。mode 就是一个动作被裁成的尺寸，所以这个词同时覆盖方式、设置与款式。"},{"en":"The fixed phrases keep the measure visible: mode of transport, mode of production, mode of operation.","cn":"固定短语把“尺度”保留在明面上：交通方式、生产方式、运作方式。"},{"en":"mood 'state of mind' is not related: it comes from Old English mod. Only grammatical mood is a variant of mode.","cn":"mood“心境”与它无关：它来自古英语 mod。只有语法上的 mood 才是 mode 的变体。"},{"en":"model is a 'little measure' (Latin modellus), a pattern to copy, not a way of doing.","cn":"model 是“小小的尺度”（拉丁语 modellus），指供模仿的范本，而不是行事方式。"},{"en":"modal, modality, and multimodal all keep the noun's stem; they describe the form or the channel, not the fashion.","cn":"modal、modality、multimodal 都保留了这个名词的词干；它们描述形式或通道，而不指时尚。"}],"abstract":[{"en":"Picture a tailor's ruler laid on cloth. The ruler does not decide what the cloth is for; it only fixes the shape. Mode is that ruler applied to an action.","cn":"想象一把裁缝尺压在布上。尺子不决定布用来做什么，只固定形状。mode 就是那把量在动作上的尺子。"},{"en":"A switch with several positions is a row of modes: each position is a stable measure the machine can return to.","cn":"一个有多个挡位的开关就是一排模式：每个挡位都是机器可以回到的稳定尺度。"},{"en":"Fashion is a measure everyone agrees to wear for a season; that is why the same word can mean 'way' and 'style'.","cn":"时尚就是大家在一季里共同同意穿着的尺度；正因如此，同一个词既能指“方式”，又能指“款式”。"}]},"examples":[{"en":"The city's buses and trains are two modes of the same public transport system.","cn":"城市的公交与地铁是同一套公共交通系统里的两种方式。"},{"en":"Please leave the phone in silent mode during the examination.","cn":"考试期间请把手机留在静音模式。"},{"en":"The historian argues that a new mode of production changed the family as well as the factory.","cn":"这位历史学家主张，新的生产方式不仅改变了工厂，也改变了家庭。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“摸的”——先摸清门道，量好尺寸再动手，什么东西就按什么方式做 → mode 方式、模式（只借音，不表词源）","word":"mode"},"root":"源自拉丁语 modus“尺度、方式”，核心是“按一把量好的尺子去做，形成固定的做法”。","sensesIntro":{"en":"Nine senses of mode, all cut from one measure: a ruler that fixes the shape of an action, a machine setting, a melody, a verb form, or a whole way of life.","cn":"mode 的九个义项都从同一把尺子上裁下：它固定一个动作、一个设备设置、一段旋律、一种动词形式或一整种生活形态。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ruler laid on something to fix its shape.","cn":"核心意象：一把尺子压在事物上，固定它的形状。"},"chain":["A MEASURE","A SHAPE GIVEN","A REPEATABLE SETTING","A CHOSEN MEANS","A PREVAILING STYLE","A FORM OF BEING"],"branches":[{"senses":"S1 · S2","en":"MEASURE APPLIED: a human action takes a shape, and a machine takes a repeatable setting.","cn":"尺度落下：人的动作被定形，机器被调到一个可重复的设置。"},{"senses":"S3 · S4","en":"ORGANIZED MEANS: transport and production each settle into a measured arrangement of vehicles, tools, and labour.","cn":"有组织的手段：运输与生产各自固定成由车辆、工具与劳动组成的被量定安排。"},{"senses":"S5 · S6","en":"STYLE AND SONG: the measure becomes the fashion of a season and the interval pattern of a melody.","cn":"款式与歌曲：这把尺子变成一季的时尚，也变成旋律的音程模式。"},{"senses":"S7","en":"GRAMMAR: the verb's form is the measure of the speaker's attitude.","cn":"语法：动词的形式成为说话人态度的尺度。"},{"senses":"S8 · S9","en":"DATA AND LIFE: the mode is where data pile up, and a mode of life is the whole pattern a person is cut to.","cn":"数据与生活：众数是数据堆积之处，而生活方式是一个人被裁成的整体格局。"}]},"affixes":{"intro":{"en":"Mode is a Latin noun, and mod- is one of the most productive stems in English: -al, -ality, -ish, -ern, -el, -ule, -ify and multi- all attach to it.","cn":"mode 是拉丁语名词，mod- 是英语里最能产出的词干之一：-al、-ality、-ish、-ern、-el、-ule、-ify 与 multi- 都能接在它上面。"},"latinIntro":{"en":"The Latin base is modus 'measure', with diminutives modulus and modellus and the verb moderari 'keep within measure'. All of them keep the idea of a fixed proportion.","cn":"拉丁语词基是 modus“尺度”，另有指小形式 modulus 与 modellus，以及动词 moderari“保持在尺度之内”。它们都保留“固定比例”的意思。"},"items":[{"word":"mode","structure":"Latin modus 'measure, manner'","meaning":"a way or pattern","meaningCN":"方式；模式（拉丁语“尺度、方式”）","example":"The app has a simple mode for beginners.","exampleCN":"这个应用为初学者设有一个简单模式。"},{"word":"modal","structure":"mod- (measure) + -al (adjective)","meaning":"relating to mode, mood, or form","meaningCN":"模态的；语气的（mod- 尺度 + -al 形容词后缀）","example":"The grammar lesson covers modal verbs such as 'can' and 'must'.","exampleCN":"这堂语法课讲 can、must 这类情态动词。"},{"word":"modality","structure":"modal + -ity (noun)","meaning":"a mode or channel of something","meaningCN":"模态；形式；感觉通道（-ity 构成名词）","example":"The study compares visual and auditory modalities.","exampleCN":"这项研究比较视觉与听觉通道。"},{"word":"multimodal","structure":"multi- (many) + modal","meaning":"using several modes at once","meaningCN":"多模态的（multi- 多 + modal 模态的）","example":"The course uses a multimodal approach with text, sound, and images.","exampleCN":"这门课采用文字、声音与图像的多模态方法。"},{"word":"modish","structure":"mode (fashion) + -ish (adjective)","meaning":"fashionable","meaningCN":"时髦的（mode 时尚 + -ish 形容词后缀）","example":"The room was furnished in a modish style that dated quickly.","exampleCN":"这个房间按一种很快过时的时髦风格布置。"},{"word":"outmoded","structure":"out- (beyond) + mode + -ed","meaning":"no longer in fashion or use","meaningCN":"过时的（out- 超出 + mode 款式 + -ed）","example":"The factory still runs on outmoded equipment.","exampleCN":"这家工厂仍在用过时的设备运转。"},{"word":"model","structure":"mod- (measure) + -el (diminutive)","meaning":"a small pattern or representation","meaningCN":"模型；范本（mod- 尺度 + -el 指小后缀）","example":"They built a scale model of the bridge.","exampleCN":"他们制作了这座桥的比例模型。"},{"word":"modern","structure":"mod- (measure, just now) + -ern (adjective)","meaning":"of the present time","meaningCN":"现代的（-ern 构成形容词）","example":"Modern offices rarely keep paper files.","exampleCN":"现代办公室很少保存纸质档案。"},{"word":"moderate","structure":"moder- (measure) + -ate (adjective/verb)","meaning":"kept within due measure","meaningCN":"适度的；使缓和（保持在应有尺度内）","example":"The region has a moderate climate.","exampleCN":"这个地区气候温和。"},{"word":"modify","structure":"mod- (measure) + -ify (make)","meaning":"to change in measure or detail","meaningCN":"修改；调整（按尺度去改）","example":"The engineers modified the valve to reduce flow.","exampleCN":"工程师改动了阀门以减少流量。"},{"word":"module","structure":"mod- (measure) + -ule (diminutive)","meaning":"a small measured unit","meaningCN":"模块；单元（mod- 尺度 + -ule 指小后缀）","example":"The software is built from reusable modules.","exampleCN":"这个软件由可复用的模块构成。"},{"word":"modulate","structure":"modul- (small measure) + -ate (verb)","meaning":"to adjust in measure, tone, or strength","meaningCN":"调节；调制（按小尺度调整）","example":"She modulated her voice so as not to wake the baby.","exampleCN":"她压低并调节了声音，以免吵醒婴儿。"}],"latinEntries":[{"word":"modus","structure":"PIE *med- 'take appropriate measures'","meaning":"measure, manner, style","meaningCN":"尺度；方式；样式"},{"word":"modellus","structure":"modus + -ellus (diminutive)","meaning":"a small measure, a pattern","meaningCN":"小尺度；范本（modus 的指小形式）"},{"word":"moderari","structure":"modus + verbal stem","meaning":"to keep within measure, restrain","meaningCN":"保持在尺度之内；节制"}]}},{"word":"modify","ipa_uk":"/ˈmɒdɪfaɪ/","ipa_us":"/ˈmɑːdɪfaɪ/","definition_zh":"修改；调整；修饰；缓和；修订；改性","definition_en":"to change something in some details or qualities without replacing it entirely, often to make it fit a new purpose or to make it less extreme","core_image":"在一件旧物上按尺寸修整几处，整体仍然是原来那件东西","scene":"The engineer did not replace the whole valve; she chose to modify one flange so that it would fit the new pipe.","sceneCN":"这里 modify 是「部分修改」（第 1 个义项：改动局部而不整体替换）；句意：工程师没有换掉整个阀门，只改动了一个法兰盘，让它能接上新管道。场景要点：一台拆开的旧阀门、一只被换掉的零件、旁边保留完好的阀体。","pos":[{"tag":"vt.","zh":"修改；调整；修饰；缓和；修订"}],"collocations":[{"phrase":"modify a plan","zh":"修改计划"},{"phrase":"modify behavior","zh":"调整行为"},{"phrase":"modify the design","zh":"改动设计"},{"phrase":"genetically modified","zh":"转基因的；经过遗传改造的"},{"phrase":"modify the terms","zh":"修改条款"},{"phrase":"modify a file","zh":"修改文件"},{"phrase":"modify a noun","zh":"修饰名词"}],"forms":[{"label":"三单（he/she/it）","form":"modifies"},{"label":"过去式（已经发生）","form":"modified"},{"label":"过去分词（完成／被动）","form":"modified"},{"label":"现在分词（进行体）","form":"modifying"}],"derivatives":[{"word":"modification","pos":"n.","zh":"修改；改动；改良"},{"word":"modifier","pos":"n.","zh":"修饰语；修改者"},{"word":"modified","pos":"adj.","zh":"修改过的；改良的"},{"word":"unmodified","pos":"adj.","zh":"未修改的；保持原样的"},{"word":"modifiable","pos":"adj.","zh":"可修改的；可调整的"}],"senses":[{"no":"01","title":"Change a part, not the whole","titleCN":"改局部，不换整体","definition":"to change some details, parts, or qualities of something while leaving its identity and main structure intact","definitionCN":"改动某物的部分细节、部件或性质，同时保留它的身份与主要结构","example":"The engineer modified the valve instead of replacing the whole assembly.","exampleCN":"工程师改动了阀门，而不是更换整个组件。","why":"Latin modificare joined modus 'measure' to facere 'make': to make according to a measure. The word starts from adjusting a thing's proportions, not from destroying and remaking it.","whyCN":"拉丁语 modificare 把 modus“尺度”与 facere“做”合在一起：按尺度去制作。这个词的起点是调整一件东西的比例，而不是毁掉重造。"},{"no":"02","title":"Adapt to fit a new use","titleCN":"为适应新用途而调整","definition":"to adjust something so that it suits a different purpose, condition, or user","definitionCN":"调整某物，使其适合不同的目的、条件或使用者","example":"The school modified its timetable to fit the bus schedule.","exampleCN":"学校调整了课程表，以配合公交时刻。","why":"A measure is taken against a purpose. When the purpose changes, the thing is re-measured and trimmed until it fits again, which is why modify often appears with 'to fit' or 'for'.","whyCN":"尺度总是对着某个目的量。目的变了，东西就被重新量一遍、修一遍，直到重新合身，所以 modify 常与“适应”“为了”一类说法连用。"},{"no":"03","title":"Grammar: a word limits another","titleCN":"语法：一个词限定另一个词","definition":"of a word or phrase, to limit or qualify the meaning of another word","definitionCN":"指一个词或短语限定或说明另一个词的意义","example":"In 'a red door', the adjective modifies the noun 'door'.","exampleCN":"在 a red door 中，形容词修饰名词 door。","why":"Grammar borrowed the word for narrowing a meaning. An adjective places a measure on a noun, saying which part of its range is meant, without replacing the noun.","whyCN":"语法学借这个词来表示收窄意义。形容词给名词加上一个尺度，说明指的是它范围里的哪一部分，而不替换这个名词。"},{"no":"04","title":"Soften a claim or tone","titleCN":"缓和语气、限定说法","definition":"to make a statement, demand, or tone less absolute or less severe","definitionCN":"使陈述、要求或语气不那么绝对、不那么严厉","example":"He modified his tone when he saw that the child was listening.","exampleCN":"看到孩子在听，他把语气缓和了下来。","why":"To keep within measure also means not to exceed it. A demand that is modified has been brought back inside reasonable bounds, so the word can mean 'soften' rather than 'change'.","whyCN":"保持在尺度之内，也意味着不越过尺度。被 modify 的要求被拉回到合理的范围内，所以这个词可以表示“缓和”，而不只是“改变”。"},{"no":"05","title":"Amend a legal text","titleCN":"修订法律或合同文本","definition":"to make a formal, limited change to a law, contract, or official document","definitionCN":"对法律、合同或正式文件作有限度的正式改动","example":"The council modified the payment clause but left the rest of the contract untouched.","exampleCN":"理事会修改了付款条款，但合同其余部分未动。","why":"A legal document is changed clause by clause, never rewritten wholesale if it can be helped. Modify is the natural verb for a bounded edit that leaves the instrument in force.","whyCN":"法律文件是一条款一条款地改，不到万不得已不会整份重写。modify 正是表示这种有限改动、让文件继续有效的动词。"},{"no":"06","title":"Change a setting or file","titleCN":"改动设置或文件","definition":"in computing, to change the contents, settings, or code of a file or system","definitionCN":"在计算机领域，改动文件或系统的内容、设置或代码","example":"Do not modify the system files without a backup.","exampleCN":"没有备份时不要修改系统文件。","why":"Software is a structure with many settable measures. Editing one setting or one line modifies the system: the rest keeps running, which is exactly the partial-change picture.","whyCN":"软件是一个有许多可调尺度的结构。改一项设置或一行代码就是 modify 系统：其余部分照旧运行，这正是“局部改动”的画面。"},{"no":"07","title":"Rewrite a gene","titleCN":"改造基因","definition":"in biology, to change an organism's genetic material, often to give it a new trait","definitionCN":"在生物学中，改变生物体的遗传物质，常为赋予它新的性状","example":"The scientists modified one gene in the rice plant to resist drought.","exampleCN":"科学家改动了水稻的一个基因，使其抗旱。","why":"The organism is not replaced; one instruction inside it is re-measured and rewritten. The phrase 'genetically modified' keeps the sense of a targeted edit to an existing living thing.","whyCN":"生物体本身没有被替换，被改写的是它内部的一条指令。“genetically modified”这一说法保留了“对既有生物做定点改动”的意思。"},{"no":"08","title":"Alter a material's surface","titleCN":"改变材料的表面性能","definition":"in materials science, to change the properties of a surface or structure without changing its bulk","definitionCN":"在材料科学中，改变表面或结构的性能，而不改变其主体","example":"The coating modifies the surface without changing the bulk of the metal.","exampleCN":"这层涂层改变了金属的表面性能，却没有改变其主体。","why":"Here the measure is applied only to the skin of the object. The bulk stays as it was, which makes modify the right verb for a treatment rather than a replacement.","whyCN":"这里的尺度只施加在物体的表皮上。主体保持原样，因此 modify 适合表示一种处理，而不是替换。"},{"no":"09","title":"A sound changed by its neighbour","titleCN":"语音受邻音影响而变化","definition":"in phonetics, of a sound, to be changed under the influence of a neighbouring sound","definitionCN":"在语音学中，指一个音受相邻音影响而发生改变","example":"In rapid speech, the final sound is often modified by the sound that follows it.","exampleCN":"在快速语流中，末尾的音常被后面的音改变。","why":"A sound keeps its identity but shifts its shape to fit its neighbours, just as a part is trimmed to fit a new pipe. The word's 'fit' sense is at work even here.","whyCN":"一个音保留自己的身份，却改变形状去适应相邻的音，正如一个零件被修整以接上新管道。即便在这里，这个词“适配”的意思仍在起作用。"}],"etymology":{"intro":{"en":"Modify entered English from Old French in the late fourteenth century and goes back to Latin modificare, literally 'to make by measure'. Its two Latin parts, modus and facere, explain why it means partial adjustment rather than total replacement. Dates are approximate.","cn":"modify 在 14 世纪晚期从古法语进入英语，可追溯到拉丁语 modificare，字面意为“按尺度制作”。它的两个拉丁成分 modus 与 facere，解释了它为何表示局部调整而不是整体替换。年代为大致估计。"},"items":[{"era":"LATE 14c.","en":"First recorded as modifien, 'alter, amend, adjust, change the properties, form, or function of'. It also meant 'set limits, keep within the bounds of reason; choose a middle course'.","cn":"最早记录为 modifien，意为“改变、修正、调整、改变……的性质、形式或功能”。它还有“设定界限、保持在理性范围之内、选择中间道路”的意思。"},{"era":"OLD FRENCH","en":"The English verb came through Old French modifier (14c.), which already carried the sense of altering something to fit.","cn":"这个英语动词经古法语 modifier（14 世纪）而来，后者已经带有“改动某物使其适配”的意思。"},{"era":"LATIN modificare","en":"Latin modificare meant 'to limit, measure off, restrain'. It joined modus 'measure, manner' with the combining form of facere 'to make'.","cn":"拉丁语 modificare 意为“限定、量出、约束”。它把 modus“尺度、方式”与 facere“制作”的结合形式合在一起。"},{"era":"TWO ROOTS","en":"Modus goes back to PIE *med- 'take appropriate measures', the root behind mode, moderate, and modest. Facere goes back to PIE *dhe- 'to set, put', the root behind do and deed.","cn":"modus 可追溯到原始印欧语 *med-“采取恰当的尺度”，也是 mode、moderate、modest 的词根。facere 可追溯到原始印欧语 *dhe-“放置、安放”，也是 do 与 deed 的词根。"},{"era":"c. 1500 / 1580s","en":"Modification is recorded c. 1500 in philosophy, 'determination by a mode or quality'. Modifier appears in the 1580s as 'one who or that which modifies'; its grammatical sense is from 1865. The 'result of a variation' sense of modification is from the 1660s, and 'act of altering' from 1774.","cn":"modification 约 1500 年出现在哲学中，意为“由某种模式或性质所决定”。modifier 于 16 世纪 80 年代出现，指“修改者或修改之物”；其语法义始于 1865 年。modification 的“变化结果”义始于 17 世纪 60 年代，“改变的行为”义始于 1774 年。"},{"era":"MODERN / KIN","en":"Moderate comes from Latin moderari 'keep within measure', the same *med- root but a different branch. Adjust comes from Old French ajouster, from Late Latin adjuxtare 'bring near'. Alter comes from Latin alter 'the other of two'. Each changes something in a different direction or degree.","cn":"moderate 来自拉丁语 moderari“保持在尺度之内”，同出 *med- 词根，但属于另一分支。adjust 来自古法语 ajouster，源于晚期拉丁语 adjuxtare“使靠近”。alter 来自拉丁语 alter“两者中的另一个”。它们各自以不同方向或不同程度改变事物。"}]},"similar":{"note":{"en":"The first group separates the noun, the agent, and the two participles built on modify; the second compares verbs of change that learners too often use as exact synonyms.","cn":"第一组把由 modify 构成的名词、施动者与两个分词分开；第二组比较学习者常当作完全同义词的几个“改变”动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"modification","ipa":"/ˌmɒdɪfɪˈkeɪʃn/","tag":"noun of result or act","definition":"a change made to something, or the act of changing it. It names the change or the process, while modify names the doing.","definitionCN":"对某物所作的改动，或改动这一行为。它命名改动或过程，而 modify 命名动作本身。"},{"word":"modifier","ipa":"/ˈmɒdɪfaɪə/","tag":"agent or grammatical word","definition":"one who or that which modifies; in grammar, a word that limits another word. It is the doer or the tool, not the act.","definitionCN":"修改者或修改之物；语法中指限定另一词的词。它是施动者或工具，不是动作。"},{"word":"modified","ipa":"/ˈmɒdɪfaɪd/","tag":"past participle and adjective","definition":"changed in some parts, as in 'genetically modified' or 'a modified version'. It describes the result, not the process.","definitionCN":"局部被改动的，如“转基因的”或“修改过的版本”。它描述结果，而不是过程。"},{"word":"unmodified","ipa":"/ˌʌnˈmɒdɪfaɪd/","tag":"negated participle","definition":"not changed at all. The un- prefix marks the absence of exactly the partial edit that modify performs.","definitionCN":"完全未被改动的。un- 前缀标记的正是 modify 所做的那种局部改动的缺席。"}]},{"heading":"NEAR MEANING","entries":[{"word":"adjust","ipa":"/əˈdʒʌst/","tag":"bring into fit","definition":"to change something slightly so that it fits, works, or looks right. It stresses fitting a standard or a position, while modify can also mean changing a design or a rule.","definitionCN":"轻微改变某物，使其合适、正常或位置正确。它强调对准某个标准或位置，而 modify 还可指改动设计或规则。"},{"word":"alter","ipa":"/ˈɔːltə/","tag":"make different","definition":"to make something different, often in a way that changes its character or appearance. It is broader and can suggest a deeper change than modify.","definitionCN":"使某物不同，常指改变其性质或外观。它范围更广，也可能暗示比 modify 更深的改变。"},{"word":"amend","ipa":"/əˈmend/","tag":"formal correction","definition":"to change a text, law, or agreement in order to correct or improve it. It is mostly formal and textual, whereas modify also covers objects and behaviour.","definitionCN":"为纠正或改进而改动文本、法律或协议。它多用于正式文本，而 modify 也覆盖物件与行为。"},{"word":"moderate","ipa":"/ˈmɒdəreɪt/","tag":"reduce intensity","definition":"to make something less extreme or less intense, or to preside over a discussion. It shares the 'measure' root but works mainly on strength, not on form.","definitionCN":"使某物不那么极端或强烈，或主持讨论。它与 modify 共享“尺度”词根，但主要作用于强度，而不是形式。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Latin modus 'measure' plus facere 'make', and the English family modification, modifier, mode, and moderate.","cn":"只用真实成分与真实同族词：拉丁语 modus“尺度”加 facere“制作”，以及英语词族 modification、modifier、mode、moderate。"},"normal":[{"en":"modus is 'measure' and -ify comes from facere 'make'. To modify is to make according to a measure, which is why the thing keeps its identity.","cn":"modus 是“尺度”，-ify 来自 facere“制作”。modify 就是按尺度去制作，所以被改的东西保留自己的身份。"},{"en":"The Latin verb also meant 'set limits, keep within bounds', so modifying a demand can mean softening it rather than changing its content.","cn":"这个拉丁动词还意为“设定界限、保持在范围之内”，所以修改一项要求可以是把它放缓，而不是改变内容。"},{"en":"modification is the change or the act; modifier is the person or word that does it; modified is the result.","cn":"modification 是改动或改动行为；modifier 是做这件事的人或词；modified 是结果。"},{"en":"mode, moderate, modest and modify all share *med- 'take appropriate measures', but only modify adds the 'make' part.","cn":"mode、moderate、modest、modify 都共享 *med-“采取恰当尺度”，但只有 modify 加了“制作”这一部分。"},{"en":"In grammar the word narrows meaning: an adjective modifies a noun without replacing it, the same partial-change picture.","cn":"在语法里这个词收窄意义：形容词修饰名词而不替换它，仍是那幅“局部改动”的画面。"}],"abstract":[{"en":"Picture a craftsman with a ruler beside an old chair. He shaves one leg, keeps the frame, and the chair is still the same chair.","cn":"想象一位工匠把尺子放在一把旧椅子旁。他刨短一条腿，保留框架，椅子仍是同一把椅子。"},{"en":"Modify is a dial, not a switch: it turns the value a little, while replace would swap the whole unit out.","cn":"modify 是一个旋钮，不是开关：它把数值稍微转动一点，而 replace 会把整个部件换掉。"},{"en":"Every modified thing still answers to its old name; if it no longer does, it was not modified but replaced.","cn":"每一件被 modify 的东西仍回应它原来的名字；如果它不再回应，那它不是被修改，而是被替换了。"}]},"examples":[{"en":"We modified the proposal after the first round of comments.","cn":"第一轮意见之后，我们修改了提案。"},{"en":"The app lets you modify the layout without changing the underlying data.","cn":"这个应用允许你修改布局，而不改动底层数据。"},{"en":"Some crops were modified to grow in salt water, but the yield remains low.","cn":"有些作物被改造为能在咸水中生长，但产量仍然很低。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“摸得改”——先摸清原有尺寸，再动手改那几处，整体不换 → modify 修改、调整（只借音，不表词源）","word":"modify"},"root":"源自拉丁语 modificare“按尺度制作”，由 modus“尺度”加 facere“制作”构成，核心是“按尺寸修整局部，而不整体替换”。","sensesIntro":{"en":"Nine senses of modify, all from one gesture: a measure is laid on an existing thing and a few parts are trimmed, while the thing itself remains what it was.","cn":"modify 的九个义项都来自同一个动作：把尺子放在既有之物上，修整其中几处，而物件本身仍是原来的物件。"},"semanticMap":{"core":{"en":"CORE IMAGE: a few parts trimmed to measure, the whole left standing.","cn":"核心意象：按尺寸修整几处，整体仍然立着。"},"chain":["A MEASURE TAKEN","A PART TOUCHED","THE SHAPE ADJUSTED","THE PURPOSE FITTED","THE WORD LIMITED","THE WHOLE STILL ITSELF"],"branches":[{"senses":"S1 · S2","en":"PARTIAL CHANGE: details or parts are re-measured, either to improve the thing or to fit a new use.","cn":"局部改变：细节或部件被重新量过，或为改良物件，或为适配新用途。"},{"senses":"S3","en":"GRAMMAR: a word places a measure on another word and narrows its meaning without replacing it.","cn":"语法：一个词给另一个词加上尺度，收窄它的意义，而不替换它。"},{"senses":"S4 · S5","en":"BOUNDS AND TEXT: a tone or demand is brought back inside measure, and a legal clause is edited while the document stays in force.","cn":"尺度与文本：语气或要求被拉回尺度之内，法律条款被改动而文件继续有效。"},{"senses":"S6 · S7","en":"SYSTEMS AND GENES: one setting, one line of code, or one gene is changed while the rest keeps running.","cn":"系统与基因：一项设置、一行代码或一个基因被改动，其余部分照旧运行。"},{"senses":"S8 · S9","en":"SURFACE AND SOUND: only the skin of a material, or the shape of a sound, is adjusted to fit its surroundings.","cn":"表面与语音：只调整材料的表皮或一个音的形状，使其适应周围环境。"}]},"affixes":{"intro":{"en":"Modify is a Latin verb whose English shape joins mod- 'measure' to -ify 'make'. The same stem, with -ation, -er, -ed, -able and un-, produces the rest of the family.","cn":"modify 是拉丁语动词，其英语形态把 mod-“尺度”与 -ify“制作”合在一起。同一词干加上 -ation、-er、-ed、-able 与 un-，构成其余词族。"},"latinIntro":{"en":"Latin modificare combined modus 'measure' and facere 'make'. Facere also gives -fic-, -fect, and -fy in English, which is why modify, manufacture, and effect all contain a 'making' piece.","cn":"拉丁语 modificare 把 modus“尺度”与 facere“制作”合起来。facere 在英语里还给出 -fic-、-fect 与 -fy，所以 modify、manufacture、effect 都含有一个“制作”的成分。"},"items":[{"word":"modify","structure":"mod- (measure) + -ify (make)","meaning":"to make according to measure; to change in part","meaningCN":"按尺度制作；局部改变（mod- 尺度 + -ify 使……）","example":"They modified the engine to burn less fuel.","exampleCN":"他们改动了发动机，使其更省油。"},{"word":"modification","structure":"modific- + -ation (noun of action)","meaning":"a change, or the act of changing","meaningCN":"修改；改动（-ation 构成行为名词）","example":"The design needs only a small modification.","exampleCN":"这个设计只需要做一处小改动。"},{"word":"modifier","structure":"modify + -er (agent)","meaning":"one who modifies; a grammatical qualifier","meaningCN":"修改者；修饰语（-er 表施动者）","example":"In the phrase 'very cold', 'very' is a modifier.","exampleCN":"在 very cold 这一短语中，very 是修饰语。"},{"word":"modified","structure":"modify + -ed (past participle)","meaning":"changed in part","meaningCN":"被局部改动的（-ed 构成过去分词）","example":"The modified version runs faster.","exampleCN":"修改后的版本运行得更快。"},{"word":"unmodified","structure":"un- (not) + modified","meaning":"not changed at all","meaningCN":"未修改的（un- 否定 + modified）","example":"The control group used unmodified seed.","exampleCN":"对照组使用的是未经改造的种子。"},{"word":"modifiable","structure":"modify + -able (capable)","meaning":"able to be changed","meaningCN":"可修改的（-able 表能力）","example":"The settings are modifiable by the user.","exampleCN":"这些设置可由用户修改。"},{"word":"mod","structure":"shortening of modification","meaning":"a user-made change to a game","meaningCN":"模组；游戏修改版（modification 的截短）","example":"He installed a mod that adds new maps.","exampleCN":"他安装了一个增加新地图的模组。"},{"word":"mode","structure":"Latin modus 'measure'","meaning":"a way or pattern","meaningCN":"方式；模式（同出 modus）","example":"The device has a low-power mode.","exampleCN":"这个设备有一个低功耗模式。"},{"word":"moderate","structure":"moder- (measure) + -ate","meaning":"kept within measure; to reduce intensity","meaningCN":"适度的；使缓和（保持在尺度内）","example":"She moderated her criticism in public.","exampleCN":"她在公开场合缓和了自己的批评。"},{"word":"modus operandi","structure":"Latin modus (manner) + operandi (of working)","meaning":"a person's usual way of working","meaningCN":"一贯做法；做事方式（拉丁语“工作的方式”）","example":"The thief's modus operandi was always the same.","exampleCN":"这个窃贼的作案手法始终如一。"},{"word":"commodify","structure":"com- (together) + mod- (measure) + -ify","meaning":"to treat something as a commodity","meaningCN":"使商品化（com- 共同 + mod- 尺度 + -ify 使……）","example":"Critics say the festival has commodified local music.","exampleCN":"批评者说这个节日把本地音乐商品化了。"}],"latinEntries":[{"word":"modificare","structure":"modus (measure) + facere (make)","meaning":"to limit, measure off, restrain","meaningCN":"限定；量出；约束（modus 尺度 + facere 制作）"},{"word":"modus","structure":"PIE *med- 'take appropriate measures'","meaning":"measure, manner","meaningCN":"尺度；方式"},{"word":"facere","structure":"PIE *dhe- 'to set, put'","meaning":"to make, do","meaningCN":"制作；做"}]}},{"word":"monitor","ipa_uk":"/ˈmɒnɪtə/","ipa_us":"/ˈmɑːnɪtər/","definition_zh":"显示器；监测仪；班长；监督者；监测；监控；监听","definition_en":"a device that displays or records information, a person who warns or keeps order, or to watch and check something continuously over time","core_image":"一个站在旁边不断提醒“注意”的人，眼睛一直盯着同一处","scene":"From the control room the engineer watched the monitor that showed the pressure inside the pipeline.","sceneCN":"这里 monitor 是「显示器」（第 1 个义项：显示画面或数据的屏幕）；句意：工程师在控制室里盯着显示管道内压力的显示器。场景要点：昏暗的控制室、一排亮着的屏幕、屏幕上跳动的压力曲线、管道剖面图。","pos":[{"tag":"n.","zh":"显示器；监测仪；班长；监督者；告诫者"},{"tag":"v.","zh":"监测；监控；监听；跟踪观察"}],"collocations":[{"phrase":"heart monitor","zh":"心脏监测仪"},{"phrase":"computer monitor","zh":"电脑显示器"},{"phrase":"monitor progress","zh":"跟踪进展"},{"phrase":"monitor a patient","zh":"监测病人情况"},{"phrase":"monitor the situation","zh":"监视局势"},{"phrase":"closely monitor","zh":"密切监测"},{"phrase":"UN monitors","zh":"联合国观察员"}],"forms":[{"label":"三单（he/she/it）","form":"monitors"},{"label":"过去式（已经发生）","form":"monitored"},{"label":"过去分词（完成／被动）","form":"monitored"},{"label":"现在分词（进行体）","form":"monitoring"},{"label":"名词复数","form":"monitors"}],"derivatives":[{"word":"monitoring","pos":"n.","zh":"监测；监控"},{"word":"monitory","pos":"adj.","zh":"告诫的；警告的"},{"word":"monitorial","pos":"adj.","zh":"级长的；监督的"},{"word":"monitorship","pos":"n.","zh":"监督职务；级长职位"}],"senses":[{"no":"01","title":"A screen that shows the picture","titleCN":"显示画面的屏幕","definition":"a screen, especially a computer or television display, that shows information or a picture","definitionCN":"显示信息或画面的屏幕，尤指电脑或电视显示屏","example":"The second monitor shows the camera feed from the front door.","exampleCN":"第二块显示器显示前门的摄像头画面。","why":"Broadcasting used a monitor for a device that continuously checked a transmission, and the screen showing that check took the name. A computer display repeats the role: it lets someone keep watch on what the machine is doing.","whyCN":"广播业曾把持续检查传输质量的设备称为 monitor，显示这项检查的屏幕便沿用了这个名字。电脑显示器重复着同一角色：让人持续看清机器在做什么。"},{"no":"02","title":"An instrument that keeps watch","titleCN":"持续监测的仪器","definition":"a device that continuously measures and displays a physical condition, such as heart rate or pressure","definitionCN":"持续测量并显示某项身体或物理状况的设备，如心率或压力","example":"The heart monitor began to beep faster and faster.","exampleCN":"心脏监测仪开始越响越快地鸣叫。","why":"The Latin monitor was a person who warned. An instrument that watches a pulse and sounds an alarm takes over the warning job, so the person's title passes to the machine.","whyCN":"拉丁语 monitor 是一个发出警告的人。一台盯着脉搏、并发出警报的仪器接过了这份警告的职责，于是人的称呼转移到了机器上。"},{"no":"03","title":"The pupil who keeps order","titleCN":"维持秩序的班长、级长","definition":"a senior pupil at a school given the task of keeping order or checking attendance","definitionCN":"学校里被赋予维持秩序或检查出勤任务的高年级学生","example":"The hall monitor checked the corridors every hour.","exampleCN":"走廊值日生每小时巡查一次走廊。","why":"This is the oldest English sense, from 1540s: a senior pupil 'charged with keeping order'. The student does exactly what the Latin word says — reminds others of the rules and reports breaches.","whyCN":"这是英语里最古老的义项，始于 16 世纪 40 年代：受命维持秩序的高年级学生。这个学生做的正是拉丁词所说的——提醒别人守规矩，并报告违规。"},{"no":"04","title":"An official who warns","titleCN":"提出告诫的监督者","definition":"a person appointed to observe, advise, and warn, especially in an official or technical role","definitionCN":"受指派观察、建议并提出告诫的人，尤指担任正式或技术职务者","example":"A monitor was appointed to warn the committee about conflicts of interest.","exampleCN":"委员会任命了一名监督员，就利益冲突提出告诫。","why":"Latin monitor meant 'one who reminds, admonishes, or checks', and also 'an overseer, instructor, guide'. The English noun keeps that advisory, warning figure before it ever names a machine.","whyCN":"拉丁语 monitor 意为“提醒者、告诫者、检查者”，也指“监督者、指导者、引路人”。英语名词先保留了这个提出建议与警告的人，之后才用它命名机器。"},{"no":"05","title":"Watch the numbers over time","titleCN":"持续监测数据","definition":"to measure and check a quantity or condition regularly over a period of time","definitionCN":"在一段时间内定期测量并检查某个数量或状况","example":"Sensors monitor the temperature of the tank every ten minutes.","exampleCN":"传感器每十分钟监测一次储罐的温度。","why":"The verb appeared in 1924 for checking the quality of radio signals. Its core is repetition: a monitor does not look once but keeps looking, so the verb means sustained checking rather than a single glance.","whyCN":"动词于 1924 年出现，指检查无线电信号的质量。它的核心是重复：monitor 不是看一眼，而是持续地看，所以这个动词表示持续的检查，而不是一瞥。"},{"no":"06","title":"Keep someone under surveillance","titleCN":"对人的监控","definition":"to watch a person, group, or activity closely, especially to detect wrongdoing or risk","definitionCN":"密切注视某人、某群体或某项活动，尤为了发现不当行为或风险","example":"The company monitors its drivers' speed and braking through an app.","exampleCN":"公司通过一个应用监控司机的车速与刹车情况。","why":"When the watching is turned from a gauge to people, the warning role becomes surveillance. The same continuous attention is now aimed at behaviour that may need correcting.","whyCN":"当注视的对象从仪表转向人，提醒的职责就变成了监控。同样的持续关注，现在对准了可能需要纠正的行为。"},{"no":"07","title":"Listen to a channel","titleCN":"监听信号或频道","definition":"to listen to a radio, telephone, or other channel continuously in order to catch particular information","definitionCN":"持续收听无线电、电话或其他频道，以捕捉特定信息","example":"They monitored the radio channel all night, waiting for a reply.","exampleCN":"他们整夜监听那个无线电频道，等待回复。","why":"The earliest verb sense was exactly this: checking radio signals for quality. Listening to a channel is watching with the ears, and the word's continuity remains.","whyCN":"最早的动词义正是这个：检查无线电信号的质量。用耳朵听一个频道就是“用耳朵看”，而这个词的持续性仍然保留。"},{"no":"08","title":"The lizard that warns","titleCN":"会“预警”的巨蜥","definition":"a large lizard of the family Varanidae, called a monitor because of an old story that it warned people of crocodiles","definitionCN":"巨蜥科的大型蜥蜴，因古老传说称它会向人预警鳄鱼而得名","example":"A monitor lizard crossed the trail and disappeared into the grass.","exampleCN":"一只巨蜥穿过小径，消失在草丛里。","why":"The name was given in 1826 because the lizard was fabled to give warning of Nile crocodiles. It is the same 'warner' sense, applied to an animal rather than a person or device.","whyCN":"这个名字始于 1826 年，因为传说这种蜥蜴会预警尼罗河鳄鱼。它仍是“警告者”这层意思，只是用在了动物身上，而不是人或设备。"},{"no":"09","title":"The ironclad that admonished","titleCN":"作为警告的铁甲舰","definition":"the name of the first ironclad warship of that design, built in 1862 and intended as a warning to the Confederacy","definitionCN":"1862 年建造的第一艘该型铁甲舰的名称，意在向南方邦联发出警告","example":"The Monitor fought the Merrimack in 1862 and changed naval warfare.","exampleCN":"1862 年，莫尼特号与梅里马克号交战，改变了海战方式。","why":"The inventor chose the name because the ship was meant to 'admonish' Confederate leaders. The Latin warner becomes a floating threat, a warning made of iron.","whyCN":"发明者选择这个名字，是因为这艘船意在“告诫”南方邦联的领导人。拉丁语的告诫者变成了浮在水上的威胁，一个用铁铸成的警告。"},{"no":"10","title":"A background watcher in software","titleCN":"软件中的后台监控程序","definition":"in computing, a program or process that runs in the background and checks system activity","definitionCN":"在计算机领域，指在后台运行、检查系统活动的程序或进程","example":"A background monitor logs every login and flags unusual hours.","exampleCN":"一个后台监控程序记录每次登录，并标记异常时段。","why":"Software repeats the human watchman: it runs unnoticed, checks continuously, and reports what looks wrong. The old 'one who warns' is now a loop of code.","whyCN":"软件重复着人类更夫的角色：它不声不响地运行，持续检查，并报告看起来不对的地方。古老的“告诫者”如今成了一段循环的代码。"}],"etymology":{"intro":{"en":"Monitor began as a Latin word for a person who warns, entered English in the sixteenth century as a school officer, and only in the nineteenth and twentieth centuries became a machine, a lizard, a warship, and finally a screen. Dates are approximate.","cn":"monitor 最初是拉丁语中表示“告诫者”的词，16 世纪作为学校职务进入英语，直到 19 与 20 世纪才变成仪器、蜥蜴、军舰，最后成为屏幕。年代为大致估计。"},"items":[{"era":"1540s","en":"First recorded in English as 'senior pupil at a school charged with keeping order'. It came from Latin monitor.","cn":"英语最早记录为“受命维持秩序的学校高年级学生”。它来自拉丁语 monitor。"},{"era":"LATIN monitor","en":"Latin monitor meant 'one who reminds, admonishes, or checks', and also 'an overseer, instructor, guide, teacher'. It was an agent noun from monere.","cn":"拉丁语 monitor 意为“提醒者、告诫者、检查者”，也指“监督者、指导者、引路人、教师”。它是 monere 的施动名词。"},{"era":"monere / PIE *men-","en":"Monere meant 'to remind, bring to one's recollection, tell of; admonish, advise, warn, instruct, teach'. It goes back to PIE *moneie-, a causative form of *men- 'to think', the root also behind Latin memini 'I remember' and mens 'mind'.","cn":"monere 意为“提醒、使想起、告知；告诫、建议、警告、指导、教导”。它可追溯到原始印欧语 *moneie-，即 *men-“思考”的使役形式；同一词根也是拉丁语 memini“我记得”与 mens“心智”的来源。"},{"era":"1826 / 1862","en":"The monitor lizard was so called because it was fabled to warn people of Nile crocodiles (1826). The ironclad warship Monitor (1862) was named by its inventor because it was meant to 'admonish' Confederate leaders.","cn":"巨蜥被称为 monitor，是因为传说它会向人预警尼罗河鳄鱼（1826）。铁甲舰莫尼特号（1862）由发明者命名，因为这艘船意在“告诫”南方邦联的领导人。"},{"era":"1924 / 1944","en":"The verb is recorded in 1924 meaning 'to check for quality', originally of radio signals. The general sense 'observe, keep under review' is from 1944. Keats had used it in 1818 to mean 'to guide'.","cn":"动词于 1924 年有记录，意为“检查质量”，最初用于无线电信号。泛指“观察、持续审视”的义项始于 1944 年。济慈在 1818 年曾用它表示“引导”。"},{"era":"1931 / MODERN","en":"A broadcasting sense, 'a device to continuously check on the technical quality of a transmission', is recorded from 1931 and led to the sense 'a TV screen displaying the picture from a particular camera'. The computer display is a later extension of that screen sense.","cn":"广播义“持续检查传输技术质量的设备”记录于 1931 年，并由此引出“显示某一摄像机画面的电视屏幕”这一义项。电脑显示器是该屏幕义的后期引申。"}]},"similar":{"note":{"en":"The first group separates the noun and adjective forms built on monitor from two related warning words; the second compares the verbs of watching that learners use interchangeably.","cn":"第一组把由 monitor 构成的名词与形容词形式，同两个相关的“警告”词分开；第二组比较学习者常互换使用的几个“看管”动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"monitoring","ipa":"/ˈmɒnɪtərɪŋ/","tag":"noun of process","definition":"the continuous act of checking or watching something. It is the process, while monitor is the device or the verb.","definitionCN":"持续检查或观察的行为。它是过程，而 monitor 是设备或动词。"},{"word":"monitory","ipa":"/ˈmɒnɪtəri/","tag":"adjective: warning","definition":"giving or serving as a warning. It keeps the Latin sense of admonition and is mostly formal.","definitionCN":"给予警告的，或起警告作用的。它保留了拉丁语“告诫”的意思，多用于正式语境。"},{"word":"admonish","ipa":"/əˈmɒnɪʃ/","tag":"verb: warn or reprimand","definition":"to warn or reprimand someone firmly but not harshly. It shares the Latin monere root but is a separate verb, not a form of monitor.","definitionCN":"坚定但不严厉地警告或责备某人。它与 monitor 共享拉丁语 monere 词根，但它是另一个动词，不是 monitor 的词形。"},{"word":"premonition","ipa":"/ˌpriːməˈnɪʃn/","tag":"noun: forewarning","definition":"a feeling that something is about to happen, especially something bad. It is a warning that comes before the event, built with pre- 'before'.","definitionCN":"一种某事即将发生、尤指坏事的感觉。它是事件之前到来的警告，由 pre-“在前”构成。"}]},{"heading":"NEAR MEANING","entries":[{"word":"supervise","ipa":"/ˈsuːpəvaɪz/","tag":"oversee people or work","definition":"to be in charge of people or work and make sure it is done properly. It stresses authority over workers, while monitor stresses continuous checking of signals or conditions.","definitionCN":"负责管理人或工作，确保事情做好。它强调对工作者的权威，而 monitor 强调对信号或状况的持续检查。"},{"word":"watch","ipa":"/wɒtʃ/","tag":"look at over time","definition":"to look at something for a period of time, often without measuring it. Monitor usually adds a purpose: to detect change, risk, or poor quality.","definitionCN":"在一段时间内看着某物，通常不进行测量。monitor 通常多一层目的：发现变化、风险或质量问题。"},{"word":"track","ipa":"/træk/","tag":"follow a path or progress","definition":"to follow the movement or development of something over time, often by recorded traces. It focuses on where something goes; monitor focuses on whether it stays within limits.","definitionCN":"随时间跟踪某物的移动或发展，常依据记录下来的痕迹。它关注东西去了哪里，monitor 关注它是否仍在限度之内。"},{"word":"screen","ipa":"/skriːn/","tag":"test and filter","definition":"to examine people, substances, or signals in order to sort or filter them. It is usually a test applied at a point in time, while monitor is a watch kept over time.","definitionCN":"检查人、物质或信号，以便分类或筛选。它通常是在某一时点施行的检验，而 monitor 是长期保持的观察。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Latin monere 'warn', the agent noun monitor, and the English family monitoring, monitory, admonish, and premonition.","cn":"只用真实成分与真实同族词：拉丁语 monere“警告”、施动名词 monitor，以及英语词族 monitoring、monitory、admonish、premonition。"},"normal":[{"en":"monere means 'to warn, remind'. A monitor is literally 'one who warns' — first a pupil, then an instrument, then a screen.","cn":"monere 意为“警告、提醒”。monitor 字面上就是“发出警告的人”——先是学生，再是仪器，最后是屏幕。"},{"en":"The school sense is the oldest English one (1540s); the machine and screen senses are centuries later.","cn":"学校职务义是英语里最古老的义项（16 世纪 40 年代）；仪器与屏幕义要晚好几个世纪。"},{"en":"The verb arrived in 1924 for checking radio signal quality, which is why 'monitor a channel' still sounds natural.","cn":"动词于 1924 年出现，用于检查无线电信号质量，所以 monitor a channel 至今听起来自然。"},{"en":"monitoring is the process, monitory is 'warning', admonish is a separate verb from the same root.","cn":"monitoring 是过程，monitory 是“警告的”，admonish 则是同根的另一动词。"},{"en":"A monitor differs from a supervisor: it keeps checking a signal or condition, while a supervisor holds authority over people.","cn":"monitor 与 supervisor 不同：它持续检查信号或状况，而 supervisor 对人拥有管理权。"}],"abstract":[{"en":"Picture a night watchman at a factory gate. He does not repair anything; he looks, checks, and raises the alarm.","cn":"想象一名守在工厂大门的更夫。他不修理任何东西；他看、检查、发出警报。"},{"en":"Move that watchman into a box on the wall, and he becomes a heart monitor; put his gaze on a screen, and he becomes a display.","cn":"把这位更夫装进墙上的盒子，他就成了心脏监测仪；把他的目光放到屏幕上，他就成了显示器。"},{"en":"The word always means attention spread over time: a single look is not monitoring, however careful it is.","cn":"这个词始终表示铺在时间上的注意：只看一眼，无论多仔细，都不算监测。"}]},"examples":[{"en":"Nurses monitor the patient's pulse and blood pressure every hour.","cn":"护士每小时监测病人的脉搏与血压。"},{"en":"The app monitors how much time you spend on each website.","cn":"这个应用监控你在每个网站上花多少时间。"},{"en":"The teacher left a monitor in charge of the class while she fetched the keys.","cn":"老师去取钥匙时，让班长负责管班。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“莫离他”——莫要离开他，他一直在旁边盯着、随时提醒你 → monitor 监视器；监测（只借音，不表词源）","word":"monitor"},"root":"源自拉丁语 monere“警告、提醒”的施动名词 monitor“告诫者”，核心是“持续盯着并随时发出提醒”。","sensesIntro":{"en":"Ten senses of monitor, all held together by one figure: someone standing beside a thing, watching without stopping and speaking up when something is wrong.","cn":"monitor 的十个义项都由同一个形象串起：有人站在某物旁边，不停地看，一有不对就出声提醒。"},"semanticMap":{"core":{"en":"CORE IMAGE: a warner standing beside, eyes fixed on one spot.","cn":"核心意象：一个站在旁边、目光钉在一处的告诫者。"},"chain":["ONE WHO WARNS","ONE WHO KEEPS ORDER","ONE WHO CHECKS","A DEVICE THAT CHECKS","A SCREEN THAT SHOWS","A WATCH KEPT OVER TIME"],"branches":[{"senses":"S1 · S2","en":"INSTRUMENTS: the warner becomes a measuring device, and the screen that shows its check takes the same name.","cn":"仪器：告诫者变成测量设备，显示这项检查的屏幕也沿用了同一个名字。"},{"senses":"S3 · S4","en":"PEOPLE: the oldest senses keep a person in the role, either a pupil keeping order or an official who warns.","cn":"人：最古老的义项让一个人留在这个角色里，或是维持秩序的学生，或是提出告诫的官员。"},{"senses":"S5 · S6","en":"WATCHING: the verb checks quantities over time, and when aimed at people it becomes surveillance.","cn":"注视：动词随时间检查数量，而当对象转向人时，它就变成监控。"},{"senses":"S7","en":"LISTENING: a channel is watched with the ears, the earliest verb use of all.","cn":"监听：频道是用耳朵看的，这是所有动词用法中最早的一个。"},{"senses":"S8 · S9 · S10","en":"THE NAME TRAVELS: a lizard fabled to warn, an ironclad built to admonish, and a background program that keeps checking.","cn":"名字远行：传说会预警的蜥蜴、为告诫而造的铁甲舰，以及持续检查的后台程序。"}]},"affixes":{"intro":{"en":"Monitor is a Latin agent noun in -itor built on mon- 'warn'. English adds -ing, -y, -ial and -ship, while the same root also reaches English through admonish, monition, and premonition.","cn":"monitor 是拉丁语中以 -itor 结尾的施动名词，词干 mon- 意为“警告”。英语加上 -ing、-y、-ial 与 -ship，同一词根还通过 admonish、monition、premonition 进入英语。"},"latinIntro":{"en":"The Latin family is monere 'warn, remind', its agent noun monitor, and the action noun monitio 'a warning'. Summon also belongs here: Latin summonere meant 'hint, remind, warn'.","cn":"拉丁语词族包括 monere“警告、提醒”、它的施动名词 monitor，以及行为名词 monitio“警告”。summon 也属于这里：拉丁语 summonere 意为“暗示、提醒、警告”。"},"items":[{"word":"monitor","structure":"mon- (warn) + -itor (agent noun)","meaning":"one who warns or checks; a checking device","meaningCN":"告诫者；检查者；监测设备（mon- 警告 + -itor 施动名词）","example":"The monitor on the wall showed a steady line.","exampleCN":"墙上的监测仪显示出一条平稳的线。"},{"word":"monitoring","structure":"monitor + -ing (noun of process)","meaning":"the act of checking continuously","meaningCN":"监测；监控（-ing 构成过程名词）","example":"The patient was kept under close monitoring.","exampleCN":"病人被置于密切监测之下。"},{"word":"monitory","structure":"monit- + -ory (adjective)","meaning":"serving as a warning","meaningCN":"告诫的；警告的（-ory 构成形容词）","example":"He gave a monitory glance at the noisy table.","exampleCN":"他朝吵闹的那桌投去一个警告的目光。"},{"word":"monitorial","structure":"monitor + -ial (adjective)","meaning":"relating to a monitor or prefect","meaningCN":"级长的；监督的（-ial 构成形容词）","example":"The monitorial duties rotated each week.","exampleCN":"级长职责每周轮换。"},{"word":"admonish","structure":"ad- (to) + mon- (warn) + -ish (verb)","meaning":"to warn or reprimand gently","meaningCN":"告诫；温和地责备（ad- 向 + mon- 警告）","example":"The coach admonished the players for arriving late.","exampleCN":"教练因球员迟到而告诫了他们。"},{"word":"admonition","structure":"ad- + monit- (warning) + -ion","meaning":"a warning or mild reprimand","meaningCN":"告诫；温和的责备","example":"She ignored the admonition and drove faster.","exampleCN":"她无视那句告诫，反而开得更快。"},{"word":"monition","structure":"monit- (warning) + -ion","meaning":"a warning, especially an official one","meaningCN":"警告；正式告诫（-ion 构成名词）","example":"The court issued a monition to the landowner.","exampleCN":"法院向那位土地所有者发出正式警告。"},{"word":"premonition","structure":"pre- (before) + monition (warning)","meaning":"a feeling that something is coming","meaningCN":"预感；事前警告（pre- 在前 + monition 警告）","example":"She had a premonition that the flight would be delayed.","exampleCN":"她预感到那趟航班会延误。"},{"word":"summon","structure":"sum- (secretly, under) + mon- (warn)","meaning":"to call someone to come","meaningCN":"召唤；传唤（sum- 暗中 + mon- 提醒）","example":"The manager summoned the clerk to her office.","exampleCN":"经理把那名职员叫到办公室。"},{"word":"mentor","structure":"Greek Mentor, perhaps from PIE *men- 'to think'","meaning":"a trusted adviser","meaningCN":"导师；可信赖的顾问（同出“思考”词根）","example":"She became a mentor to the younger researchers.","exampleCN":"她成了年轻研究者的导师。"}],"latinEntries":[{"word":"monitor","structure":"monere (warn) + -itor (agent noun)","meaning":"one who warns, reminds, or checks","meaningCN":"告诫者；提醒者；检查者"},{"word":"monere","structure":"PIE *moneie-, causative of *men- 'think'","meaning":"to remind, warn, advise","meaningCN":"提醒；警告；建议"},{"word":"monitio","structure":"monit- (warned) + -io (action noun)","meaning":"a warning, admonition","meaningCN":"警告；告诫"}]}},{"word":"motive","ipa_uk":"/ˈməʊtɪv/","ipa_us":"/ˈmoʊtɪv/","definition_zh":"动机；目的；主题；动力的；推动的","definition_en":"the inner force or reason that makes a person act in a certain way; also an adjective meaning causing or supplying motion","core_image":"一只手从背后推着人往某个方向走","scene":"The detective kept returning to one question: what motive would make a quiet neighbour drive three hours to an empty house?","sceneCN":"这里 motive 是「作案动机」（第 2 个义项：侦查语境中驱使人行动的内在原因）；句意：探长反复回到同一个问题：什么样的动机会让一个安静的邻居开三小时车去一栋空房子？场景要点：一间堆满卷宗的办公室、一张标着三小时车程的地图、一栋没有人的房子。","pos":[{"tag":"n.","zh":"动机；目的；意图；主题"},{"tag":"adj.","zh":"动力的；推动的；引起运动的"}],"collocations":[{"phrase":"ulterior motive","zh":"别有用心；不可告人的动机"},{"phrase":"hidden motive","zh":"隐藏的动机"},{"phrase":"profit motive","zh":"利润动机"},{"phrase":"motive for","zh":"做……的动机"},{"phrase":"mixed motives","zh":"混合动机"},{"phrase":"question someone's motives","zh":"质疑某人的动机"},{"phrase":"political motive","zh":"政治动机"}],"forms":[{"label":"名词复数","form":"motives"}],"derivatives":[{"word":"motivate","pos":"v.","zh":"激励；促使；成为……的动机"},{"word":"motivation","pos":"n.","zh":"动机；积极性；激励"},{"word":"motivational","pos":"adj.","zh":"激励的；动机方面的"},{"word":"motiveless","pos":"adj.","zh":"无动机的；无缘无故的"},{"word":"demotivate","pos":"v.","zh":"使失去动力；使沮丧"},{"word":"motivator","pos":"n.","zh":"激励者；动力因素"}],"senses":[{"no":"01","title":"The push from inside","titleCN":"内在的推动力","definition":"the inner feeling, need, or desire that makes a person choose to act in a particular way","definitionCN":"使人选择以某种方式行动的内在感受、需要或欲望","example":"Her motive was not money but curiosity.","exampleCN":"她的动机不是钱，而是好奇。","why":"Medieval Latin motivus meant 'moving, impelling'. The noun names the moving force inside a person, the push that starts the action before any explanation is given.","whyCN":"中世纪拉丁语 motivus 意为“使移动、推动”。这个名词命名人内部那股推动力，即行动开始、解释尚未给出之前的那一推。"},{"no":"02","title":"A motive in an investigation","titleCN":"侦查中的作案动机","definition":"the reason a person is believed to have committed a crime or a harmful act","definitionCN":"被认为促使某人实施犯罪或伤害行为的那个原因","example":"The police found no motive for the attack.","exampleCN":"警方没有找到这次袭击的动机。","why":"Detectives work backwards from an act to the push that could have produced it. In that setting, motive becomes the hidden spring the whole case must locate.","whyCN":"探员从行为倒推，寻找可能产生它的那一推。在这种语境里，动机变成了整个案件必须找到的那根隐藏的发条。"},{"no":"03","title":"A motive kept out of sight","titleCN":"隐藏的、不可告人的动机","definition":"a real reason for acting that a person does not admit, often because it is self-interested","definitionCN":"一个人不愿承认的真实动因，常因它出于私利","example":"He offered to help, but she suspected an ulterior motive.","exampleCN":"他主动提出帮忙，但她怀疑他别有用心。","why":"If a motive is a push, it can be applied from behind, where no one sees it. The phrase 'ulterior motive' places the push out of sight, beyond the stated reason.","whyCN":"如果动机是一推，它就可以从背后施加，让人看不见。“ulterior motive”这一说法把这一推放到视线之外，越过了明面上说出的理由。"},{"no":"04","title":"The profit motive","titleCN":"利润动机","definition":"the desire for financial gain considered as the force that drives investment and business activity","definitionCN":"把对经济收益的渴望看作驱动投资与商业活动的力量","example":"The profit motive drives most of the investment in the region.","exampleCN":"利润动机驱动着这个地区的大部分投资。","why":"Economics turns the inner push into a system-wide force. When many people are moved by gain, the motive stops being personal and becomes the engine of a market.","whyCN":"经济学把内在的一推变成整个系统的力量。当许多人被收益推动时，动机就不再是个人的，而成了市场的引擎。"},{"no":"05","title":"A motive behind a group act","titleCN":"群体行动背后的动机","definition":"the stated or suspected force behind a collective decision, such as a reform or a policy","definitionCN":"集体决定背后的、被说明或被怀疑的推动力，如改革或政策","example":"The reform was pushed by political motives rather than by evidence.","exampleCN":"推动这项改革的不是证据，而是政治动机。","why":"A group can be pushed too. The word then names whatever moves an assembly, party, or institution, even when no single person's feeling is involved.","whyCN":"群体也会被推动。这时这个词命名的是推动一个议会、政党或机构的东西，即使其中并不涉及某一个人的感受。"},{"no":"06","title":"A musical motive","titleCN":"音乐与艺术中的动机","definition":"a short recurring figure or theme in a piece of music or art, often carrying a meaning","definitionCN":"音乐或艺术作品中反复出现的短小音型或主题，常带有某种含义","example":"The three-note figure returns as a leading motive in the third act.","exampleCN":"那个三音音型在第三幕作为主导动机再次出现。","why":"A motive in music is a small unit that keeps moving through the work, returning and developing. It is a push that carries the listener forward, which is why the same word serves both action and art.","whyCN":"音乐中的动机是一个在作品中不断移动、反复出现并发展的短小单位。它是一股推着听者往前的力量，所以同一个词既用于行动，也用于艺术。"},{"no":"07","title":"Motive in law and morality","titleCN":"法律与道德评价中的动机","definition":"the reason for an act as judged in law or ethics, especially when it affects how the act is evaluated","definitionCN":"在法律或伦理评判中一个行为的原因，尤当它影响对该行为的评价时","example":"The court weighs the motive as well as the act itself.","exampleCN":"法院既衡量行为本身，也衡量其动机。","why":"Law cares where the push came from, not only where it ended. A helping hand moved by kindness and one moved by gain produce similar acts but different judgments, so motive becomes a separate thing to assess.","whyCN":"法律关心这一推从何而来，而不只是它把行为推到了哪里。出于善意的手和出于获利的手做出相似的行为，却得到不同的评判，所以动机成了需要单独评估的东西。"},{"no":"08","title":"Motive power","titleCN":"动力","definition":"in the adjective use, the force that drives a machine or a process, as in 'motive power'","definitionCN":"形容词用法中指驱动机器或过程的力量，如“motive power”","example":"Steam was the motive power of the first factories.","exampleCN":"蒸汽是第一批工厂的动力。","why":"The adjective kept the literal Latin sense 'causing motion'. Steam moves an engine exactly as a desire moves a person, so the same word covers both the mental and the mechanical push.","whyCN":"形容词保留了拉丁语字面的“引起运动”之义。蒸汽推动发动机，正如欲望推动人，所以同一个词同时覆盖心理与机械的推动。"},{"no":"09","title":"Motive force","titleCN":"引起运动的作用力","definition":"in technical or literary use, a force that produces movement, as in 'motive force'","definitionCN":"在技术或文学用法中指产生运动的力量，如“motive force”","example":"Gravity is the motive force behind the landslide.","exampleCN":"重力是这场滑坡背后的作用力。","why":"Here the word is almost physics: whatever makes a body begin to move. The inner push and the physical push are the same picture seen from two sides.","whyCN":"这里这个词几乎属于物理学：任何使物体开始运动的东西。内在的一推与物理的一推，是同一幅画面的两面。"}],"etymology":{"intro":{"en":"Motive comes from Medieval Latin motivus 'moving' through French, and the whole family keeps one image: something that sets a body, or a person, in motion. Dates are approximate.","cn":"motive 经法语来自中世纪拉丁语 motivus“使移动的”，整个词族都保留同一幅画面：某物使一个身体、或一个人开始运动。年代为大致估计。"},"items":[{"era":"LATE 14c. (noun)","en":"The noun first meant 'something brought forward, a proposition, assertion, or argument', a sense now obsolete. It came from Old French motif, a noun use of an adjective literally meaning 'moving'.","cn":"名词最初意为“被提出的东西、命题、主张或论点”，这一义项今已废弃。它来自古法语 motif，是字面意为“移动的”形容词的名词化用法。"},{"era":"MEDIEVAL LATIN motivus","en":"Medieval Latin motivus meant 'moving, impelling'. It came from Latin motus 'a moving, motion', the past participle of movere 'to move'.","cn":"中世纪拉丁语 motivus 意为“使移动的、推动的”。它来自拉丁语 motus“移动、运动”，即 movere“移动”的过去分词。"},{"era":"PIE *meue-","en":"Movere goes back to PIE *meue- 'to push away'. The same root gives motor, emotion, promote, remote, and locomotive.","cn":"movere 可追溯到原始印欧语 *meue-“推开”。同一词根给出 motor、emotion、promote、remote 与 locomotive。"},{"era":"EARLY 15c.","en":"The modern sense, 'that which inwardly moves a person to behave a certain way, a mental state or force which induces an action of volition', is recorded from the early fifteenth century. Hence also 'the design or object one has in any action'.","cn":"现代义“在内部促使人以某种方式行动的东西，即引发意志行动的心理状态或力量”记录于 15 世纪早期。由此也引申出“任何行动中所抱的目的或对象”。"},{"era":"LATE 14c. (adjective)","en":"The adjective meant 'having control of motion, causing motion, having power to move someone or something'. It survives mainly in fixed phrases such as motive power and motive force.","cn":"形容词意为“控制运动的、引起运动的、有能力推动某人或某物的”。它主要存活于 motive power、motive force 这类固定短语中。"},{"era":"MODERN / KIN","en":"Motive and motivation now divide the work: motive is the inner spring itself, while motivation covers the whole process or supply of drive. Reason is the account offered for an act, and incentive is an external lure. Motivate is the verb built on motive.","cn":"motive 与 motivation 如今分工：motive 是那根内在的发条本身，motivation 则覆盖整个激励过程或动力的供给。reason 是为行为给出的解释，incentive 是外部的诱因。motivate 是由 motive 构成的动词。"}]},"similar":{"note":{"en":"The first group separates the verb, the process noun, and the adjective built on motive; the second compares the words learners use when they mean 'why someone acted'.","cn":"第一组把由 motive 构成的动词、过程名词与形容词分开；第二组比较学习者表达“某人为何行动”时混用的几个词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"motivate","ipa":"/ˈməʊtɪveɪt/","tag":"verb","definition":"to give someone a reason or drive to act. It is the act of supplying the push, while motive is the push itself.","definitionCN":"给某人行动的理由或动力。它是提供这一推的动作，而 motive 是这一推本身。"},{"word":"motivation","ipa":"/ˌməʊtɪˈveɪʃn/","tag":"process or supply of drive","definition":"the whole process of being driven to act, or the amount of drive a person has. It is wider than motive: one motive is a specific spring, motivation is the general force or the study of it.","definitionCN":"被驱动去行动的整个过程，或一个人拥有的动力总量。它比 motive 更宽：一个 motive 是一根具体的发条，motivation 是总体力量或对它的研究。"},{"word":"motivational","ipa":"/ˌməʊtɪˈveɪʃənl/","tag":"adjective","definition":"intended to increase someone's drive, as in a motivational speech. It describes the effect on drive, not the reason for a single act.","definitionCN":"旨在增强某人干劲的，如励志演讲。它描述对干劲的效果，而不是某一次行动的原因。"},{"word":"motiveless","ipa":"/ˈməʊtɪvləs/","tag":"adjective: without a motive","definition":"done without any discernible reason. The -less suffix marks the absence of exactly the inner push that motive names.","definitionCN":"没有任何可辨原因的。 -less 后缀标记的正是 motive 所指那根内在发条的缺席。"}]},{"heading":"NEAR MEANING","entries":[{"word":"reason","ipa":"/ˈriːzn/","tag":"explanation offered","definition":"the explanation a person gives for an act, or the grounds that make it intelligible. A motive is the inner push; a reason is the account laid out for others, which may or may not match the motive.","definitionCN":"一个人为行为给出的解释，或使该行为可被理解的理由。motive 是内在的一推；reason 是摆给别人看的说法，它未必与动机相符。"},{"word":"incentive","ipa":"/ɪnˈsentɪv/","tag":"external lure","definition":"something offered from outside, such as a reward, that encourages a person to act. It is the bait in front, while a motive is the push behind.","definitionCN":"从外部提供、鼓励人去行动的东西，如奖励。它是前面的诱饵，而 motive 是背后的推力。"},{"word":"purpose","ipa":"/ˈpɜːpəs/","tag":"intended end","definition":"the result or end a person intends to bring about. Purpose looks forward to what the act is for; motive looks back to what started it.","definitionCN":"一个人打算造成的结果或终点。purpose 向前看行为为了什么；motive 向后看是什么启动了行为。"},{"word":"impulse","ipa":"/ˈɪmpʌls/","tag":"sudden push","definition":"a sudden urge to act, often without deliberation. It is a motive at its most immediate and least reasoned.","definitionCN":"突然的、常未经深思的行动冲动。它是动机最直接、最少经过推理的形态。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Latin movere 'to move', its participle motus, Medieval Latin motivus, and the English family motor, emotion, and motivate.","cn":"只用真实成分与真实同族词：拉丁语 movere“移动”、它的分词 motus、中世纪拉丁语 motivus，以及英语词族 motor、emotion、motivate。"},"normal":[{"en":"movere means 'to move'; motivus means 'moving, impelling'. A motive is the thing that moves a person, seen from inside.","cn":"movere 意为“移动”，motivus 意为“使移动的、推动的”。motive 就是从内部看、推动一个人的那个东西。"},{"en":"The noun first meant 'a proposition brought forward' in the late 1300s; the inner-drive sense is early 1400s.","cn":"名词在 14 世纪晚期最初意为“被提出的命题”；内在驱动义要到 15 世纪早期。"},{"en":"motive, motor, emotion, promote, and locomotive all contain the same 'move' root.","cn":"motive、motor、emotion、promote、locomotive 都含有同一个“移动”词根。"},{"en":"Motivate is the act of supplying a push; motivation is the whole supply or process; motive is one particular spring.","cn":"motivate 是提供一推的动作；motivation 是整体的供给或过程；motive 是某一根具体的发条。"},{"en":"A reason is what you say; a motive is what pushed you. The two can differ, which is why detectives distrust stated reasons.","cn":"reason 是你说出来的，motive 是推你的那股力。两者可以不一致，所以探员不轻信口头理由。"}],"abstract":[{"en":"Picture a hand between someone's shoulder blades, pushing. The person moves forward, but the hand is behind and unseen.","cn":"想象一只手按在某人肩胛之间向前推。人往前走了，而那只手在背后，看不见。"},{"en":"An incentive is a coin held out in front; a motive is the hand behind. A person can be led by either, or by both at once.","cn":"incentive 是举在前面的一个硬币；motive 是背后的那只手。人可能被其中任何一个引导，也可能同时被两者引导。"},{"en":"In music the same push becomes a few notes that keep returning, moving the piece forward each time they sound.","cn":"在音乐里，同一股推力变成几个不断回来的音符，每次响起都把作品往前推一段。"}]},"examples":[{"en":"No one could explain the motive behind the anonymous donation.","cn":"没有人能解释这笔匿名捐款背后的动机。"},{"en":"The profit motive can build a railway and also abandon a town.","cn":"利润动机可以修起一条铁路，也可以抛下一座城镇。"},{"en":"The court found that his motive was fear, not hatred.","cn":"法院认定他的动机是恐惧，而不是仇恨。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“莫替吾”——莫替吾拿主意，吾自有推吾向前的那股劲 → motive 动机（只借音，不表词源）","word":"motive"},"root":"源自拉丁语 movere“移动”的派生形式 motivus“使移动的”，核心是“从背后推动人行动的那股力”。","sensesIntro":{"en":"Nine senses of motive, all from one hand pushing from behind: the force may be hidden or admitted, personal or collective, mental or mechanical, but it always sets something in motion.","cn":"motive 的九个义项都来自背后那只推动的手：这股力可以隐藏或明说，可以属于个人或群体，可以是心理的或机械的，但它总使某物开始运动。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand pushing a person forward from behind.","cn":"核心意象：一只手从背后把人向前推。"},"chain":["A PUSH","A PERSON MOVED","AN ACT CHOSEN","A REASON SOUGHT","A FORCE NAMED","A PATTERN REPEATED"],"branches":[{"senses":"S1 · S6","en":"INNER SPRING: the push is felt from inside a person, and in art the same push becomes a recurring figure that moves the work along.","cn":"内在发条：这一推从人的内部被感受到；在艺术中，同一股推力变成反复出现的音型，把作品往前带。"},{"senses":"S2 · S3","en":"HIDDEN AND HUNTED: detectives search for the push behind a crime, and an ulterior motive is the same push kept out of sight.","cn":"隐藏与被追查：探员寻找罪行背后的那一推，而别有用心就是同一推被藏在视线之外。"},{"senses":"S4 · S5","en":"COLLECTIVE FORCES: profit moves a market, and political motives move a reform or a party.","cn":"集体力量：利润推动市场，政治动机推动改革或政党。"},{"senses":"S7","en":"JUDGMENT: law and ethics ask where the push came from, because origin changes the value of the act.","cn":"评判：法律与伦理追问这一推从何而来，因为来源会改变行为的价值。"},{"senses":"S8 · S9","en":"MECHANICAL PUSH: the adjective keeps the literal sense, naming steam, gravity, or any force that starts motion.","cn":"机械推动：形容词保留字面义，命名蒸汽、重力或任何使运动开始的力量。"}]},"affixes":{"intro":{"en":"Motive is a Latin-derived adjective in -ive built on the 'move' stem mot-. The same stem, with e-, pro-, re-, and -or, builds emotion, promote, remote, and motor.","cn":"motive 是拉丁语来源、以 -ive 结尾的形容词，词干 mot- 意为“移动”。同一词干加上 e-、pro-、re- 与 -or，构成 emotion、promote、remote 与 motor。"},"latinIntro":{"en":"The Latin base is movere 'to move', with its participle motus and the Medieval Latin adjective motivus. The family is large because 'move' is one of the oldest and most productive ideas in the language.","cn":"拉丁语词基是 movere“移动”，另有其分词 motus 与中世纪拉丁语形容词 motivus。这个词族庞大，因为“移动”是语言中最古老、最能产出的观念之一。"},"items":[{"word":"motive","structure":"mot- (move) + -ive (adjective/noun)","meaning":"a moving force; an inner reason","meaningCN":"推动力；内在动机（mot- 移动 + -ive 形容词或名词后缀）","example":"The motive for the trip was to see his father.","exampleCN":"这趟旅行的动机是去看他父亲。"},{"word":"motivate","structure":"motive + -ate (verb)","meaning":"to supply a reason or drive","meaningCN":"激励；促使（-ate 构成动词）","example":"Good teachers motivate students to ask questions.","exampleCN":"好老师激励学生提问。"},{"word":"motivation","structure":"motivate + -ion (noun)","meaning":"the process or strength of being driven","meaningCN":"动机；积极性（-ion 构成名词）","example":"Her motivation fell after the third rejection.","exampleCN":"第三次被拒之后，她的积极性下降了。"},{"word":"motivational","structure":"motivation + -al (adjective)","meaning":"intended to raise someone's drive","meaningCN":"激励的（-al 构成形容词）","example":"He gives a motivational talk every Monday.","exampleCN":"他每周一做一次励志演讲。"},{"word":"motiveless","structure":"motive + -less (without)","meaning":"done without any discernible reason","meaningCN":"无动机的（-less 表没有）","example":"The novel describes a motiveless crime.","exampleCN":"这部小说描写了一桩没有动机的罪行。"},{"word":"motor","structure":"mot- (move) + -or (agent)","meaning":"one who or that which imparts motion","meaningCN":"发动机；马达（mot- 移动 + -or 施动者）","example":"The small motor turns the fan.","exampleCN":"这个小马达带动风扇。"},{"word":"emotion","structure":"e- (out) + motion (movement)","meaning":"a feeling that moves a person","meaningCN":"情感；情绪（e- 向外 + motion 运动）","example":"The speech stirred a strong emotion in the crowd.","exampleCN":"这番讲话在人群中激起强烈的情绪。"},{"word":"promote","structure":"pro- (forward) + mot- (move)","meaning":"to move something forward; to advance","meaningCN":"促进；提升（pro- 向前 + mot- 移动）","example":"The campaign promotes local farmers.","exampleCN":"这场活动推广本地农户。"},{"word":"remote","structure":"re- (back) + mot- (move)","meaning":"moved far away; distant","meaningCN":"遥远的；偏僻的（re- 向后 + mot- 移动）","example":"They live in a remote village without a bus.","exampleCN":"他们住在一个没有公交的偏远村庄。"},{"word":"locomotive","structure":"loco (from a place) + motive (moving)","meaning":"a railway engine that moves itself","meaningCN":"机车；火车头（loco 从某地 + motive 移动的）","example":"The old locomotive still runs on weekends.","exampleCN":"那台老机车周末仍在运行。"},{"word":"movement","structure":"move + -ment (noun)","meaning":"the act of moving, or an organized campaign","meaningCN":"移动；运动（-ment 构成名词）","example":"A slow movement of the crowd began near the gate.","exampleCN":"人群在门口附近开始缓慢移动。"}],"latinEntries":[{"word":"motivus","structure":"motus (moved) + -ivus (adjective)","meaning":"moving, impelling","meaningCN":"使移动的；推动的（motus 移动 + -ivus 形容词后缀）"},{"word":"movere","structure":"PIE *meue- 'to push away'","meaning":"to move","meaningCN":"移动；推动"},{"word":"motus","structure":"past participle of movere","meaning":"a moving, motion","meaningCN":"移动；运动（movere 的过去分词）"}]}}]);
